CARDIO.register({"item":"225","meta":{"num":225,"short":"AOMI / anévrismes","title":"Artériopathie de l'aorte, des artères viscérales et des membres inférieurs ; anévrismes","section":"I","chapter":7,"pages":"164-190","sdd":[{"num":3,"label":"Distension abdominale"},{"num":4,"label":"Douleur abdominale"},{"num":15,"label":"Anomalies de couleur des extrémités"},{"num":19,"label":"Découverte d'un souffle vasculaire"},{"num":30,"label":"Dénutrition/malnutrition"},{"num":42,"label":"Hypertension artérielle"},{"num":63,"label":"Troubles sexuels et troubles de l'érection"},{"num":66,"label":"Apparition d'une difficulté à la marche"},{"num":68,"label":"Boiterie"},{"num":69,"label":"Claudication intermittente d'un membre"},{"num":71,"label":"Douleur d'un membre (supérieur ou inférieur)"},{"num":92,"label":"Ulcère cutané"},{"num":195,"label":"Analyse du bilan lipidique"},{"num":231,"label":"Demande d'un examen d'imagerie"},{"num":232,"label":"Demande d'explication d'un patient sur le déroulement, les risques et les bénéfices attendus d'un examen d'imagerie"},{"num":248,"label":"Prescription et suivi d'un traitement par anticoagulant et/ou antiagrégant"},{"num":252,"label":"Prescription d'un hypolipémiant"},{"num":259,"label":"Évaluation et prise en charge de la douleur aiguë"},{"num":260,"label":"Évaluation et prise en charge de la douleur chronique"},{"num":271,"label":"Prescription et surveillance d'une voie d'abord vasculaire"},{"num":281,"label":"Prescription médicamenteuse, consultation de suivi et éducation d'un patient diabétique de type 2 ou ayant un diabète secondaire"},{"num":282,"label":"Prescription médicamenteuse, consultation de suivi et éducation d'un patient hypertendu"},{"num":300,"label":"Consultation pré-anesthésique"},{"num":314,"label":"Prévention des risques liés au tabac"},{"num":328,"label":"Annonce d'une maladie chronique"}]},"objectives":[{"id":"225-obj-01","rank":"A","rubric":"Définition","title":"Définition et fréquence de l'AOMI","desc":"Connaître la définition et la fréquence de l'artériopathie oblitérante des membres inférieurs (AOMI)."},{"id":"225-obj-02","rank":"B","rubric":"Physiopathologie","title":"Étiologie et facteurs de risque de l'AOMI","desc":"Connaître l'étiologie et les facteurs de risque de l'AOMI."},{"id":"225-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Manifestations cliniques et classification de l'AOMI","desc":"Connaître les manifestations cliniques et la classification de l'AOMI et savoir évoquer les diagnostics différentiels."},{"id":"225-obj-04","rank":"A","rubric":"Examens complémentaires","title":"Examens complémentaires de 1re intention de l'AOMI","desc":"Savoir prescrire les examens complémentaires de 1re intention."},{"id":"225-obj-05","rank":"A","rubric":"Prise en charge","title":"Traitement médical et principes du traitement chirurgical de l'AOMI","desc":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical."},{"id":"225-obj-06","rank":"A","rubric":"Suivi et/ou pronostic","title":"Complications et pronostic de l'AOMI","desc":"Connaître les complications et le pronostic : ischémie aiguë des membres inférieurs, morbimortalité cardiovasculaire."},{"id":"225-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Manifestations cliniques de l'ischémie aiguë de membre","desc":"Savoir définir et identifier les manifestations cliniques d'ischémie aiguë complète ou incomplète."},{"id":"225-obj-08","rank":"B","rubric":"Étiologies","title":"Autres causes de l'ischémie aiguë","desc":"Connaître les autres causes de l'ischémie aiguë."},{"id":"225-obj-09","rank":"A","rubric":"Identifier une urgence","title":"Principes du traitement en urgence de l'ischémie aiguë","desc":"Connaître les principes d'un traitement en urgence."},{"id":"225-obj-10","rank":"A","rubric":"Définition","title":"Définition et histoire naturelle de l'anévrisme de l'aorte abdominale","desc":"Connaître la définition et l'histoire naturelle d'un anévrisme de l'aorte abdominale et savoir rechercher d'autres localisations anévrismales."},{"id":"225-obj-11","rank":"B","rubric":"Étiologies","title":"Étiologies des anévrismes de l'aorte abdominale et dépistage","desc":"Connaître les principales étiologies des anévrismes de l'aorte abdominale et les principes du dépistage."},{"id":"225-obj-12","rank":"A","rubric":"Diagnostic positif","title":"Signes cliniques des anévrismes de l'aorte","desc":"Connaître les signes cliniques des anévrismes de l'aorte."},{"id":"225-obj-13","rank":"A","rubric":"Examens complémentaires","title":"Diagnostic des anévrismes de l'aorte abdominale","desc":"Savoir comment faire le diagnostic des anévrismes de l'aorte abdominale."},{"id":"225-obj-14","rank":"B","rubric":"Prise en charge","title":"Principes thérapeutiques de l'anévrisme de l'aorte abdominale","desc":"Connaître les principes thérapeutiques d'un anévrisme de l'aorte abdominale."},{"id":"225-obj-15","rank":"A","rubric":"Identifier une urgence","title":"Urgence chez le porteur d'un anévrisme de l'aorte abdominale","desc":"Savoir reconnaître et prendre en charge une situation d'urgence chez les patients porteurs d'un anévrisme de l'aorte abdominale."},{"id":"225-obj-16","rank":"A","rubric":"Définition","title":"Définition de l'ischémie intestinale aiguë et chronique","desc":"Connaître la définition de l'ischémie intestinale aiguë et chronique."},{"id":"225-obj-17","rank":"A","rubric":"Diagnostic positif","title":"Sémiologie de l'ischémie intestinale aiguë et chronique","desc":"Connaître la sémiologie de l'ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques."}],"course":{"sections":[{"id":"225-sec-01","title":"Aorte et artères viscérales : athérome et ischémies mésentériques","rank":"A","objectives":["225-obj-16","225-obj-17"],"content":"**Athérome aortique** : des plaques peuvent toucher tous les segments de l'aorte dès un âge jeune, avec une prédilection pour la bifurcation aortique et l'origine des branches (coronaires, digestives, rénales). Le tabagisme est le facteur le plus associé. Le plus souvent asymptomatiques et de découverte fortuite à l'imagerie, elles peuvent se compliquer d'embolies (cerveau, membres, viscères) ; leur présence marque un sur-risque cardiovasculaire global.\n\n> L'athérome des artères rénales peut engendrer une HTA rénovasculaire par activation du système rénine-angiotensine-aldostérone.\n\n**Ischémie mésentérique chronique** : sténose du tronc cœliaque et/ou des artères mésentériques, souvent asymptomatique. Quand elle est symptomatique, elle réalise un *angor digestif* : douleurs abdominales postprandiales pouvant conduire à une restriction alimentaire, un amaigrissement et une dénutrition. Un souffle abdominal peut être perçu. Diagnostic par écho-Doppler digestif, angioscanner ou angio-IRM (l'artériographie n'est réalisée que pour un geste endovasculaire). Traitement : revascularisation, de préférence endovasculaire.\n\n**[A] Ischémie mésentérique aiguë** : occlusion brutale d'une artère digestive (thrombose in situ ou embolie), urgence vitale rare grâce aux collatérales. Triade évocatrice : douleur abdominale aiguë pauvre en signes physiques, vidange digestive accélérée (vomissements/diarrhée), arguments emboligènes (fibrillation atriale). Le diagnostic est confirmé par l'angioscanner. Traitement : résection des segments intestinaux infarcis associée à une revascularisation (endovasculaire ou chirurgicale).","keyPoints":["L'athérome peut toucher tous les segments de l'aorte, avec des sièges préférentiels aux bifurcations.","L'ischémie mésentérique chronique se traduit par un angor digestif postprandial.","L'échodoppler digestif, l'angioscanner ou l'angio-IRM confirment la sténose viscérale.","L'ischémie mésentérique aiguë associe douleur abdominale, vidange digestive accélérée et contexte emboligène.","L'angioscanner confirme le diagnostic d'ischémie mésentérique aiguë.","Le traitement de l'ischémie mésentérique aiguë associe résection intestinale et revascularisation en urgence."],"pitfalls":["Ne pas se laisser rassurer par un examen abdominal pauvre : la douleur aiguë avec paucité de signes physiques fait partie de la triade.","Ne pas confondre la forme chronique (angor digestif, prise en charge programmée) et la forme aiguë (urgence vitale)."],"src":"p. 166-167, 187"},{"id":"225-sec-02","title":"AOMI : généralités, épidémiologie et facteurs de risque","rank":"A","objectives":["225-obj-01","225-obj-02"],"content":"**[A] Définition** : l'AOMI regroupe toute atteinte athéromateuse significative touchant les artères entre l'aorte terminale et les artères digitales. Les lésions sont comparables à celles des autres territoires athéromateux.\n\n**Épidémiologie** : après le cœur et le cerveau, l'AOMI est la 3e localisation de l'athérosclérose. Elle touche plus souvent l'homme, avec un pic de survenue symptomatique entre 60-75 ans chez l'homme et 70-80 ans chez la femme. Sa prévalence clinique varie de 1 à 5 % après 60 ans, et atteint 10-15 % si l'on intègre les formes infracliniques : pour un cas clinique, 2 à 4 patients ont une forme infraclinique, ce qui justifie un dépistage ciblé.\n\n**[B] Facteurs de risque** : le tabagisme (plus fréquent chez le sujet jeune) et le diabète (associé à des formes distales plus graves) sont les deux principaux facteurs de risque. L'hypercholestérolémie et l'hypertension artérielle sont également fréquemment associées à l'AOMI.","keyPoints":["L'AOMI correspond à une atteinte athéromateuse entre l'aorte terminale et les artères digitales.","C'est la 3e localisation de l'athérosclérose après les atteintes coronarienne et cérébrale.","Le tabac et le diabète sont les deux premiers facteurs de risque de l'AOMI.","Le diabète favorise des formes plus distales et de moins bon pronostic.","Pour chaque cas clinique d'AOMI, il existe 2 à 4 formes infracliniques associées."],"pitfalls":["Ne pas sous-estimer l'AOMI infraclinique, beaucoup plus fréquente que la forme symptomatique."],"src":"p. 167-168"},{"id":"225-sec-03","title":"AOMI : manifestations cliniques et stades","rank":"A","objectives":["225-obj-03"],"content":"Longtemps asymptomatique grâce au développement d'une circulation collatérale, l'AOMI se manifeste d'abord à l'effort (**ischémie d'effort**) puis, à un stade plus avancé, au repos (**ischémie permanente**).\n\n**Classifications** (à connaître) :\n\n| Leriche-Fontaine | Symptômes | Rutherford (grade/catégorie) | Symptômes |\n|---|---|---|---|\n| I | Asymptomatique | 0/0 | Asymptomatique |\n| II | Claudication intermittente | I/1-3 | Claudication légère à sévère |\n| III | Douleur ischémique de repos | II/4 | Douleur ischémique de repos |\n| IV | Ulcération ou gangrène | III/5-6 | Perte de substance faible à majeure |\n\n**Claudication intermittente** : crampe du mollet à la marche, cédant en moins de 5 minutes à l'arrêt ; sévère si la distance de marche est < 100 m. Formes atypiques fréquentes (variabilité, localisation fessière/cuisse par atteinte aorto-iliaque, paresthésies, ralentissement du pas). Le **syndrome de Leriche** associe atteinte aorto-iliaque, claudication fessière et troubles de l'érection. Une atteinte sévère peut rester masquée (collatéralité, comorbidités limitant la marche, neuropathie).\n\n**Ischémie permanente** (stades III-IV) : douleurs de décubitus soulagées en position déclive, durant plus de 15 jours en cas d'ischémie critique (pression de cheville < 50 mmHg ou d'hallux < 30 mmHg) ; troubles trophiques (peau fine, ulcères aux zones d'appui, gangrène des orteils, plus fréquente chez le diabétique).\n\nL'interrogatoire recherche systématiquement les autres atteintes athéromateuses (angor, AVC).","keyPoints":["La maladie évolue de l'asymptomatique vers l'ischémie d'effort puis l'ischémie permanente.","La claudication est sévère si la distance de marche est < 100 m et cède en < 5 minutes.","Le syndrome de Leriche associe claudication fessière, atteinte aorto-iliaque et troubles de l'érection.","L'ischémie critique correspond à une pression de cheville < 50 mmHg ou d'hallux < 30 mmHg.","Les troubles trophiques (ulcères, gangrène) définissent le stade IV et sont plus fréquents chez le diabétique."],"pitfalls":["Une AOMI sévère peut être masquée chez le sujet âgé peu mobile ou neuropathe : toujours vérifier que le patient marche réellement.","Ne pas confondre claudication artérielle et claudication veineuse ou neurogène (canal lombaire étroit)."],"src":"p. 168-170"},{"id":"225-sec-04","title":"AOMI : examen clinique, index de pression systolique et examens complémentaires","rank":"A","objectives":["225-obj-04"],"content":"**Examen physique**, toujours bilatéral et comparatif : inspection (couleur, troubles trophiques), palpation (froideur, recherche des pouls fémoral, poplité, tibial postérieur et pédieux — ce dernier absent congénitalement chez 5 % des sujets —, temps de recoloration cutanée normalement < 3 secondes), auscultation des trajets vasculaires, palpation abdominale et poplitée à la recherche d'un anévrisme.\n\n**Index de pression systolique (IPS)** : rapport pression systolique de cheville / pression systolique brachiale, mesuré au doppler de poche.\n\n> Normal : 1,00-1,40 · AOMI si < 0,90 (au moins une cheville) · AOMI sévère si < 0,70 · Médiacalcose si > 1,40 (remplacer par l'index de pression d'orteil, pathologique si < 0,70 ; pression d'orteil < 30 mmHg = ischémie critique).\n\nL'IPS est aussi un marqueur de risque cardiovasculaire général lorsqu'il est abaissé. En cas de symptômes avec IPS de repos normal, un **test de marche** (tapis roulant, protocole de Strandness : 3,2 km/h, pente 10 %) sensibilise le diagnostic : une baisse de pression de cheville > 30 mmHg ou de l'IPS > 20 % après l'effort est évocatrice d'AOMI. Le test de marche de 6 minutes évalue le handicap fonctionnel global (non spécifique).\n\n**TcPO2** (pression transcutanée en oxygène, après hyperémie) : utile pour l'ischémie critique — normale > 50 mmHg au dos du pied ; > 35 mmHg = bonne compensation ; 10-35 mmHg = hypoxie continue ; < 10 mmHg = hypoxie critique.\n\n**Imagerie** : l'**échodoppler artériel** est l'examen de 1re intention (non invasif, localise et quantifie les sténoses). L'**angioscanner** et l'**angio-IRM** (sensibilité/spécificité ≈ 95 % vs artériographie) ne sont demandés qu'en vue d'une revascularisation ; l'angio-IRM (gadolinium contre-indiqué si clairance < 30 mL/min/1,73 m²) ne visualise pas les calcifications, utiles au chirurgien. L'**artériographie** est aujourd'hui réservée aux procédures de revascularisation, notamment pour le réseau jambier et pédieux.","keyPoints":["L'IPS est le premier examen devant une suspicion d'AOMI : pathologique si < 0,90, sévère si < 0,70.","Un IPS > 1,40 signe une médiacalcose ; il faut alors mesurer la pression d'orteil.","Le test de marche démasque une AOMI à IPS de repos normal (baisse de pression > 30 mmHg ou d'IPS > 20 %).","L'échodoppler artériel des membres inférieurs est l'examen de 1re intention pour localiser les lésions.","L'angioscanner, l'angio-IRM et l'artériographie ne sont utiles qu'en vue d'une revascularisation.","La TcPO2 aide à évaluer l'ischémie critique."],"pitfalls":["Chez le diabétique, l'insuffisant rénal ou le sujet très âgé, un IPS normal n'élimine pas l'AOMI (médiacalcose) : demander une pression d'orteil.","Ne pas prescrire d'angioscanner ou d'artériographie en dehors d'un projet de revascularisation."],"src":"p. 170-173"},{"id":"225-sec-05","title":"AOMI : diagnostics différentiels et étiologiques","rank":"B","objectives":["225-obj-02","225-obj-03"],"content":"**Diagnostics différentiels** selon le tableau clinique :\n\n- Douleurs à la marche : neurologique (canal lombaire étroit, sciatalgie, atteinte médullaire), rhumatologique (tendinite, arthrose), veineuse (claudication post-thrombotique), piège ou kyste poplité, endofibrose iliaque, syndrome des loges, malformations vasculaires, douleurs musculaires sous statines.\n- Douleurs de décubitus : neuropathie sensorielle, syndromes douloureux régionaux complexes, compression radiculaire.\n- Ulcères : veineux, microcirculatoire, neuropathique, traumatique.\n\n**[B] Diagnostic étiologique** : l'AOMI (origine athéromateuse) représente plus de 95 % des artériopathies oblitérantes des membres inférieurs. Les artériopathies non athéromateuses restent rares : artériopathies inflammatoires (Buerger, Takayasu, Horton, collagénoses), dysplasie fibromusculaire, coarctation de l'aorte, atteintes postradiques, post-traumatiques, toxiques (dérivés de l'ergot de seigle), gelures, compressions extrinsèques, atteintes spécifiques de l'artère poplitée (piège poplité, kyste sous-adventiciel).","keyPoints":["Plusieurs causes de douleur de jambe à la marche coexistent souvent chez le sujet âgé : penser au canal lombaire étroit et à la claudication veineuse.","Les douleurs musculaires sous statines peuvent mimer une claudication artérielle.","Plus de 95 % des AOMI sont d'origine athéromateuse.","Les artériopathies inflammatoires (Buerger, Takayasu, Horton) et la dysplasie fibromusculaire sont des causes non athéromateuses à connaître."],"pitfalls":["Chez un sujet jeune sans facteur de risque cardiovasculaire, évoquer une cause non athéromateuse (Buerger, dysplasie fibromusculaire)."],"src":"p. 174"},{"id":"225-sec-06","title":"AOMI : traitement et pronostic","rank":"A","objectives":["225-obj-05","225-obj-06"],"content":"**Traitement à visée générale** (tous les stades) :\n\n- Contrôle des facteurs de risque : arrêt du tabac, équilibre du diabète (HbA1c < 7 %), objectifs tensionnels (PAS 120-129 mmHg, PAD 70-79 mmHg), LDL-cholestérol < 0,55 g/L (< 1,4 mmol/L) avec réduction ≥ 50 % sous **statine** systématique, IMC cible 20-25 kg/m², régime méditerranéen, réentraînement 3 fois/semaine pendant 12 semaines.\n- **Antiplaquettaire** (aspirine ou clopidogrel) indiqué chez tout AOMI symptomatique ; discuté si asymptomatique isolée.\n- **IEC** utile sur le plan pronostique (cible PA < 140/90 mmHg) ; **bêtabloquants** possibles si indication formelle (cardiopathie ischémique, insuffisance cardiaque), prudence en ischémie critique non revascularisable.\n\n**Traitement à visée locale** :\n\n- Arrêt du tabac et marche régulière (30-45 min, ≥ 3 fois/semaine), idéalement en réadaptation supervisée + éducation thérapeutique.\n- Traitements vasoactifs (ex. pentoxifylline) : bénéfice modeste sur le périmètre de marche, sans effet pronostique. Prostaglandines possibles en ischémie critique non revascularisable.\n- **[A] Revascularisation** systématiquement proposée en cas d'ischémie permanente ; discutée en cas de claudication sévère invalidante (périmètre < 100 m), notamment après échec du traitement médical bien conduit : angioplastie endovasculaire (± stent, bithérapie antiplaquettaire 1-6 mois) pour les lésions courtes/proximales, ou chirurgie (pontage veineux ou prothétique, endartériectomie) pour les lésions étendues ; techniques hybrides possibles. Surveillance clinique et écho-Doppler systématique après le geste.\n- Soins de plaies multidisciplinaires ; **amputation** en dernier recours (zone saine et bien oxygénée, guidée par la TcPO2).\n\n**Pronostic** : grave, comparable à certains cancers en ischémie permanente. Chez le claudicant : espérance de vie réduite d'environ 10 ans, et à 5 ans, 20 % de complications cardiovasculaires, 20 % de décès (pour moitié cardiovasculaires), 25 % d'aggravation locale (dont 1/5 d'amputation majeure) et environ 5 % de risque d'amputation. En ischémie critique, la mortalité à 5 ans avoisine 70 %.","keyPoints":["Le contrôle des facteurs de risque et l'antiagrégant plaquettaire s'appliquent à tout AOMI symptomatique.","Cibles : LDL < 0,55 g/L (réduction ≥ 50 %), HbA1c < 7 %, PA ≤ 120-129/70-79 mmHg.","La revascularisation est systématique en cas d'ischémie permanente.","La marche supervisée est le traitement de 1re ligne de la claudication non invalidante.","L'amputation est le geste ultime en l'absence de possibilité de revascularisation.","Le pronostic est grave : mortalité à 5 ans d'environ 70 % en ischémie critique."],"pitfalls":["Ne pas négliger le bilan et le traitement des autres atteintes athéromateuses (coronaire, carotidienne) chez tout patient AOMI."],"src":"p. 175-178"},{"id":"225-sec-07","title":"Ischémie aiguë des membres inférieurs : physiopathologie et diagnostic clinique","rank":"A","objectives":["225-obj-07"],"content":"**Définition** : interruption brutale du flux artériel d'un membre, urgence vasculaire pouvant menacer le membre et le pronostic vital.\n\n**Physiopathologie** : la gravité dépend de la pression artérielle systémique, de l'abondance de la collatéralité et de la qualité du lit d'aval. Les cellules nerveuses souffrent dès 2 heures, les cellules musculaires dès 6-8 heures (rhabdomyolyse). L'œdème musculaire dans les loges aponévrotiques inextensibles peut aboutir à un **syndrome des loges**, traité par aponévrotomie de décharge. La nécrose cutanée apparaît vers la 24e heure. À la reperfusion, le relargage d'acides et de radicaux libres (**syndrome de revascularisation**) peut provoquer hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie/myoglobinurie, hypocalcémie, hyperphosphorémie, voire CIVD, et une insuffisance rénale aiguë (nécrose tubulaire).\n\n**Diagnostic clinique** : douleur brutale intense à type de broiement avec impotence fonctionnelle ; membre froid, livide, douloureux à la palpation musculaire, pouls abolis en aval, troubles neurologiques (anesthésie, paralysie, notamment du nerf fibulaire commun). L'occlusion de la bifurcation aortique donne une ischémie bilatérale sévère pouvant aller jusqu'au collapsus.\n\n**Classification de sévérité de Rutherford** (recommandations ESC 2024) :\n\n| Grade | Catégorie | Déficit sensitif | Déficit moteur | Pronostic |\n|---|---|---|---|---|\n| I | Viable | Absent | Absent | Pas de menace immédiate |\n| IIa | Discrètement menaçante | Absent ou limité aux orteils | Absent | Récupérable si prise en charge |\n| IIb | Immédiatement menaçante | Présent au-delà des orteils | Modéré | Récupération possible si urgence immédiate |\n| III | Irréversible | Anesthésie importante | Important, paralysie | Perte tissulaire et séquelles inévitables |\n\n**Diagnostic paraclinique** : purement clinique en pratique ; aucune exploration ne doit retarder l'intervention, surtout en cas de déficit neurologique (grade II). Un échodoppler peut être réalisé sans perte de temps si le tableau le permet (grade I sans atteinte neurologique). L'artériographie est le plus souvent faite au bloc pour guider le geste (localisation, aspect de l'occlusion, qualité du réseau d'aval) et dépister d'autres emboles.","keyPoints":["L'ischémie aiguë de membre est une urgence vasculaire mettant en jeu le membre et parfois le pronostic vital.","Les cellules nerveuses souffrent dès 2 h, les cellules musculaires dès 6-8 h.","Le syndrome des loges se traite par aponévrotomie de décharge.","Le diagnostic est clinique : douleur, froideur, pâleur, abolition des pouls, troubles neurologiques.","La classification de Rutherford (I, IIa, IIb, III) guide le degré d'urgence.","Aucun examen ne doit retarder la revascularisation en cas de déficit neurologique."],"pitfalls":["Ne jamais retarder la prise en charge par des examens complémentaires en cas de grade II (déficit sensitif).","Le syndrome de revascularisation peut être aussi dangereux que l'ischémie elle-même (hyperkaliémie, acidose)."],"src":"p. 178-180"},{"id":"225-sec-08","title":"Ischémie aiguë des membres inférieurs : étiologies","rank":"B","objectives":["225-obj-08"],"content":"Deux grands tableaux étiologiques s'opposent, bien qu'ils ne soient pas toujours totalement distincts.\n\n**Thrombose artérielle in situ** : sujet âgé, facteurs de risque cardiovasculaire, souvent AOMI préexistante (à rechercher sur l'autre membre) ; douleur d'intensité moyenne, d'installation progressive ou rapide grâce à la collatéralité préalable. Causes : AOMI, artériopathies non athéromateuses, anévrisme poplité thrombosé, déshydratation/hémoconcentration du sujet âgé, kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies, causes iatrogènes (cathétérisme, thrombopénie à l'héparine, ergotisme).\n\n**Embolie sur artères saines** : sujet plus jeune, sans antécédent vasculaire (cardiopathie possible) ; douleur brutale, aiguë et sévère (absence de collatérales), parfois précédée de palpitations. Causes cardiaques (fibrillation atriale, foramen ovale perméable/anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome de l'atrium, anévrisme/dyskinésie du VG) ou aortiques (athérome, anévrisme, aortite, tumeur).\n\n**[A] Bilan étiologique systématique** : auscultation cardiaque, ECG, palpation abdominale (anévrisme), bilan de coagulation ; puis, après revascularisation : bilan cardiaque (Holter, ETT ± ETO/IRM) et bilan artériel (échodoppler, angioscanner ou artériographie).","keyPoints":["La thrombose in situ touche typiquement un sujet âgé déjà artériopathe.","L'embolie touche un sujet plus jeune sur artères saines, souvent d'origine cardiaque (fibrillation atriale en tête).","Le bilan étiologique inclut systématiquement ECG, auscultation cardiaque, palpation abdominale et bilan de coagulation.","Les deux tableaux peuvent se superposer chez un même patient."],"pitfalls":["Ne pas oublier de rechercher une fibrillation atriale ou un anévrisme aortique devant toute ischémie aiguë de membre.","Une embolie peut survenir sur des artères déjà artériopathes, et une thrombose in situ sur des artères initialement saines."],"src":"p. 181-182"},{"id":"225-sec-09","title":"Ischémie aiguë des membres inférieurs : traitement","rank":"A","objectives":["225-obj-09"],"content":"**Traitement médical immédiat** : anticoagulation par héparine non fractionnée (bolus 5000 UI puis perfusion continue 500 UI/kg/j, TCA cible entre 2 et 3) dès le diagnostic, après le prélèvement du bilan de coagulation ; antalgiques de palier 3 souvent nécessaires ; oxygénothérapie ; correction hémodynamique (remplissage) ; soins locaux immédiats (protection, position légèrement déclive), y compris après revascularisation.\n\n**Revascularisation**, adaptée au grade de sévérité :\n\n- **Embolectomie à la sonde de Fogarty** sous contrôle angiographique : méthode de référence pour l'embolie sur artère saine (utilisable aussi sur artère athéromateuse).\n- **Thrombolyse in situ / thromboaspiration** : si lit d'aval de mauvaise qualité et ischémie peu sévère (surveillance spécialisée, contrôles angiographiques répétés).\n- Angioplastie complémentaire en cas de sténose résiduelle ; pontage (souvent distal) en dernier recours.\n- **Aponévrotomie de décompression** (loge antéro-externe de jambe en général) systématique en cas de revascularisation tardive, pour prévenir le syndrome des loges.\n- **Amputation** d'emblée si ischémie dépassée, ou secondairement en cas d'échec de revascularisation / désordres métaboliques majeurs.\n\n**Prise en charge des conséquences métaboliques** : surveillance de la diurèse (sonde urinaire), ionogramme, urée, créatininémie, CPK ; correction de l'acidose (bicarbonates IV) et de l'hyperkaliémie (chélateur type polystyrène sulfonate de sodium, voire dialyse), lavage de membre au sérum physiologique.\n\n**À distance** : traitement étiologique (anticoagulation au long cours si fibrillation atriale ; antiplaquettaire et contrôle des facteurs de risque si origine thrombotique).","keyPoints":["L'héparine non fractionnée (bolus 5000 UI puis 500 UI/kg/j, TCA 2-3) est débutée dès le diagnostic.","L'embolectomie à la sonde de Fogarty est le traitement de référence de l'embolie sur artère saine.","Une aponévrotomie de décharge est systématique en cas de revascularisation tardive.","Les troubles métaboliques de la reperfusion (hyperkaliémie, acidose, myoglobinurie) doivent être activement surveillés et traités.","L'amputation reste le dernier recours en cas d'ischémie dépassée ou d'échec de revascularisation."],"pitfalls":["Ne pas retarder l'anticoagulation en attendant les résultats du bilan de coagulation complet.","Anticiper systématiquement le syndrome de revascularisation, surtout après une ischémie prolongée."],"src":"p. 182-183"},{"id":"225-sec-10","title":"Anévrisme de l'aorte abdominale : épidémiologie, étiologie et diagnostic","rank":"A","objectives":["225-obj-10","225-obj-11","225-obj-12","225-obj-13"],"content":"**[A] Définition** : on parle d'anévrisme lorsqu'une artère se dilate de façon localisée et durable, son diamètre dépassant de plus de 50 % celui du segment sus-jacent, avec disparition du parallélisme normal des bords vasculaires. Hors atteintes cérébrales, ce sont surtout l'aorte (notamment le segment sous-rénal), les artères poplitées et les artères iliaques qui sont concernées. La paroi (média) perd sa résistance à la distension du fait d'une destruction des fibres élastiques et d'une fragmentation du collagène, sous l'effet d'enzymes comme les métalloprotéases.\n\n**Épidémiologie** : prévalence en baisse dans les pays occidentaux, 2-5 % chez l'homme > 65 ans ; entre 75-84 ans, 5 % chez l'homme et 3 % chez la femme. Le risque annuel de rupture augmente avec le diamètre : ≈ 0,4 %/an si < 40 mm, 3 %/an à 50-59 mm, 15 %/an au-delà de 60 mm (risque environ 4 fois plus élevé chez la femme à diamètre égal). Environ 12 000 décès par rupture d'AAA par an en Europe, mais le porteur d'AAA a un risque de décès cardiovasculaire (coronaire, AVC) 10 fois supérieur à celui de rupture.\n\n**[B] Étiologie** : dans 80-90 % des cas, l'AAA survient sur un terrain athéromateux (souvent associé à une AOMI, une atteinte coronarienne ou carotidienne). Formes familiales avec parfois une maladie du tissu élastique identifiée (Marfan, Ehlers-Danlos, Loeys-Dietz), ou secondaires à une aortite (Takayasu, Horton), plus rarement infectieuses (syphilis, historiquement).\n\n**[A] Diagnostic clinique** :\n- *Forme asymptomatique* (la plus fréquente) : découverte fortuite à la palpation abdominale (masse battante et expansive para-ombilicale, ± souffle) ou à l'imagerie ; dépistage échographique recommandé chez l'homme > 65 ans, ou plus jeune si facteurs de risque (tabac, athérome, antécédents familiaux).\n- *Forme symptomatique* : révélation par une **fissuration/rupture** (douleur abdominale ou lombaire ± choc hémorragique, urgence vitale ; rupture intrapéritonéale souvent cataclysmique), plus rarement par fistule (aorto-cave → insuffisance cardiaque à débit élevé ; aorto-digestive → hémorragie digestive), par embolie à partir d'une thrombose intra-anévrismale, ou par compression des organes de voisinage, ou encore par un syndrome inflammatoire (fièvre, altération de l'état général, élévation de la VS/CRP).\n\n**[A] Diagnostic paraclinique** : l'**échographie abdominale** dépiste, mesure le diamètre maximal et assure le suivi (et recherche les localisations poplitées/iliaques associées). Le **scanner abdominopelvien injecté** est l'examen préthérapeutique de référence (diamètre, anatomie). L'IRM est une alternative en cas de contre-indication au scanner. L'artériographie n'est pas utile (ne visualise que la lumière circulante, sous-estime la taille en cas de thrombus mural).","keyPoints":["Un anévrisme correspond à une augmentation de diamètre > 50 % par rapport au diamètre d'amont.","80-90 % des AAA sont d'origine athéromateuse ; penser à Marfan, Ehlers-Danlos, Loeys-Dietz et aux aortites en cas de forme non athéromateuse.","Le risque de rupture augmente fortement avec le diamètre et est plus élevé chez la femme à taille égale.","Le porteur d'AAA meurt 10 fois plus souvent d'une complication cardiovasculaire que d'une rupture.","L'échographie dépiste et surveille l'AAA ; le scanner injecté est l'examen préthérapeutique de référence.","La forme symptomatique la plus grave est la rupture, urgence vitale."],"pitfalls":["Ne pas oublier de rechercher d'autres localisations anévrismales (poplitées, iliaques) et une maladie coronarienne/carotidienne associée.","L'artériographie ne doit pas être utilisée pour mesurer le diamètre d'un AAA (sous-estimation par le thrombus mural)."],"src":"p. 183-185"},{"id":"225-sec-11","title":"Anévrisme de l'aorte abdominale : prise en charge, suivi, anévrisme poplité","rank":"A","objectives":["225-obj-14","225-obj-15"],"content":"**[B] Forme asymptomatique** : le diamètre est le principal facteur prédictif du risque de rupture. La croissance moyenne est de 2-4 mm/an (variable individuellement), plus rapide chez l'homme fumeur avec un anévrisme déjà volumineux (tabagisme actif : progression environ 3 fois plus rapide). Surveillance échographique répétée, renforcée (tous les 6 mois) si le diamètre dépasse 45 mm. Le contrôle des facteurs de risque est indispensable pendant le suivi.\n\nAu-delà d'un seuil de **50-55 mm**, une intervention « à froid » est programmée :\n- chirurgie conventionnelle à ciel ouvert (exclusion de la zone anévrismale, interposition d'une prothèse) ;\n- traitement endovasculaire (endoprothèse par voie fémorale), moins invasif, préféré chez les sujets à haut risque chirurgical si l'anatomie est favorable, mais nécessitant une surveillance itérative (scanner, écho de contraste) à la recherche d'endofuites.\n\n**Forme symptomatique** : l'anévrisme rompu est une urgence absolue — seul le scanner diagnostique ne doit pas retarder l'intervention chez un patient en choc. Le traitement endovasculaire est de plus en plus proposé même en contexte de rupture, surtout chez le sujet à très haut risque périopératoire. En cas d'ischémie aiguë de membre par embolie à partir de l'AAA, la revascularisation du membre est urgente, la cure de l'AAA étant secondaire.\n\n**Suivi à long terme** : risque cardiovasculaire persistant à surveiller même après traitement réussi. Après chirurgie conventionnelle : surveillance écho-Doppler (risque de faux anévrisme anastomotique, thrombose exceptionnelle). Après endoprothèse : surveillance scanner/écho au long cours (endofuites, pouvant faire progresser voire rompre l'anévrisme). Le risque infectieux d'une prothèse vasculaire justifie une antibioprophylaxie lors des gestes à risque bactérien.\n\n**Anévrisme de l'artère poplitée (AP)** : fréquemment associé à un AAA (≈ 30 % des cas), bilatéral dans près de la moitié des cas. Découverte le plus souvent par une masse battante poplitée, un écho-Doppler systématique (dépistage si AAA ou AP controlatéral connu), ou une complication (ischémie).","keyPoints":["Le diamètre de l'AAA est le principal facteur prédictif de rupture ; la surveillance échographique s'intensifie (6 mois) au-delà de 45 mm.","Une intervention programmée est proposée au-delà de 50-55 mm, chirurgicale ou endovasculaire selon le terrain et l'anatomie.","La rupture d'AAA est une urgence absolue confirmée par le scanner sans délai.","Après endoprothèse, la surveillance recherche des endofuites au long cours.","L'anévrisme poplité est fréquemment associé à l'AAA (≈ 30 %) et bilatéral une fois sur deux."],"pitfalls":["Ne pas laisser un AAA rompu sans traitement en attendant d'autres examens que le scanner diagnostique.","Ne pas oublier la surveillance à vie des endoprothèses (endofuites) et des pontages (faux anévrismes anastomotiques).","Penser à rechercher un anévrisme poplité controlatéral ou un AAA associé devant tout anévrisme poplité."],"src":"p. 185-186"}],"essentials":[{"id":"225-ess-01","rank":"A","text":"L'AOMI est une atteinte athéromateuse significative des artères entre l'aorte terminale et les artères digitales.","src":"p. 167"},{"id":"225-ess-02","rank":"A","text":"L'AOMI est la 3e localisation de l'athérosclérose après les atteintes coronarienne et cérébrale.","src":"p. 167"},{"id":"225-ess-03","rank":"B","text":"Le tabagisme et le diabète sont les deux principaux facteurs de risque de l'AOMI.","src":"p. 168"},{"id":"225-ess-04","rank":"B","text":"Le diabète expose à des formes d'AOMI plus distales et de pronostic plus sévère.","src":"p. 168"},{"id":"225-ess-05","rank":"A","text":"La classification de Leriche et Fontaine comporte 4 stades : asymptomatique, claudication, douleur de repos, troubles trophiques.","src":"p. 168"},{"id":"225-ess-06","rank":"A","text":"La classification de Rutherford, plus détaillée, tend aujourd'hui à remplacer celle de Leriche et Fontaine.","src":"p. 168"},{"id":"225-ess-07","rank":"A","text":"La claudication intermittente est dite sévère lorsque la distance de marche est inférieure à 100 m.","src":"p. 169"},{"id":"225-ess-08","rank":"A","text":"Le syndrome de Leriche associe claudication fessière, fatigabilité à la marche et troubles de l'érection par atteinte aorto-iliaque.","src":"p. 169"},{"id":"225-ess-09","rank":"A","text":"L'ischémie critique se définit par une pression de cheville < 50 mmHg ou une pression d'hallux < 30 mmHg.","src":"p. 169"},{"id":"225-ess-10","rank":"B","text":"Le pouls pédieux peut être physiologiquement absent chez environ 5 % de la population.","src":"p. 170"},{"id":"225-ess-11","rank":"A","text":"L'index de pression systolique (IPS) est l'examen de première intention devant une suspicion d'AOMI.","src":"p. 170"},{"id":"225-ess-12","rank":"A","text":"Un IPS inférieur à 0,90 sur au moins une cheville affirme le diagnostic d'AOMI.","src":"p. 171"},{"id":"225-ess-13","rank":"A","text":"Un IPS inférieur à 0,70 définit une AOMI sévère.","src":"p. 171"},{"id":"225-ess-14","rank":"A","text":"Un IPS supérieur à 1,40 traduit une médiacalcose et impose de recourir à la pression d'orteil.","src":"p. 171"},{"id":"225-ess-15","rank":"B","text":"Un IPS abaissé est aussi un marqueur de risque cardiovasculaire global.","src":"p. 171"},{"id":"225-ess-16","rank":"B","text":"Le test de marche démasque une AOMI à IPS de repos normal chez un patient symptomatique.","src":"p. 171"},{"id":"225-ess-17","rank":"A","text":"L'échodoppler artériel des membres inférieurs est l'examen de première intention pour localiser et quantifier les sténoses.","src":"p. 172"},{"id":"225-ess-18","rank":"A","text":"L'angioscanner, l'angio-IRM et l'artériographie ne sont demandés qu'en vue d'une revascularisation.","src":"p. 172-173"},{"id":"225-ess-19","rank":"B","text":"Plus de 95 % des AOMI ont une origine athéromateuse.","src":"p. 174"},{"id":"225-ess-20","rank":"A","text":"Le contrôle des facteurs de risque cardiovasculaire s'applique à tous les stades de l'AOMI.","src":"p. 175"},{"id":"225-ess-21","rank":"A","text":"Un traitement antiplaquettaire est indiqué chez tout patient présentant une AOMI symptomatique.","src":"p. 175"},{"id":"225-ess-22","rank":"A","text":"L'objectif de LDL-cholestérol sous statine chez le patient AOMI est inférieur à 0,55 g/L, avec une réduction d'au moins 50 %.","src":"p. 175"},{"id":"225-ess-23","rank":"A","text":"La revascularisation est systématiquement proposée en cas d'ischémie permanente.","src":"p. 176"},{"id":"225-ess-24","rank":"B","text":"L'espérance de vie des patients claudicants est en moyenne réduite d'environ 10 ans.","src":"p. 177"},{"id":"225-ess-25","rank":"A","text":"La mortalité à 5 ans des patients en ischémie critique avoisine 70 %.","src":"p. 178"},{"id":"225-ess-26","rank":"A","text":"L'ischémie aiguë de membre est une urgence vasculaire pouvant engager le pronostic du membre et du patient.","src":"p. 178"},{"id":"225-ess-27","rank":"A","text":"Dans l'ischémie aiguë, les cellules nerveuses souffrent dès 2 heures et les cellules musculaires dès 6-8 heures.","src":"p. 178"},{"id":"225-ess-28","rank":"A","text":"La classification de Rutherford de l'ischémie aiguë distingue les grades I, IIa, IIb et III.","src":"p. 179"},{"id":"225-ess-29","rank":"A","text":"Le diagnostic de l'ischémie aiguë de membre est avant tout clinique ; aucun examen ne doit retarder la prise en charge en cas de déficit neurologique.","src":"p. 180"},{"id":"225-ess-30","rank":"A","text":"La thrombose in situ touche typiquement un sujet âgé déjà artériopathe, l'embolie un sujet plus jeune sur artères saines.","src":"p. 181"},{"id":"225-ess-31","rank":"B","text":"La fibrillation atriale est la principale cause cardiaque d'embolie artérielle des membres.","src":"p. 181"},{"id":"225-ess-32","rank":"A","text":"L'embolectomie à la sonde de Fogarty est le traitement de référence de l'ischémie aiguë par embolie sur artère saine.","src":"p. 182"},{"id":"225-ess-33","rank":"A","text":"Le syndrome de revascularisation associe hyperkaliémie, acidose métabolique et myoglobinurie, pouvant entraîner une insuffisance rénale aiguë.","src":"p. 178-183"},{"id":"225-ess-34","rank":"A","text":"Un anévrisme est défini par une augmentation de diamètre de plus de 50 % par rapport au diamètre d'amont.","src":"p. 183"},{"id":"225-ess-35","rank":"B","text":"Dans 80 à 90 % des cas, l'anévrisme de l'aorte abdominale survient chez un patient athéromateux.","src":"p. 184"},{"id":"225-ess-36","rank":"B","text":"Le risque annuel de rupture d'un AAA augmente fortement avec le diamètre et est environ 4 fois plus élevé chez la femme à taille égale.","src":"p. 184"},{"id":"225-ess-37","rank":"B","text":"Le porteur d'un AAA a un risque de décès cardiovasculaire 10 fois supérieur à celui de mourir de la rupture de son anévrisme.","src":"p. 184"},{"id":"225-ess-38","rank":"A","text":"L'échographie abdominale est l'examen de dépistage et de surveillance de l'AAA.","src":"p. 184"},{"id":"225-ess-39","rank":"A","text":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence de l'AAA.","src":"p. 185"},{"id":"225-ess-40","rank":"A","text":"La rupture d'AAA est une urgence absolue dont le diagnostic est confirmé par le scanner sans retarder la prise en charge.","src":"p. 186"}],"numbers":[{"id":"225-num-01","rank":"A","label":"Rang de l'AOMI parmi les localisations de l'athérosclérose","value":"3e (après coronaire et cérébrale)","src":"p. 167"},{"id":"225-num-02","rank":"B","label":"Pic d'âge de l'AOMI symptomatique (homme / femme)","value":"60-75 ans / 70-80 ans","src":"p. 167"},{"id":"225-num-03","rank":"B","label":"Prévalence de l'AOMI clinique après 60 ans","value":"1-5 %","src":"p. 168"},{"id":"225-num-04","rank":"B","label":"Prévalence de l'AOMI (clinique + infraclinique) après 60 ans","value":"10-15 %","src":"p. 168"},{"id":"225-num-05","rank":"B","label":"Ratio formes infracliniques / clinique d'AOMI","value":"2 à 4 pour 1","src":"p. 168"},{"id":"225-num-06","rank":"A","label":"Distance de marche définissant une claudication sévère","value":"< 100 m","src":"p. 169"},{"id":"225-num-07","rank":"A","label":"Délai de disparition de la douleur de claudication au repos","value":"< 5 minutes","src":"p. 168"},{"id":"225-num-08","rank":"B","label":"Fréquence d'absence congénitale du pouls pédieux","value":"5 % de la population","src":"p. 170"},{"id":"225-num-09","rank":"B","label":"Temps de recoloration cutanée normal","value":"< 3 secondes","src":"p. 170"},{"id":"225-num-10","rank":"A","label":"IPS normal","value":"1,00 à 1,40","src":"p. 171"},{"id":"225-num-11","rank":"A","label":"Seuil d'IPS diagnostique d'AOMI","value":"< 0,90","src":"p. 171"},{"id":"225-num-12","rank":"A","label":"Seuil d'IPS d'AOMI sévère","value":"< 0,70","src":"p. 171"},{"id":"225-num-13","rank":"A","label":"Seuil d'IPS évoquant une médiacalcose","value":"> 1,40","src":"p. 171"},{"id":"225-num-14","rank":"A","label":"Seuil pathologique de l'index de pression d'orteil","value":"< 0,70","src":"p. 171"},{"id":"225-num-15","rank":"A","label":"Pression d'orteil définissant l'ischémie critique","value":"< 30 mmHg","src":"p. 171"},{"id":"225-num-16","rank":"A","label":"Pression de cheville définissant l'ischémie critique","value":"< 50 mmHg","src":"p. 169"},{"id":"225-num-17","rank":"B","label":"Protocole du test de marche sur tapis roulant (Strandness)","value":"3,2 km/h, pente 10 %","src":"p. 171"},{"id":"225-num-18","rank":"B","label":"Baisse de pression de cheville après marche évocatrice d'AOMI","value":"> 30 mmHg","src":"p. 171"},{"id":"225-num-19","rank":"B","label":"Baisse d'IPS après marche évocatrice d'AOMI","value":"> 20 %","src":"p. 171"},{"id":"225-num-20","rank":"B","label":"TcPO2 normale au dos du pied","value":"> 50 mmHg","src":"p. 171"},{"id":"225-num-21","rank":"B","label":"TcPO2 seuil d'hypoxie critique","value":"< 10 mmHg","src":"p. 172"},{"id":"225-num-22","rank":"B","label":"Sensibilité/spécificité de l'angioscanner et de l'angio-IRM (vs artériographie)","value":"≈ 95 %","src":"p. 173"},{"id":"225-num-23","rank":"A","label":"Cible de pression artérielle chez l'AOMI","value":"PAS 120-129 mmHg, PAD 70-79 mmHg","src":"p. 175"},{"id":"225-num-24","rank":"A","label":"Cible d'HbA1c chez l'AOMI","value":"< 7 %","src":"p. 175"},{"id":"225-num-25","rank":"A","label":"Cible de LDL-cholestérol chez l'AOMI","value":"< 0,55 g/L (< 1,4 mmol/L), réduction ≥ 50 %","src":"p. 175"},{"id":"225-num-27","rank":"A","label":"Rythme de marche recommandé dans l'AOMI","value":"30-45 min, ≥ 3 fois/semaine","src":"p. 175"},{"id":"225-num-28","rank":"B","label":"Durée de la bithérapie antiplaquettaire après angioplastie","value":"1 à 6 mois","src":"p. 176"},{"id":"225-num-29","rank":"B","label":"Réduction de l'espérance de vie des claudicants","value":"≈ 10 ans","src":"p. 177"},{"id":"225-num-30","rank":"B","label":"Complications cardiovasculaires et décès à 5 ans chez les claudicants","value":"20 % et 20 %","src":"p. 177"},{"id":"225-num-31","rank":"B","label":"Risque d'amputation à 5 ans dans l'AOMI","value":"≈ 5 %","src":"p. 177"},{"id":"225-num-32","rank":"A","label":"Mortalité à 5 ans en ischémie critique","value":"≈ 70 %","src":"p. 178"},{"id":"225-num-33","rank":"A","label":"Délai de souffrance des cellules nerveuses en ischémie aiguë","value":"2 heures","src":"p. 178"},{"id":"225-num-34","rank":"A","label":"Délai de souffrance des cellules musculaires (rhabdomyolyse)","value":"6-8 heures","src":"p. 178"},{"id":"225-num-35","rank":"A","label":"Délai d'apparition de la nécrose cutanée","value":"24 heures","src":"p. 178"},{"id":"225-num-36","rank":"A","label":"Posologie de l'héparine non fractionnée en ischémie aiguë","value":"bolus 5000 UI puis 500 UI/kg/j","src":"p. 182"},{"id":"225-num-37","rank":"A","label":"Cible de TCA sous héparine en ischémie aiguë","value":"entre 2 et 3","src":"p. 182"},{"id":"225-num-38","rank":"A","label":"Seuil de dilatation définissant un anévrisme","value":"augmentation de diamètre > 50 % du diamètre d'amont","src":"p. 183"},{"id":"225-num-39","rank":"B","label":"Prévalence de l'AAA chez l'homme > 65 ans","value":"2-5 %","src":"p. 183"},{"id":"225-num-40","rank":"B","label":"Risque annuel de rupture d'AAA selon le diamètre","value":"0,4 %/an (< 40 mm), 3 %/an (50-59 mm), 15 %/an (> 60 mm)","src":"p. 184"}],"mnemonics":[{"id":"225-mn-01","rank":"B","title":"Facteurs de risque de l'AOMI","mnemonic":"Tout Diabétique A du Cholestérol","expansion":"**T**abagisme · **D**iabète · HT**A** · **Cholestérol** (hypercholestérolémie) — les quatre facteurs de risque associés à l'AOMI.","src":"p. 168"},{"id":"225-mn-02","rank":"A","title":"Signes physiques de l'ischémie aiguë de membre","mnemonic":"Froid, Douloureux, Pâle, Pouls Perdu, Paralysé","expansion":"**F**roideur du membre · **D**ouleur à la palpation musculaire · **P**âleur/couleur livide · **P**ouls abolis en aval · **P**aralysie/anesthésie (déficit neurologique).","src":"p. 179"},{"id":"225-mn-03","rank":"A","title":"Stades de l'AOMI (Leriche-Fontaine)","mnemonic":"Après un Certain temps, Douleur puis Ulcère","expansion":"**A**symptomatique (I) · **C**laudication intermittente (II) · **D**ouleur ischémique de repos (III) · **U**lcération ou gangrène (IV).","src":"p. 168"},{"id":"225-mn-04","rank":"B","title":"Causes cardiaques d'embolie artérielle des membres","mnemonic":"Mon Vieux cœur Infarci Fibrille et s'Endocardite","expansion":"**M**yxome de l'atrium · **V**alvulopathie ou prothèse valvulaire · **I**nfarctus du myocarde (faux anévrisme) · **F**ibrillation atriale · **Endocardite** infectieuse — principales sources cardiaques d'embolie sur artère saine.","src":"p. 181"},{"id":"225-mn-05","rank":"B","title":"Conséquences métaboliques de la revascularisation","mnemonic":"Hyper Acide, Myoglobine, Calcium bas, Phosphore haut","expansion":"**H**yperkaliémie · **A**cidose métabolique · **M**yoglobinémie/myoglobinurie · hypo**C**alcémie · hyper**P**hosphorémie — le syndrome de revascularisation à dépister après désobstruction d'une ischémie aiguë.","src":"p. 178-179"},{"id":"225-mn-06","rank":"B","title":"Diagnostics différentiels de la claudication","mnemonic":"Nerveux, Rhumato, Veines, Muscles","expansion":"**N**eurologique (canal lombaire étroit, sciatalgie) · **Rhumato**logique (arthrose, tendinite) · **Veines** (claudication post-thrombotique) · **Muscles** (douleurs sous statines) — grandes catégories de diagnostics différentiels de la douleur de jambe à la marche.","src":"p. 174"},{"id":"225-mn-07","rank":"B","title":"Artériopathies non athéromateuses des membres inférieurs","mnemonic":"Buerger Taquine Horton, Dysplasie et Coarctation","expansion":"Maladie de **B**uerger · maladie de **T**akayasu · maladie de **Horton** · **D**ysplasie fibromusculaire · **C**oarctation de l'aorte — principales causes non athéromateuses d'artériopathie des membres inférieurs.","src":"p. 174"}]},"questions":[{"id":"225-qcm-001","type":"QRM","rank":"A","objective":"225-obj-01","tags":["définition","épidémiologie"],"difficulty":1,"stem":"Parmi les propositions suivantes concernant l'AOMI, lesquelles sont exactes ?","options":[{"t":"Elle correspond à une atteinte athéromateuse significative entre l'aorte terminale et les artères digitales","ok":true,"why":"C'est la définition retenue par le référentiel."},{"t":"La forme infraclinique est plus fréquente que la forme clinique","ok":true,"why":"Il existe 2 à 4 formes infracliniques pour chaque forme clinique."},{"t":"Sa forme symptomatique est plus fréquente chez l'homme","ok":true,"why":"Le pic symptomatique touche préférentiellement l'homme."},{"t":"Elle est la 2e localisation de l'athérosclérose en fréquence","ok":false,"why":"Elle vient après le cœur et le cerveau, donc au 3e rang."},{"t":"Elle ne concerne jamais les artères digitales","ok":false,"why":"Au contraire, la définition inclut les artères jusqu'aux artères digitales."}],"explanation":"L'AOMI est une atteinte athéromateuse des artères entre l'aorte terminale et les artères digitales, 3e localisation de l'athérosclérose, plus fréquente et plus souvent infraclinique qu'elle n'y paraît.","trap":"Ne pas confondre 2e et 3e rang des localisations athéromateuses.","src":"p. 167-168"},{"id":"225-qcm-002","type":"QRM","rank":"B","objective":"225-obj-02","tags":["étiologie","physiopathologie"],"difficulty":1,"stem":"Quels sont les deux facteurs de risque les plus fortement associés à l'AOMI ?","options":[{"t":"Le tabagisme","ok":true,"why":"C'est le premier facteur de risque, plus marqué chez le sujet jeune."},{"t":"L'hypercholestérolémie","ok":false,"why":"Elle est citée comme fréquemment associée mais pas comme l'un des deux facteurs principaux."},{"t":"L'hypertension artérielle","ok":false,"why":"Elle est fréquemment associée mais n'est pas l'un des deux facteurs principaux."},{"t":"Le diabète","ok":true,"why":"Il est associé à des formes plus distales et de pronostic plus sévère."},{"t":"L'hypertriglycéridémie isolée","ok":false,"why":"Ce facteur n'est pas cité parmi les principaux facteurs de risque de l'AOMI."}],"explanation":"Le tabac et le diabète sont les deux principaux facteurs de risque de l'AOMI ; l'hypercholestérolémie et l'HTA y sont seulement fréquemment associées.","src":"p. 168"},{"id":"225-qcm-003","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"stem":"Un homme de 64 ans décrit une crampe du mollet apparaissant après 300 mètres de marche, cédant à l'arrêt. Quelles propositions sont exactes ?","options":[{"t":"La claudication est dite sévère car la distance de marche est inférieure à 100 m","ok":false,"why":"Ici la distance est de 300 m, donc non sévère selon le seuil retenu."},{"t":"Il s'agit probablement d'une claudication intermittente d'origine artérielle","ok":true,"why":"Le tableau typique associe crampe à la marche et sédation rapide à l'arrêt."},{"t":"La douleur cède habituellement en moins de 5 minutes","ok":true,"why":"C'est le délai habituel de disparition de la douleur de claudication."},{"t":"Cette présentation élimine formellement une AOMI infraclinique associée","ok":false,"why":"Rien n'élimine une atteinte infraclinique associée sur un autre territoire."},{"t":"Une localisation fessière évoquerait une atteinte aorto-iliaque","ok":true,"why":"La claudication fessière oriente vers une atteinte aorto-iliaque (syndrome de Leriche)."}],"explanation":"La claudication typique cède en moins de 5 minutes ; elle est dite sévère seulement si la distance de marche est < 100 m. Une localisation fessière oriente vers une atteinte aorto-iliaque.","trap":"Le seuil de sévérité (< 100 m) est souvent confondu avec le seuil déclenchant la douleur.","src":"p. 168-169"},{"id":"225-qcm-004","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique","pièges"],"difficulty":2,"stem":"Quelles situations peuvent masquer une AOMI sévère malgré une absence de plainte fonctionnelle ?","options":[{"t":"Des comorbidités limitant la marche (insuffisance cardiaque, atteinte articulaire)","ok":true,"why":"Le patient ne marche pas assez pour révéler la claudication."},{"t":"Une circulation collatérale bien développée","ok":true,"why":"Elle peut compenser suffisamment le déficit de perfusion pour éviter les symptômes."},{"t":"Une neuropathie diabétique altérant la sensibilité","ok":true,"why":"Elle peut masquer les douleurs de claudication ou de repos."},{"t":"Un IPS supérieur à 1,40","ok":false,"why":"Cette valeur oriente vers une médiacalcose, pas vers une AOMI masquée par ailleurs asymptomatique."},{"t":"Un âge inférieur à 50 ans","ok":false,"why":"Ce n'est pas un facteur de masquage cité dans le texte."}],"explanation":"La collatéralité, la neuropathie et les comorbidités limitant la marche peuvent masquer une AOMI sévère : il faut toujours vérifier que le patient marche réellement avant d'interroger sur la claudication.","src":"p. 169"},{"id":"225-qcm-005","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique","urgence"],"difficulty":1,"stem":"Concernant l'ischémie permanente (stades III-IV), quelles propositions sont exactes ?","options":[{"t":"Les douleurs de décubitus durent typiquement moins de 48 heures","ok":false,"why":"L'ischémie critique implique des douleurs de plus de 15 jours."},{"t":"La pression d'hallux seuil est de 50 mmHg","ok":false,"why":"Le seuil pour l'hallux est de 30 mmHg, non 50 mmHg."},{"t":"L'ischémie critique est définie par une pression de cheville inférieure à 50 mmHg","ok":true,"why":"C'est l'un des deux seuils hémodynamiques de l'ischémie critique."},{"t":"Les douleurs de décubitus sont soulagées par la surélévation des jambes","ok":false,"why":"Elles s'améliorent au contraire en position déclive : le patient garde la jambe pendante au bord du lit, voire se lève la nuit."},{"t":"Les troubles trophiques sont plus fréquents chez le patient diabétique","ok":true,"why":"La gangrène des orteils est plus fréquente chez ces patients."}],"explanation":"L'ischémie critique associe des douleurs de plus de 15 jours et un effondrement des pressions de perfusion (cheville < 50 mmHg ou hallux < 30 mmHg).","trap":"Ne pas confondre les seuils de cheville (50 mmHg) et d'hallux (30 mmHg).","src":"p. 169"},{"id":"225-qcm-006","type":"QRM","rank":"A","objective":"225-obj-04","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Quelles affirmations concernant l'index de pression systolique (IPS) sont exactes ?","options":[{"t":"L'IPS est mesuré uniquement au bras droit","ok":false,"why":"La pression brachiale doit être mesurée aux deux bras."},{"t":"Un IPS inférieur à 0,90 doit être retrouvé aux deux chevilles pour affirmer l'AOMI","ok":false,"why":"Il suffit qu'au moins une des deux chevilles ait un IPS inférieur à 0,90 pour retenir l'AOMI."},{"t":"Un IPS supérieur à 1,40 élimine toute AOMI","ok":false,"why":"Il traduit une médiacalcose, qui peut masquer une AOMI sous-jacente : il faut alors mesurer la pression d'orteil."},{"t":"Un IPS entre 1,00 et 1,40 est normal","ok":true,"why":"C'est l'intervalle physiologique habituel."},{"t":"Un IPS inférieur à 0,70 définit une AOMI sévère","ok":true,"why":"C'est le seuil de sévérité retenu."}],"explanation":"L'IPS normal est entre 1,00 et 1,40 ; il est pathologique si < 0,90 (AOMI) ou < 0,70 (sévère). Un IPS > 1,40 signe une médiacalcose et impose la mesure de la pression d'orteil, sans éliminer une AOMI.","trap":"Un IPS élevé ne rassure pas chez le diabétique ou l'insuffisant rénal : penser à la médiacalcose.","src":"p. 171"},{"id":"225-qcm-007","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Chez un patient diabétique âgé avec suspicion d'AOMI et IPS mesuré à 1,55, quelle est la conduite adaptée ?","options":[{"t":"Conclure à l'absence d'AOMI devant cet IPS élevé","ok":false,"why":"Un IPS > 1,40 traduit une médiacalcose et ne permet pas d'éliminer l'AOMI."},{"t":"Mesurer la pression d'orteil","ok":true,"why":"Elle remplace la pression de cheville en cas de médiacalcose."},{"t":"Considérer qu'un index de pression d'orteil inférieur à 0,70 témoigne d'une AOMI","ok":true,"why":"C'est le seuil retenu pour l'index de pression d'orteil."},{"t":"Demander d'emblée une artériographie diagnostique","ok":false,"why":"L'artériographie n'est indiquée qu'en vue d'une revascularisation, jamais en 1re intention diagnostique."},{"t":"Considérer qu'une pression d'orteil inférieure à 30 mmHg traduit une ischémie critique","ok":true,"why":"C'est le seuil de pression d'orteil définissant l'ischémie critique."}],"explanation":"Chez le diabétique âgé, un IPS élevé évoque une médiacalcose : la pression d'orteil (pathologique si < 0,70 ; ischémie critique si < 30 mmHg) doit alors être mesurée.","src":"p. 171"},{"id":"225-qcm-008","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique","imagerie"],"difficulty":1,"stem":"Quel(s) examen(s) est (sont) réservé(s) à un projet de revascularisation dans l'AOMI ?","options":[{"t":"L'artériographie des membres inférieurs","ok":true,"why":"Elle est aujourd'hui réservée aux procédures de revascularisation."},{"t":"L'angioscanner des membres inférieurs","ok":true,"why":"Il n'est demandé qu'en vue d'une revascularisation."},{"t":"L'échodoppler artériel des membres inférieurs","ok":false,"why":"C'est l'examen de 1re intention, utilisé dès la suspicion diagnostique."},{"t":"Le test de marche sur tapis roulant","ok":false,"why":"Il évalue la distance de gêne et la distance de marche et sensibilise le diagnostic (baisse de la pression de cheville après la marche) : il n'est pas réservé à un projet de revascularisation."},{"t":"L'index de pression systolique","ok":false,"why":"Il s'agit d'un examen de dépistage/diagnostic de 1re intention."}],"explanation":"L'échodoppler, l'IPS et le test de marche sur tapis roulant servent au diagnostic et à l'évaluation ; l'angioscanner, l'angio-IRM et l'artériographie ne sont demandés qu'en vue d'une revascularisation.","src":"p. 172-173"},{"id":"225-qcm-009","type":"QRM","rank":"B","objective":"225-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Concernant l'angio-IRM des membres inférieurs, quelles propositions sont exactes ?","options":[{"t":"Elle constitue l'examen de 1re intention devant une suspicion d'AOMI","ok":false,"why":"L'examen de 1re intention est l'échodoppler artériel."},{"t":"Elle n'utilise pas de rayonnement ionisant","ok":true,"why":"C'est un avantage de l'IRM par rapport au scanner."},{"t":"Ses performances diagnostiques sont proches de celles de l'angioscanner","ok":true,"why":"Sensibilité et spécificité de l'ordre de 95 % pour les deux techniques."},{"t":"Elle permet de bien visualiser les calcifications artérielles","ok":false,"why":"Au contraire, elle ne visualise pas les calcifications, utiles au chirurgien."},{"t":"Elle est contre-indiquée dès que la clairance de la créatinine est inférieure à 60 mL/min/1,73 m²","ok":false,"why":"Le gadolinium n'est contre-indiqué qu'en cas d'insuffisance rénale sévère, avec une clairance inférieure à 30 mL/min/1,73 m²."}],"explanation":"L'angio-IRM a des performances proches de l'angioscanner (≈ 95 %) sans irradiation, mais est contre-indiquée si la clairance est < 30 mL/min/1,73 m² et ne montre pas les calcifications.","src":"p. 173"},{"id":"225-qcm-010","type":"QRM","rank":"B","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":3,"stem":"Une femme de 72 ans présente des douleurs des mollets à la marche, variables selon les jours, cédant au repos. Quels diagnostics différentiels doivent être évoqués ?","options":[{"t":"Une douleur musculaire sous statines, qui permet alors d'écarter une AOMI associée","ok":false,"why":"Les douleurs musculaires sous statines peuvent mimer une AOMI, mais les tableaux peuvent être intriqués : elles n'éliminent pas une AOMI."},{"t":"Un canal lombaire étroit","ok":true,"why":"Il donne des douleurs ou paresthésies à l'effort, cédant au repos."},{"t":"Une anévrisme poplité asymptomatique","ok":false,"why":"Il n'est pas cité comme cause de claudication ; il se manifeste plutôt par une masse battante ou une ischémie."},{"t":"Une ischémie mésentérique chronique","ok":false,"why":"Elle donne un angor digestif postprandial, pas une claudication des membres."},{"t":"Un syndrome de Leriche","ok":false,"why":"C'est une forme d'AOMI par atteinte aorto-iliaque (claudication fessière, fatigabilité à la marche, troubles de l'érection chez l'homme), pas un diagnostic différentiel."}],"explanation":"Devant des douleurs de jambe à la marche, on évoque notamment un canal lombaire étroit, une cause rhumatologique, une claudication veineuse post-thrombotique ou des douleurs musculaires sous statines, qui peuvent coexister avec une AOMI chez le sujet âgé (tableaux intriqués). Le syndrome de Leriche est une forme d'AOMI aorto-iliaque, pas un diagnostic différentiel.","trap":"Un tableau atypique de claudication n'élimine pas une cause non artérielle intriquée.","src":"p. 174"},{"id":"225-qcm-011","type":"QRM","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Chez un homme de 35 ans non tabagique et sans facteur de risque cardiovasculaire, une artériopathie des membres inférieurs doit faire évoquer :","options":[{"t":"Une hypercholestérolémie familiale isolée sans autre facteur","ok":false,"why":"Ce n'est pas une cause d'artériopathie non athéromateuse évoquée dans ce contexte."},{"t":"Une dysplasie fibromusculaire","ok":true,"why":"Elle touche préférentiellement l'artère iliaque ou poplitée en dehors de l'athérome."},{"t":"Une athérosclérose classique","ok":false,"why":"Elle représente plus de 95 % des AOMI mais est peu probable en l'absence de tout facteur de risque chez un sujet jeune."},{"t":"Une coarctation de l'aorte","ok":true,"why":"Elle peut causer un hypodébit d'aval touchant les membres inférieurs."},{"t":"Une maladie de Buerger","ok":true,"why":"C'est une artériopathie inflammatoire non athéromateuse classique du sujet jeune."}],"explanation":"Chez un sujet jeune sans facteur de risque cardiovasculaire, il faut évoquer une cause non athéromateuse : maladie de Buerger, dysplasie fibromusculaire, coarctation, aortite, etc.","src":"p. 174"},{"id":"225-qcm-012","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Quelles sont les cibles thérapeutiques recommandées chez un patient AOMI ?","options":[{"t":"HbA1c < 7 %","ok":true,"why":"C'est la cible glycémique recommandée."},{"t":"Pression artérielle systolique cible entre 120 et 129 mmHg","ok":true,"why":"C'est la cible tensionnelle proposée."},{"t":"IMC cible entre 25 et 30 kg/m²","ok":false,"why":"La cible d'IMC est entre 20 et 25 kg/m², pas 25-30."},{"t":"Réentraînement 3 fois par semaine pendant 4 semaines","ok":false,"why":"La cible de réentraînement citée est de 3 fois par semaine pendant 12 semaines."},{"t":"LDL-cholestérol < 0,70 g/L avec réduction d'au moins 50 %","ok":false,"why":"La cible de LDL-cholestérol chez le patient AOMI est < 0,55 g/L (< 1,4 mmol/L), avec une réduction d'au moins 50 %."}],"explanation":"Les cibles chez le patient AOMI incluent LDL < 0,55 g/L (réduction ≥ 50 %), HbA1c < 7 %, PAS 120-129/PAD 70-79 mmHg, IMC 20-25 kg/m² et un réentraînement supervisé 3 fois/semaine pendant 12 semaines.","src":"p. 175"},{"id":"225-qcm-013","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement","pièges"],"difficulty":3,"stem":"Concernant l'antithrombotique dans l'AOMI, quelles propositions sont exactes ?","options":[{"t":"L'antiplaquettaire vise à réduire le risque de complications cardiovasculaires (infarctus, AVC)","ok":true,"why":"C'est l'objectif de ce traitement chez l'artériopathe."},{"t":"L'antiplaquettaire est systématiquement indiqué même en cas d'AOMI totalement asymptomatique isolée","ok":false,"why":"Il est alors débattu, sauf atteinte athéromateuse associée dans un autre territoire."},{"t":"Le clopidogrel est une alternative à l'aspirine","ok":true,"why":"L'antiplaquettaire peut être l'aspirine ou le clopidogrel."},{"t":"Une anticoagulation curative au long cours est le traitement antithrombotique de référence de l'AOMI","ok":false,"why":"Le traitement antithrombotique de référence est l'antiplaquettaire (aspirine ou clopidogrel)."},{"t":"Un antiplaquettaire est indiqué chez tout patient AOMI symptomatique","ok":true,"why":"C'est l'indication formelle rappelée dans le texte."}],"explanation":"L'antiplaquettaire (aspirine ou clopidogrel) est systématique si l'AOMI est symptomatique, pour réduire le risque d'infarctus et d'AVC ; il est débattu en cas d'AOMI asymptomatique isolée.","trap":"Ne pas prescrire systématiquement un antiplaquettaire dans une AOMI asymptomatique isolée : il y est débattu.","src":"p. 175"},{"id":"225-qcm-014","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Chez un patient présentant une claudication intermittente invalidante, quelles propositions concernant la prise en charge sont exactes ?","options":[{"t":"Une bithérapie antiplaquettaire est proposée pendant 1 à 6 mois après une angioplastie avec ou sans stent","ok":true,"why":"C'est la durée proposée selon le geste et sa localisation."},{"t":"La réadaptation à la marche supervisée est proposée en 1re intention si le périmètre de marche n'est pas très altéré","ok":true,"why":"C'est la stratégie de 1re ligne avant de discuter une revascularisation."},{"t":"Une revascularisation peut être discutée après échec du traitement médical bien conduit","ok":true,"why":"Elle est envisagée en cas de claudication sévère invalidante persistante."},{"t":"La chirurgie de pontage privilégie le matériel veineux lorsque c'est possible","ok":true,"why":"Le matériel veineux est préféré à la prothèse vasculaire quand c'est réalisable."},{"t":"L'angioplastie donne de meilleurs résultats sur des lésions longues et distales que sur des lésions courtes et proximales","ok":false,"why":"C'est l'inverse : les résultats sont meilleurs sur les lésions courtes et proximales."}],"explanation":"La réadaptation supervisée est proposée en 1re ligne ; une revascularisation (angioplastie sur lésions courtes/proximales, ou chirurgie de pontage veineux de préférence) est discutée après échec du traitement médical.","src":"p. 175-176"},{"id":"225-qcm-015","type":"QRM","rank":"B","objective":"225-obj-06","tags":["suivi","complications"],"difficulty":2,"stem":"Concernant le pronostic des patients claudicants, quelles propositions sont exactes ?","options":[{"t":"À 5 ans, environ 20 % présentent des complications cardiovasculaires","ok":true,"why":"C'est le chiffre retenu à 5 ans."},{"t":"Le risque d'amputation à 5 ans avoisine 25 %","ok":false,"why":"Le risque d'amputation à 5 ans est de l'ordre de 5 %, pas 25 % (qui concerne l'aggravation locale globale)."},{"t":"25 % voient leur artériopathie s'aggraver localement à 5 ans, dont 1/5 avec amputation majeure","ok":true,"why":"Ce sont les chiffres d'aggravation locale et d'amputation parmi ceux-ci."},{"t":"À 5 ans, environ 20 % décèdent, pour moitié de cause cardiovasculaire","ok":true,"why":"C'est la répartition citée du taux de décès à 5 ans."},{"t":"Leur espérance de vie est réduite d'environ 2 ans en moyenne","ok":false,"why":"Chez les claudicants, l'espérance de vie est réduite en moyenne de 10 ans."}],"explanation":"Chez les claudicants, l'espérance de vie est réduite d'environ 10 ans ; à 5 ans : 20 % de complications cardiovasculaires, 20 % de décès (moitié CV), 25 % d'aggravation locale (dont 1/5 d'amputation majeure) et environ 5 % de risque global d'amputation.","trap":"Ne pas confondre le taux d'aggravation locale globale (25 %) et le risque global d'amputation (5 %).","src":"p. 177"},{"id":"225-qru-001","type":"QRU","rank":"A","objective":"225-obj-04","tags":["diagnostic","paraclinique"],"difficulty":1,"stem":"Quel est l'examen à réaliser en première intention devant une suspicion d'AOMI ?","options":[{"t":"La mesure de la TcPO2","ok":false,"why":"Elle est utile pour l'évaluation de l'ischémie critique, pas comme test de première intention."},{"t":"L'index de pression systolique","ok":true,"why":"C'est l'examen de première intention devant une suspicion d'AOMI."},{"t":"Le test de marche sur tapis roulant","ok":false,"why":"Il est réservé au cas d'IPS de repos normal chez un patient symptomatique."},{"t":"Le scanner injecté","ok":false,"why":"Il n'est demandé qu'en vue d'une revascularisation."},{"t":"L'artériographie","ok":false,"why":"Elle est réservée aux procédures de revascularisation."}],"explanation":"L'IPS est le premier examen devant toute suspicion d'AOMI ; il est simple, non invasif et permet d'affirmer le diagnostic si < 0,90.","src":"p. 170-171"},{"id":"225-qru-002","type":"QRU","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"stem":"Quel syndrome associe claudication fessière, fatigabilité à la marche et troubles de l'érection ?","options":[{"t":"Le syndrome de revascularisation","ok":false,"why":"Il correspond aux conséquences métaboliques après reperfusion, sans rapport avec ce tableau."},{"t":"Le syndrome des loges","ok":false,"why":"Il s'agit d'une complication de l'ischémie aiguë, sans rapport avec ce tableau."},{"t":"Le syndrome de Rutherford","ok":false,"why":"Rutherford désigne une classification de sévérité, pas un syndrome clinique."},{"t":"Le syndrome de Fontaine","ok":false,"why":"Fontaine désigne également une classification, pas un syndrome clinique spécifique."},{"t":"Le syndrome de Leriche","ok":true,"why":"Il correspond à une atteinte aorto-iliaque associant ces trois éléments."}],"explanation":"Le syndrome de Leriche associe claudication fessière, fatigabilité à la marche et troubles de l'érection, en rapport avec une atteinte aorto-iliaque.","src":"p. 169"},{"id":"225-qru-003","type":"QRU","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"stem":"Chez un patient symptomatique dont l'IPS de repos est normal, quel examen permet de sensibiliser le diagnostic d'AOMI ?","options":[{"t":"Le test de marche sur tapis roulant","ok":true,"why":"Une baisse de pression de cheville > 30 mmHg ou d'IPS > 20 % après l'effort est évocatrice d'AOMI."},{"t":"La palpation des pouls périphériques","ok":false,"why":"Elle fait partie de l'examen initial mais ne sensibilise pas le diagnostic en cas d'IPS de repos normal."},{"t":"Le dosage des D-dimères","ok":false,"why":"Ce dosage n'a pas d'indication dans le bilan de l'AOMI chronique."},{"t":"L'angioscanner des membres inférieurs","ok":false,"why":"Il n'est indiqué qu'en vue d'une revascularisation, pas pour sensibiliser un diagnostic douteux."},{"t":"L'artériographie","ok":false,"why":"Elle est réservée aux gestes de revascularisation."}],"explanation":"Le test de marche sur tapis roulant (protocole de Strandness) démasque une AOMI à IPS de repos normal via une chute de la pression de cheville ou de l'IPS après effort.","src":"p. 171"},{"id":"225-qru-004","type":"QRU","rank":"A","objective":"225-obj-17","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Quel tableau clinique évoque typiquement une ischémie mésentérique chronique ?","options":[{"t":"Une claudication fessière bilatérale","ok":false,"why":"Elle évoque une atteinte aorto-iliaque (syndrome de Leriche), pas une ischémie digestive."},{"t":"Une douleur de décubitus des orteils","ok":false,"why":"Elle évoque une ischémie permanente des membres inférieurs, pas une ischémie digestive."},{"t":"Une masse battante et expansive péri-ombilicale","ok":false,"why":"C'est le signe d'un anévrisme de l'aorte abdominale, pas d'une ischémie mésentérique."},{"t":"Une douleur abdominale aiguë avec vidange digestive accélérée","ok":false,"why":"Ce tableau évoque plutôt une ischémie mésentérique aiguë."},{"t":"Un angor digestif : douleurs abdominales postprandiales","ok":true,"why":"C'est la présentation typique de l'ischémie mésentérique chronique."}],"explanation":"L'ischémie mésentérique chronique se traduit typiquement par un angor digestif : douleurs abdominales postprandiales pouvant conduire à une restriction alimentaire et un amaigrissement.","src":"p. 166"},{"id":"225-qroc-001","type":"QROC","rank":"A","objective":"225-obj-01","tags":["définition"],"difficulty":1,"question":"Entre quelles structures artérielles se situent les lésions définissant l'AOMI ?","answer":"Entre l'aorte terminale et les artères digitales","accept":["aorte terminale - artères digitales","aorte distale aux orteils"],"keywords":["aorte","digitales"],"explanation":"L'AOMI regroupe toute atteinte athéromateuse significative des artères situées entre l'aorte terminale et les artères digitales des orteils.","src":"p. 167"},{"id":"225-qroc-002","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"Quel est le rang de l'AOMI parmi les localisations de l'athérosclérose ?","answer":"3e localisation, après les atteintes coronarienne et cérébrale","accept":["troisième","3e"],"keywords":["3e","localisation"],"explanation":"Après le cœur et le cerveau, l'AOMI est la 3e localisation de l'athérosclérose par sa fréquence.","src":"p. 167"},{"id":"225-qroc-003","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on le stade où l'AOMI ne se manifeste qu'à l'effort ?","answer":"Ischémie d'effort","accept":["ischémie à l'effort"],"keywords":["ischémie","effort"],"explanation":"Avant l'ischémie permanente, l'AOMI se manifeste d'abord à l'effort par une hypoxie musculaire lors de la marche : c'est le stade d'ischémie d'effort.","src":"p. 168"},{"id":"225-qroc-004","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"En dessous de quelle distance de marche la claudication intermittente est-elle considérée comme sévère ?","answer":"100 mètres","accept":["100 m","< 100 mètres"],"keywords":["100"],"explanation":"La claudication est dite sévère lorsque la distance de marche est inférieure à 100 mètres.","src":"p. 169"},{"id":"225-qroc-005","type":"QROC","rank":"B","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Quel pourcentage de la population n'a physiologiquement pas de pouls pédieux perceptible ?","answer":"Environ 5 %","accept":["5 %","5 pour cent"],"keywords":["5"],"explanation":"Le pouls pédieux peut être absent de manière congénitale chez environ 5 % de la population, sans que cela traduise une pathologie.","src":"p. 170"},{"id":"225-qroc-006","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quelle est la valeur seuil de l'IPS en dessous de laquelle le diagnostic d'AOMI est retenu ?","answer":"Inférieur à 0,90","accept":["< 0,90","0,9"],"keywords":["0,90"],"explanation":"Un IPS inférieur à 0,90 sur au moins une cheville permet de retenir le diagnostic d'AOMI.","src":"p. 171"},{"id":"225-qroc-007","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quelle anomalie de la paroi artérielle explique un IPS anormalement élevé (> 1,40) ?","answer":"Une médiacalcose (rigidité artérielle par calcification de la média)","accept":["médiacalcose","calcification de la média"],"keywords":["médiacalcose"],"explanation":"Une médiacalcose, fréquente chez le diabétique âgé ou le dialysé, rend l'artère incompressible et donne un IPS faussement élevé, sans rétrécissement intraluminal.","src":"p. 171"},{"id":"225-qroc-008","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quel est l'examen d'imagerie de première intention pour localiser et quantifier une sténose artérielle des membres inférieurs ?","answer":"L'échodoppler artériel des membres inférieurs","accept":["échodoppler","écho-doppler artériel"],"keywords":["échodoppler"],"explanation":"L'échodoppler artériel est l'examen de 1re intention, non invasif, qui localise et quantifie les lésions dans la grande majorité des cas.","src":"p. 172"},{"id":"225-qroc-009","type":"QROC","rank":"B","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quel protocole de test de marche standardisé (vitesse, pente) est utilisé pour sensibiliser le diagnostic d'AOMI ?","answer":"Protocole de Strandness : 3,2 km/h, pente à 10 %","accept":["strandness","3,2 km/h pente 10%"],"keywords":["strandness"],"explanation":"Le protocole de Strandness (3,2 km/h, pente à 10 %) sur tapis roulant permet de sensibiliser le diagnostic chez un patient symptomatique à IPS de repos normal.","src":"p. 171"},{"id":"225-qroc-010","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"question":"Citer deux artériopathies inflammatoires non athéromateuses des membres inférieurs.","answer":"Maladie de Buerger et maladie de Takayasu (ou Horton)","accept":["buerger","takayasu","horton"],"keywords":["buerger","takayasu"],"explanation":"Les artériopathies inflammatoires non athéromateuses comprennent la maladie de Buerger, la maladie de Takayasu, la maladie de Horton et certaines collagénoses.","src":"p. 174"},{"id":"225-qroc-011","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","paraclinique"],"difficulty":1,"question":"Quelle est la cible de LDL-cholestérol chez un patient AOMI sous statine ?","answer":"Inférieur à 0,55 g/L, avec une réduction d'au moins 50 %","accept":["< 0,55 g/l","0,55"],"keywords":["0,55"],"explanation":"La cible de LDL-cholestérol chez le patient AOMI est inférieure à 0,55 g/L (1,4 mmol/L), avec une réduction d'au moins 50 % par rapport à la valeur initiale.","src":"p. 175"},{"id":"225-qroc-012","type":"QROC","rank":"A","objective":"225-obj-06","tags":["suivi","paraclinique"],"difficulty":2,"question":"De combien d'années environ l'espérance de vie des patients claudicants est-elle réduite en moyenne ?","answer":"Environ 10 ans","accept":["10 ans"],"keywords":["10"],"explanation":"L'espérance de vie des sujets atteints de claudication intermittente est en moyenne réduite d'environ 10 ans par rapport à la population générale.","src":"p. 177"},{"id":"225-open-01","type":"OPEN","rank":"A","objective":"225-obj-04","tags":["diagnostic","paraclinique"],"difficulty":2,"prompt":"Un homme de 66 ans, tabagique, consulte pour une claudication du mollet gauche apparaissant à la marche. Décrivez la démarche diagnostique à mettre en œuvre, des éléments de l'examen clinique à la place des différents examens complémentaires.","rubric":[{"point":"Examen clinique bilatéral et comparatif : inspection, palpation des pouls, temps de recoloration, auscultation","weight":2},{"point":"Mesure de l'index de pression systolique en 1re intention","weight":2},{"point":"Interprétation des seuils de l'IPS (normal, AOMI, sévère, médiacalcose)","weight":2},{"point":"Test de marche si symptômes avec IPS de repos normal","weight":1},{"point":"Échodoppler artériel des membres inférieurs en 1re intention pour localiser les lésions","weight":2},{"point":"Angioscanner/angio-IRM/artériographie réservés à un projet de revascularisation","weight":1}],"model":"L'examen clinique doit être bilatéral et comparatif : inspection de la couleur cutanée et des troubles trophiques, palpation des pouls fémoral, poplité, tibial postérieur et pédieux, mesure du temps de recoloration cutanée, auscultation des trajets vasculaires. Devant cette suspicion clinique, l'index de pression systolique est mesuré en 1re intention : un IPS entre 1,00 et 1,40 est normal, inférieur à 0,90 il affirme l'AOMI, inférieur à 0,70 il définit une forme sévère, supérieur à 1,40 il évoque une médiacalcose imposant la mesure de la pression d'orteil. Si l'IPS de repos est normal malgré des symptômes évocateurs, un test de marche sur tapis roulant (protocole de Strandness) peut sensibiliser le diagnostic. L'échodoppler artériel des membres inférieurs est ensuite l'examen d'imagerie de 1re intention pour localiser et quantifier les lésions. L'angioscanner, l'angio-IRM et l'artériographie ne sont demandés qu'en cas de projet de revascularisation.","src":"p. 170-173"},{"id":"225-open-02","type":"OPEN","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":3,"prompt":"Détaillez les grands axes du traitement à visée générale d'un patient présentant une AOMI symptomatique, en précisant les cibles thérapeutiques principales.","rubric":[{"point":"Contrôle des facteurs de risque cardiovasculaire (arrêt du tabac, équilibre du diabète)","weight":2},{"point":"Cibles tensionnelles et de LDL-cholestérol chiffrées","weight":2},{"point":"Traitement antiplaquettaire systématique si AOMI symptomatique","weight":2},{"point":"Statine systématique avec objectif de réduction du LDL","weight":1},{"point":"Intérêt pronostique des IEC et place prudente des bêtabloquants","weight":1},{"point":"Mesures hygiéno-diététiques (IMC, réentraînement, régime méditerranéen)","weight":1}],"model":"Le traitement à visée générale a pour objectif d'améliorer le pronostic cardiovasculaire global. Il repose sur le contrôle strict des facteurs de risque : arrêt du tabac, équilibre du diabète (HbA1c < 7 %), pression artérielle cible autour de 120-129/70-79 mmHg, LDL-cholestérol inférieur à 0,55 g/L avec une réduction d'au moins 50 % sous statine systématique, IMC entre 20 et 25 kg/m², régime méditerranéen et réentraînement supervisé (3 fois par semaine pendant 12 semaines). Un traitement antiplaquettaire (aspirine ou clopidogrel) est indiqué chez tout patient symptomatique. Les IEC ont un intérêt pronostique en abaissant la pression artérielle sous 140/90 mmHg, et les bêtabloquants peuvent être utilisés en cas d'indication formelle, avec prudence en ischémie critique non revascularisable.","src":"p. 175"},{"id":"225-open-03","type":"OPEN","rank":"A","objective":"225-obj-16","tags":["clinique","diagnostic","traitement"],"difficulty":2,"prompt":"Opposez, dans leur présentation clinique, leur diagnostic et leur prise en charge, l'ischémie mésentérique chronique et l'ischémie mésentérique aiguë.","rubric":[{"point":"Ischémie chronique : angor digestif postprandial, amaigrissement, souffle abdominal possible","weight":2},{"point":"Ischémie chronique : diagnostic par échodoppler digestif/angioscanner/angio-IRM, revascularisation programmée","weight":2},{"point":"Ischémie aiguë : triade douleur aiguë pauvre en signes physiques + vidange digestive accélérée + contexte emboligène","weight":2},{"point":"Ischémie aiguë : urgence vitale, diagnostic confirmé par l'angioscanner","weight":1},{"point":"Ischémie aiguë : traitement associant résection intestinale et revascularisation","weight":1}],"model":"L'ischémie mésentérique chronique résulte d'une sténose du tronc cœliaque et/ou des artères mésentériques, se traduisant par un angor digestif postprandial pouvant conduire à un amaigrissement, avec parfois un souffle abdominal. Le diagnostic repose sur l'échodoppler digestif, l'angioscanner ou l'angio-IRM, et le traitement repose sur une revascularisation programmée, de préférence endovasculaire. L'ischémie mésentérique aiguë résulte d'une occlusion brutale (thrombose ou embolie) et constitue une urgence vitale rare grâce aux collatérales : elle associe classiquement une douleur abdominale aiguë pauvre en signes physiques, une vidange digestive accélérée et un contexte emboligène (fibrillation atriale). Le diagnostic est confirmé par l'angioscanner. Le traitement associe résection des segments infarcis et revascularisation en urgence.","src":"p. 166-167, 187"},{"id":"225-qcm-101","type":"QRM","rank":"A","objective":"225-obj-07","tags":["urgence","clinique"],"difficulty":1,"stem":"Quels signes physiques font partie du tableau clinique de l'ischémie aiguë de membre ?","options":[{"t":"Une hyperthermie cutanée localisée du membre","ok":false,"why":"Le membre est au contraire froid, pas chaud."},{"t":"Un membre froid et livide","ok":true,"why":"C'est l'un des signes physiques cardinaux."},{"t":"Une anesthésie ou une paralysie du membre","ok":true,"why":"L'examen neurologique recherche ces déficits, notamment du nerf fibulaire commun."},{"t":"Une douleur à la palpation des masses musculaires","ok":true,"why":"C'est un signe témoignant de la souffrance musculaire."},{"t":"Une abolition des pouls en amont de l'occlusion, les pouls d'aval restant perçus","ok":false,"why":"Les pouls sont abolis en aval de l'occlusion ; avec la froideur, leur niveau d'abolition aide à situer l'occlusion."}],"explanation":"L'ischémie aiguë de membre associe un membre froid, livide, douloureux à la palpation musculaire, avec pouls abolis en aval et éventuels troubles neurologiques (anesthésie, paralysie).","src":"p. 179"},{"id":"225-qcm-102","type":"QRM","rank":"A","objective":"225-obj-07","tags":["physiopathologie","paraclinique"],"difficulty":2,"stem":"Concernant la chronologie de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Les cellules nerveuses souffrent dès 2 heures d'ischémie","ok":true,"why":"C'est le délai de souffrance nerveuse cité."},{"t":"Le syndrome des loges est sans rapport avec l'œdème musculaire","ok":false,"why":"Il résulte au contraire de l'œdème musculaire dans une loge aponévrotique inextensible."},{"t":"Les cellules musculaires ne souffrent qu'après 24 heures d'ischémie","ok":false,"why":"Les cellules musculaires souffrent dans les 6 à 8 heures (rhabdomyolyse) ; la 24e heure correspond à l'apparition de la nécrose cutanée."},{"t":"Les cellules musculaires souffrent avant les cellules nerveuses","ok":false,"why":"C'est l'inverse : les cellules nerveuses souffrent en premier, dès 2 heures."},{"t":"La nécrose cutanée apparaît dès la 2e heure","ok":false,"why":"La nécrose cutanée apparaît à partir de la 24e heure ; les 2 premières heures correspondent à la souffrance des cellules nerveuses."}],"explanation":"Les cellules nerveuses souffrent dès 2 heures, les cellules musculaires dès 6-8 heures (rhabdomyolyse), et la nécrose cutanée apparaît vers la 24e heure ; l'œdème musculaire peut causer un syndrome des loges.","trap":"Ne pas inverser l'ordre de souffrance : nerfs avant muscles.","src":"p. 178"},{"id":"225-qcm-103","type":"QRM","rank":"A","objective":"225-obj-07","tags":["physiopathologie","complications"],"difficulty":2,"stem":"Quelles anomalies métaboliques peuvent survenir lors de la reperfusion d'un membre après ischémie aiguë prolongée ?","options":[{"t":"Une hypokaliémie","ok":false,"why":"C'est au contraire une hyperkaliémie qui est observée."},{"t":"Une hyperkaliémie","ok":true,"why":"Elle fait partie du syndrome de revascularisation."},{"t":"Une hypercalcémie","ok":false,"why":"C'est une hypocalcémie qui est décrite parmi les conséquences métaboliques de la reperfusion."},{"t":"Une alcalose métabolique","ok":false,"why":"La reperfusion libère des métabolites acides : c'est une acidose métabolique qui est observée."},{"t":"Une myoglobinurie","ok":true,"why":"Elle traduit la lyse musculaire massive."}],"explanation":"Le syndrome de revascularisation associe hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie/myoglobinurie, hypocalcémie et hyperphosphorémie, pouvant conduire à une insuffisance rénale aiguë.","src":"p. 178-179"},{"id":"225-qcm-104","type":"QRM","rank":"A","objective":"225-obj-07","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Selon la classification de sévérité de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Le grade IIa correspond à une ischémie immédiatement menaçante avec déficit moteur modéré","ok":false,"why":"C'est le grade IIb qui correspond à cette description ; le grade IIa est seulement discrètement menaçant."},{"t":"Cette classification ne prend en compte que les données de l'imagerie","ok":false,"why":"Elle repose sur l'examen clinique : déficit sensitif et moteur."},{"t":"Le grade III (irréversible) s'accompagne d'une perte tissulaire et de séquelles inévitables","ok":true,"why":"C'est le pronostic attendu à ce stade."},{"t":"Le grade IIb impose une prise en charge immédiate pour espérer une récupération","ok":true,"why":"Le déficit y est présent au-delà des orteils avec un déficit moteur modéré."},{"t":"Le grade I (viable) ne présente ni déficit sensitif ni déficit moteur","ok":true,"why":"C'est la définition du grade I, sans menace immédiate."}],"explanation":"La classification de Rutherford de l'ischémie aiguë distingue le grade I (viable, aucun déficit), IIa (discrètement menaçant), IIb (immédiatement menaçant, déficit moteur modéré, urgence de prise en charge) et III (irréversible).","trap":"Ne pas confondre IIa (discrètement menaçant) et IIb (immédiatement menaçant, déficit moteur).","src":"p. 179"},{"id":"225-qcm-105","type":"QRM","rank":"A","objective":"225-obj-09","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Concernant la démarche diagnostique devant une ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"En cas de déficit neurologique (grade II), une imagerie doit précéder la revascularisation","ok":false,"why":"En cas d'atteinte neurologique (grade II), aucune exploration ne doit retarder l'intervention ; un échodoppler n'est envisageable sans perte de temps qu'en l'absence d'atteinte neurologique (notamment grade I)."},{"t":"Un échodoppler peut être réalisé sans perte de temps si le tableau clinique le permet (grade I sans déficit)","ok":true,"why":"Il n'est envisageable que dans les formes les moins sévères."},{"t":"L'artériographie est systématiquement réalisée avant le transfert au bloc opératoire","ok":false,"why":"Elle est le plus souvent réalisée au bloc opératoire lui-même pour guider le geste."},{"t":"Le bilan de coagulation doit être différé après la revascularisation","ok":false,"why":"Il doit être prélevé avant le début de l'anticoagulation, dès le diagnostic."},{"t":"Le diagnostic repose sur l'angioscanner, à obtenir avant d'alerter l'équipe chirurgicale","ok":false,"why":"Le diagnostic est essentiellement clinique et l'équipe chirurgicale doit être alertée au plus tôt ; aucune exploration ne doit retarder l'intervention."}],"explanation":"Le diagnostic d'ischémie aiguë est clinique ; aucun examen ne doit retarder l'intervention en cas de déficit neurologique. Un échodoppler est possible sans perte de temps en cas de grade I sans atteinte neurologique, et l'artériographie est le plus souvent réalisée au bloc opératoire.","src":"p. 180"},{"id":"225-qcm-106","type":"QRM","rank":"A","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"stem":"Quels éléments orientent vers une thrombose artérielle in situ plutôt qu'une embolie devant une ischémie aiguë de membre ?","options":[{"t":"Un sujet âgé avec antécédent d'AOMI","ok":true,"why":"C'est le terrain typique de la thrombose in situ."},{"t":"Une prothèse valvulaire cardiaque","ok":false,"why":"Les valvulopathies et prothèses valvulaires sont des causes cardiaques d'embolie : elles orientent vers une embolie, non vers une thrombose in situ."},{"t":"Des palpitations précédant la douleur","ok":false,"why":"Cet élément oriente vers une origine cardiaque emboligène, donc vers une embolie."},{"t":"Une douleur d'intensité moyenne d'installation progressive","ok":true,"why":"La collatéralité préalable explique une installation moins brutale."},{"t":"Une douleur brutale et sévère chez un sujet jeune sans antécédent vasculaire","ok":false,"why":"Ce tableau oriente au contraire vers une embolie sur artère saine."}],"explanation":"La thrombose in situ touche typiquement un sujet âgé déjà artériopathe, avec une douleur d'installation progressive grâce à la collatéralité ; l'embolie touche un sujet plus jeune sur artères saines, avec douleur brutale et sévère, parfois précédée de palpitations.","src":"p. 181"},{"id":"225-qcm-107","type":"QRM","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"stem":"Quelles causes cardiaques d'embolie artérielle des membres inférieurs sont citées dans le référentiel ?","options":[{"t":"L'endocardite infectieuse","ok":true,"why":"Les végétations peuvent être source d'embolies artérielles."},{"t":"Le foramen ovale perméable associé à un anévrisme du septum interatrial","ok":true,"why":"Cette association est citée parmi les causes cardiaques d'embolie."},{"t":"La fibrillation atriale","ok":true,"why":"C'est la principale cause cardiaque citée d'embolie artérielle."},{"t":"La péricardite aiguë isolée","ok":false,"why":"Elle n'est pas citée comme cause d'embolie artérielle des membres."},{"t":"Le myxome de l'atrium","ok":true,"why":"C'est une tumeur cardiaque emboligène citée."}],"explanation":"Les causes cardiaques d'embolie artérielle citées comprennent la fibrillation atriale, le foramen ovale perméable avec anévrisme du septum, l'infarctus avec faux anévrisme, l'endocardite, les valvulopathies/prothèses et le myxome de l'atrium.","src":"p. 181"},{"id":"225-qcm-108","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":2,"stem":"Quelles mesures font partie du traitement médical immédiat de l'ischémie aiguë de membre ?","options":[{"t":"Un positionnement du membre strictement horizontal sans soin local particulier","ok":false,"why":"Une position légèrement déclive et des soins locaux protecteurs sont recommandés."},{"t":"Une anticoagulation par héparine non fractionnée, débutée seulement après la revascularisation","ok":false,"why":"L'héparine non fractionnée est débutée dès le diagnostic, après prélèvement du bilan de coagulation (bolus de 5 000 UI puis perfusion continue, TCA entre 2 et 3)."},{"t":"Un remplissage vasculaire en cas d'instabilité hémodynamique","ok":true,"why":"Il vise à corriger l'état hémodynamique si nécessaire."},{"t":"Des antalgiques de palier 3 si nécessaire","ok":true,"why":"La douleur est souvent intense et nécessite des antalgiques puissants."},{"t":"Une oxygénothérapie","ok":true,"why":"Elle fait partie des mesures de soutien immédiates."}],"explanation":"Le traitement médical immédiat associe héparine non fractionnée, antalgiques de palier 3, oxygénothérapie, correction hémodynamique et soins locaux protecteurs en position légèrement déclive.","src":"p. 182"},{"id":"225-qcm-109","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement","paraclinique"],"difficulty":2,"stem":"Concernant l'héparinothérapie initiale de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"La cible de TCA est comprise entre 2 et 3","ok":true,"why":"C'est la cible de TCA retenue."},{"t":"Un bolus initial de 5 000 UI est administré","ok":true,"why":"C'est la posologie de bolus citée."},{"t":"L'héparine est débutée seulement après le résultat du bilan de coagulation complet","ok":false,"why":"Elle est débutée dès le diagnostic, après le simple prélèvement du bilan, sans en attendre le résultat."},{"t":"Une héparine de bas poids moléculaire est privilégiée en 1re intention","ok":false,"why":"C'est l'héparine non fractionnée qui est utilisée, pas une héparine de bas poids moléculaire."},{"t":"La perfusion continue est de 500 UI/kg/jour","ok":true,"why":"C'est la posologie d'entretien citée."}],"explanation":"L'anticoagulation initiale associe un bolus de 5 000 UI d'héparine non fractionnée puis une perfusion continue de 500 UI/kg/j, pour une cible de TCA entre 2 et 3, débutée dès le diagnostic après simple prélèvement du bilan de coagulation.","src":"p. 182"},{"id":"225-qcm-110","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"stem":"Quelles propositions concernant la revascularisation de l'ischémie aiguë de membre sont exactes ?","options":[{"t":"Une aponévrotomie de décompression est systématique en cas de revascularisation tardive","ok":true,"why":"Elle prévient le syndrome des loges après revascularisation tardive."},{"t":"La thrombolyse in situ est préférée en cas de lit d'aval de mauvaise qualité et d'ischémie peu sévère","ok":true,"why":"C'est l'indication décrite pour cette technique."},{"t":"L'embolectomie à la sonde de Fogarty est le traitement de référence de l'embolie sur artère saine","ok":true,"why":"C'est la méthode de référence citée pour ce tableau."},{"t":"L'amputation d'emblée peut être proposée en cas d'ischémie dépassée","ok":true,"why":"C'est l'indication d'une amputation immédiate."},{"t":"Le pontage est la méthode de revascularisation de 1re intention dans tous les cas","ok":false,"why":"Le pontage est envisagé en dernier ressort, pas en première intention."}],"explanation":"L'embolectomie à la sonde de Fogarty est la méthode de référence pour l'embolie sur artère saine ; la thrombolyse est réservée au lit d'aval de mauvaise qualité avec ischémie peu sévère ; le pontage est un dernier recours, l'aponévrotomie est systématique si revascularisation tardive.","src":"p. 182-183"},{"id":"225-qcm-111","type":"QRM","rank":"A","objective":"225-obj-10","tags":["définition"],"difficulty":1,"stem":"Comment définit-on un anévrisme artériel selon le référentiel ?","options":[{"t":"Une atteinte qui ne peut concerner que l'aorte thoracique","ok":false,"why":"L'anévrisme peut toucher l'aorte, les artères poplitées et iliaques, entre autres."},{"t":"Une perte du parallélisme des bords vasculaires","ok":true,"why":"C'est un élément constitutif de la définition de l'anévrisme."},{"t":"Une augmentation de diamètre d'au moins 20 % par rapport au segment d'amont","ok":false,"why":"Le seuil retenu est une augmentation de plus de 50 %, pas 20 %."},{"t":"Une simple ectasie transitoire réversible de l'artère","ok":false,"why":"L'anévrisme est au contraire focal et permanent, pas transitoire."},{"t":"Une dilatation focale et permanente avec augmentation de diamètre de plus de 50 % par rapport au segment d'amont","ok":true,"why":"C'est la définition retenue de l'anévrisme."}],"explanation":"Un anévrisme correspond à une dilatation focale et permanente de l'artère, avec perte du parallélisme des bords vasculaires et augmentation de diamètre de plus de 50 % par rapport au segment d'amont.","src":"p. 183"},{"id":"225-qcm-112","type":"QRM","rank":"B","objective":"225-obj-11","difficulty":2,"tags":["étiologie"],"stem":"Quelles causes non athéromateuses d'anévrisme de l'aorte abdominale sont citées dans le référentiel ?","options":[{"t":"La maladie de Marfan","ok":true,"why":"C'est une maladie du tissu élastique citée parmi les formes familiales."},{"t":"Le syndrome de Loeys-Dietz","ok":true,"why":"C'est une autre maladie du tissu élastique citée."},{"t":"La maladie de Buerger","ok":false,"why":"Elle est citée parmi les artériopathies inflammatoires des membres inférieurs, pas parmi les causes d'AAA ; les aortites en cause sont notamment Takayasu et Horton."},{"t":"Le diabète de type 2","ok":false,"why":"Le diabète n'est pas cité comme cause d'AAA ; les diabétiques seraient même moins souvent atteints."},{"t":"Le syndrome d'Ehlers-Danlos","ok":true,"why":"C'est une maladie du tissu élastique citée parmi les formes familiales."}],"explanation":"Dans 80-90 % des cas, l'AAA est athéromateux ; les formes non athéromateuses comprennent les maladies du tissu élastique (Marfan, Ehlers-Danlos, Loeys-Dietz) et les aortites (Takayasu, Horton).","src":"p. 184"},{"id":"225-qcm-113","type":"QRM","rank":"A","objective":"225-obj-12","tags":["clinique","urgence"],"difficulty":2,"stem":"Quels tableaux cliniques peuvent révéler un anévrisme de l'aorte abdominale ?","options":[{"t":"Une hypertension artérielle rénovasculaire isolée","ok":false,"why":"Ce tableau évoque une sténose de l'artère rénale, pas un anévrisme de l'aorte."},{"t":"Une hémorragie digestive par fistule aorto-digestive","ok":true,"why":"C'est une autre complication rare décrite."},{"t":"Une douleur abdominale ou lombaire avec choc hémorragique","ok":true,"why":"Elle évoque une fissuration ou une rupture, urgence vitale."},{"t":"Une insuffisance cardiaque à débit élevé par fistule aorto-cave","ok":true,"why":"C'est une complication rare décrite dans le texte."},{"t":"Une découverte fortuite d'une masse battante et expansive para-ombilicale","ok":true,"why":"C'est le mode de révélation le plus fréquent, en forme asymptomatique."}],"explanation":"L'AAA peut être découvert de façon fortuite (masse battante), ou se révéler par une complication : rupture/fissuration (urgence vitale), fistule aorto-cave ou aorto-digestive, embolie, compression ou syndrome inflammatoire.","src":"p. 183-184"},{"id":"225-qcm-114","type":"QRM","rank":"A","objective":"225-obj-13","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Quelles propositions concernant les examens complémentaires de l'AAA sont exactes ?","options":[{"t":"L'échographie abdominale est l'examen de dépistage et de suivi","ok":true,"why":"Elle permet de mesurer le diamètre et d'assurer le suivi."},{"t":"L'IRM est une alternative possible en cas de contre-indication au scanner","ok":true,"why":"Elle peut remplacer le scanner en cas de contre-indication."},{"t":"L'artériographie donne une mesure fiable du diamètre de l'anévrisme","ok":false,"why":"Elle sous-estime la taille en ne visualisant que la lumière circulante, du fait du thrombus mural."},{"t":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence","ok":true,"why":"Il précise le diamètre et l'anatomie avant une intervention."},{"t":"L'échographie permet de rechercher d'autres localisations anévrismales associées","ok":true,"why":"Elle recherche notamment les localisations poplitées et iliaques."}],"explanation":"L'échographie dépiste et surveille l'AAA, le scanner injecté est l'examen préthérapeutique de référence, l'IRM est une alternative ; l'artériographie n'est pas fiable pour mesurer le diamètre en raison du thrombus mural.","src":"p. 184-185"},{"id":"225-qcm-115","type":"QRM","rank":"A","objective":"225-obj-14","tags":["traitement","suivi"],"difficulty":3,"stem":"Concernant la surveillance et le traitement d'un AAA asymptomatique, quelles propositions sont exactes ?","options":[{"t":"Une intervention programmée est envisagée dès 40 mm de diamètre","ok":false,"why":"L'intervention « à froid » est programmée au-delà de 50-55 mm, seuil où le risque de rupture devient important ; en dessous, l'anévrisme est surveillé par échographie."},{"t":"La poursuite du tabagisme accélère la croissance de l'anévrisme","ok":true,"why":"La progression est environ 3 fois plus rapide chez le fumeur actif."},{"t":"Le traitement endovasculaire est toujours contre-indiqué chez le sujet à haut risque chirurgical","ok":false,"why":"Il est au contraire préféré chez ces patients si l'anatomie est favorable."},{"t":"La surveillance échographique est renforcée (tous les 6 mois) au-delà de 45 mm","ok":true,"why":"C'est le seuil de renforcement de la surveillance."},{"t":"Le diamètre est le principal facteur prédictif du risque de rupture","ok":true,"why":"C'est le facteur prédictif principal cité."}],"explanation":"Le diamètre prédit le risque de rupture ; la surveillance échographique est renforcée à 6 mois au-delà de 45 mm ; l'intervention (chirurgie ou endoprothèse) est programmée au-delà de 50-55 mm, l'endoprothèse étant préférée chez les sujets à haut risque chirurgical si l'anatomie le permet.","src":"p. 185-186"},{"id":"225-qru-101","type":"QRU","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":1,"stem":"Quelle est la méthode de revascularisation de référence d'une ischémie aiguë de membre par embolie sur artère saine ?","options":[{"t":"L'embolectomie à la sonde de Fogarty","ok":true,"why":"C'est la méthode de référence citée pour ce mécanisme."},{"t":"Le pontage extra-anatomique d'emblée","ok":false,"why":"Le pontage est envisagé en dernier ressort, pas en première intention."},{"t":"L'amputation d'emblée","ok":false,"why":"Elle n'est indiquée qu'en cas d'ischémie dépassée."},{"t":"L'aponévrotomie isolée","ok":false,"why":"Elle traite le syndrome des loges mais ne revascularise pas le membre."},{"t":"La thrombolyse systémique intraveineuse","ok":false,"why":"Ce n'est pas la technique décrite dans ce contexte ; la thrombolyse in situ est réservée à d'autres situations."}],"explanation":"L'embolectomie à la sonde de Fogarty sous contrôle angiographique est la méthode de référence pour traiter une embolie sur artère saine.","src":"p. 182"},{"id":"225-qru-102","type":"QRU","rank":"A","objective":"225-obj-10","tags":["paraclinique","définition"],"difficulty":1,"stem":"Quelle augmentation de diamètre par rapport au segment d'amont définit un anévrisme ?","options":[{"t":"Il n'existe pas de seuil chiffré","ok":false,"why":"Un seuil chiffré de plus de 50 % est explicitement retenu."},{"t":"Plus de 50 %","ok":true,"why":"C'est le seuil retenu par la définition."},{"t":"Plus de 10 %","ok":false,"why":"Ce seuil est trop faible par rapport à la définition retenue."},{"t":"Plus de 25 %","ok":false,"why":"Ce seuil est trop faible par rapport à la définition retenue."},{"t":"Plus de 100 %","ok":false,"why":"Ce seuil est trop élevé par rapport à la définition retenue."}],"explanation":"Un anévrisme est défini par une augmentation de diamètre de plus de 50 % par rapport au segment artériel sus-jacent, avec perte du parallélisme des bords.","src":"p. 183"},{"id":"225-qru-103","type":"QRU","rank":"A","objective":"225-obj-15","tags":["urgence"],"difficulty":1,"stem":"Quel examen d'imagerie ne doit pas retarder la prise en charge d'un anévrisme de l'aorte abdominale rompu chez un patient en choc ?","options":[{"t":"L'échographie transœsophagienne","ok":false,"why":"Elle n'est pas l'examen indiqué pour confirmer une rupture d'AAA."},{"t":"L'IRM abdominale complète","ok":false,"why":"Elle n'est pas indiquée en urgence chez un patient en choc."},{"t":"Le test de marche","ok":false,"why":"Il n'a aucune place dans ce contexte d'urgence vitale."},{"t":"L'artériographie diagnostique","ok":false,"why":"Elle n'a pas d'utilité diagnostique pour mesurer ou confirmer l'anévrisme dans ce contexte."},{"t":"Le scanner abdominal diagnostique","ok":true,"why":"C'est le seul examen qui ne doit pas retarder l'intervention en urgence absolue."}],"explanation":"En cas de rupture d'AAA avec choc hémorragique, seul le scanner diagnostique ne doit pas retarder la prise en charge chirurgicale ou endovasculaire en urgence absolue.","src":"p. 186"},{"id":"225-qru-105","type":"QRU","rank":"A","objective":"225-obj-06","tags":["suivi","paraclinique"],"difficulty":2,"stem":"Quelle est approximativement la mortalité à 5 ans des patients en ischémie critique ?","options":[{"t":"Environ 70 %","ok":true,"why":"C'est le chiffre de mortalité à 5 ans retenu pour l'ischémie critique."},{"t":"Environ 90 %","ok":false,"why":"Ce chiffre surestime la mortalité réellement rapportée."},{"t":"Environ 50 %","ok":false,"why":"Ce n'est pas le chiffre retenu ; la mortalité en ischémie critique est plus élevée."},{"t":"Environ 20 %","ok":false,"why":"Ce chiffre correspond au taux de décès à 5 ans chez les claudicants, pas en ischémie critique."},{"t":"Environ 5 %","ok":false,"why":"Ce chiffre correspond au risque d'amputation à 5 ans chez les claudicants."}],"explanation":"Chez le patient en ischémie critique, la mortalité à 5 ans avoisine 70 %, bien supérieure à celle des claudicants (20 % à 5 ans).","src":"p. 178"},{"id":"225-qroc-101","type":"QROC","rank":"A","objective":"225-obj-07","tags":["physiopathologie","paraclinique"],"difficulty":1,"question":"Au bout de combien de temps les cellules nerveuses commencent-elles à souffrir en cas d'ischémie aiguë de membre ?","answer":"Dès 2 heures","accept":["2 h","2 heures"],"keywords":["2"],"explanation":"Les cellules nerveuses sont les premières à souffrir de l'hypoxie, dès 2 heures d'ischémie.","src":"p. 178"},{"id":"225-qroc-102","type":"QROC","rank":"A","objective":"225-obj-07","tags":["complications"],"difficulty":1,"question":"Quel geste chirurgical traite le syndrome des loges au cours d'une ischémie aiguë de membre ?","answer":"L'aponévrotomie de décharge","accept":["aponévrotomie","fasciotomie"],"keywords":["aponévrotomie"],"explanation":"Seule une aponévrotomie (section chirurgicale de l'aponévrose) de décharge permet de libérer le tissu musculaire comprimé et de restaurer la circulation capillaire.","src":"p. 178"},{"id":"225-qroc-103","type":"QROC","rank":"A","objective":"225-obj-07","tags":["diagnostic"],"difficulty":1,"question":"Quel nerf est le plus souvent touché par le déficit neurologique de l'ischémie aiguë de membre, se traduisant par une impossibilité de relever le pied ?","answer":"Le nerf fibulaire commun (nerf sciatique poplité externe)","accept":["fibulaire commun","sciatique poplité externe","spe"],"keywords":["fibulaire"],"explanation":"L'atteinte du nerf fibulaire commun se traduit par une impossibilité de relever le pied (steppage), signe de gravité de l'ischémie.","src":"p. 179"},{"id":"225-qroc-104","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"question":"Quel terrain est classiquement associé à une thrombose artérielle in situ à l'origine d'une ischémie aiguë ?","answer":"Un sujet âgé avec facteurs de risque cardiovasculaire, souvent déjà artériopathe","accept":["sujet âgé artériopathe"],"keywords":["âgé","artériopathe"],"explanation":"La thrombose in situ concerne le plus souvent un sujet âgé aux facteurs de risque cardiovasculaire, avec souvent une AOMI préexistante.","src":"p. 181"},{"id":"225-qroc-105","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":1,"question":"Quelle est la principale cause cardiaque d'embolie artérielle des membres ?","answer":"La fibrillation atriale","accept":["fa","arythmie complète par fibrillation atriale"],"keywords":["fibrillation"],"explanation":"Parmi les causes cardiaques d'embolie artérielle, les troubles du rythme, en premier lieu la fibrillation atriale, sont les plus fréquemment cités.","src":"p. 181"},{"id":"225-qroc-106","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","paraclinique"],"difficulty":2,"question":"Quelle est la cible de TCA sous héparine non fractionnée dans le traitement de l'ischémie aiguë de membre ?","answer":"Entre 2 et 3","accept":["2-3","2 à 3"],"keywords":["2","3"],"explanation":"L'anticoagulation par héparine non fractionnée (bolus 5 000 UI puis 500 UI/kg/j) vise une cible de TCA comprise entre 2 et 3.","src":"p. 182"},{"id":"225-qroc-107","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quel type de molécule est utilisé pour traiter l'hyperkaliémie sévère lors du syndrome de revascularisation, en dehors de la dialyse ?","answer":"Un chélateur du potassium (polystyrène sulfonate de sodium)","accept":["chélateur de potassium","polystyrène sulfonate","kayexalate"],"keywords":["chélateur","potassium"],"explanation":"L'hyperkaliémie du syndrome de revascularisation est traitée par un chélateur de potassium (polystyrène sulfonate de sodium), voire par dialyse en cas d'échec.","src":"p. 183"},{"id":"225-qroc-108","type":"QROC","rank":"A","objective":"225-obj-10","tags":["définition","épidémiologie"],"difficulty":1,"question":"Quel segment de l'aorte est le plus souvent le siège d'un anévrisme de l'aorte abdominale ?","answer":"Le segment sous-rénal","accept":["sous-rénal","aorte sous-rénale"],"keywords":["sous-rénal"],"explanation":"Dans la grande majorité des cas, l'AAA est localisé au-dessous des artères rénales, c'est-à-dire sur le segment sous-rénal de l'aorte.","src":"p. 183"},{"id":"225-qroc-109","type":"QROC","rank":"B","objective":"225-obj-10","tags":["paraclinique","suivi"],"difficulty":2,"question":"Combien de fois le porteur d'un AAA a-t-il plus de risque de décéder d'une complication cardiovasculaire que de la rupture de son anévrisme ?","answer":"Environ 10 fois plus","accept":["10 fois"],"keywords":["10"],"explanation":"Le porteur d'un AAA a un risque de décès cardiovasculaire (coronarien ou cérébral) environ 10 fois supérieur à celui de mourir de la rupture de son anévrisme.","src":"p. 184"},{"id":"225-qroc-110","type":"QROC","rank":"A","objective":"225-obj-13","tags":["paraclinique"],"difficulty":1,"question":"Quel examen constitue la référence pour le bilan préthérapeutique d'un AAA en vue d'une intervention ?","answer":"Le scanner abdominopelvien avec injection de produit de contraste","accept":["scanner injecté","angioscanner abdominal"],"keywords":["scanner"],"explanation":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence, précisant le diamètre et l'anatomie de l'anévrisme.","src":"p. 185"},{"id":"225-qroc-111","type":"QROC","rank":"A","objective":"225-obj-14","tags":["traitement","paraclinique"],"difficulty":2,"question":"À partir de quel diamètre un AAA est-il habituellement proposé pour une intervention programmée « à froid » ?","answer":"50 à 55 mm","accept":["50-55 mm"],"keywords":["50","55"],"explanation":"Le risque de rupture devenant important au-delà de 50-55 mm, une intervention programmée (chirurgicale ou endovasculaire) est alors proposée.","src":"p. 186"},{"id":"225-qroc-112","type":"QROC","rank":"B","objective":"225-obj-15","tags":["suivi","complications"],"difficulty":2,"question":"Quelle complication à long terme doit être recherchée par surveillance après la pose d'une endoprothèse aortique ?","answer":"Les endofuites","accept":["endofuite"],"keywords":["endofuite"],"explanation":"Après endoprothèse, une surveillance scanner/échographique au long cours recherche des endofuites, qui peuvent faire progresser voire rompre l'anévrisme.","src":"p. 186"},{"id":"225-open-11","type":"OPEN","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":3,"prompt":"Un homme de 74 ans en fibrillation atriale non anticoagulée présente, depuis 3 heures, une douleur brutale et intense du membre inférieur droit avec pied froid, pâle, pouls abolis, sans déficit neurologique. Décrivez votre prise en charge diagnostique et thérapeutique immédiate.","rubric":[{"point":"Reconnaître une ischémie aiguë de membre, grade I (viable, sans déficit)","weight":2},{"point":"Diagnostic essentiellement clinique, ne pas retarder la prise en charge par des examens inutiles","weight":1},{"point":"Anticoagulation par héparine non fractionnée dès le diagnostic après prélèvement du bilan de coagulation","weight":2},{"point":"Antalgiques, oxygénothérapie, soins locaux et correction hémodynamique si besoin","weight":1},{"point":"Revascularisation en urgence adaptée au mécanisme probable (embolectomie de Fogarty évoquée devant le contexte de fibrillation atriale)","weight":2},{"point":"Bilan étiologique cardiaque (ECG, auscultation, palpation abdominale) sans retarder le traitement","weight":1},{"point":"Surveillance des conséquences métaboliques de la reperfusion","weight":1}],"model":"Ce tableau correspond à une ischémie aiguë de membre de grade I (viable, sans déficit sensitivomoteur), probablement d'origine embolique compte tenu de la fibrillation atriale non anticoagulée et du caractère brutal de la douleur. Le diagnostic reste clinique et ne doit pas être retardé par des examens complémentaires inutiles ; un échodoppler peut être réalisé sans perte de temps devant ce grade I. Le traitement médical immédiat associe une anticoagulation par héparine non fractionnée (bolus puis perfusion continue pour une cible de TCA entre 2 et 3) débutée dès le diagnostic après simple prélèvement du bilan de coagulation, des antalgiques de palier 3 si besoin, une oxygénothérapie, une correction de l'état hémodynamique et des soins locaux protecteurs. Une revascularisation est organisée en urgence, l'embolectomie à la sonde de Fogarty étant la méthode de référence en cas d'embolie sur artère saine. L'examen clinique est complété par une auscultation cardiaque, un ECG et une palpation abdominale à la recherche d'un anévrisme, dans le cadre du bilan étiologique. Après revascularisation, les conséquences métaboliques (hyperkaliémie, acidose, myoglobinurie) doivent être activement surveillées.","src":"p. 178-182"},{"id":"225-open-12","type":"OPEN","rank":"A","objective":"225-obj-14","tags":["traitement","suivi"],"difficulty":2,"prompt":"Expliquez la stratégie de surveillance et de traitement d'un anévrisme de l'aorte abdominale asymptomatique, depuis sa découverte jusqu'à son éventuelle prise en charge chirurgicale.","rubric":[{"point":"Le diamètre est le principal facteur prédictif de rupture","weight":2},{"point":"Surveillance échographique répétée, renforcée à 6 mois au-delà de 45 mm","weight":2},{"point":"Contrôle des facteurs de risque, en particulier l'arrêt du tabac","weight":1},{"point":"Seuil d'intervention programmée à 50-55 mm","weight":2},{"point":"Choix entre chirurgie conventionnelle et endoprothèse selon le terrain et l'anatomie","weight":2},{"point":"Surveillance post-thérapeutique adaptée à la technique (échodoppler ou scanner/endofuites)","weight":1}],"model":"Le diamètre de l'anévrisme est le principal facteur prédictif du risque de rupture. Tant que le diamètre reste inférieur au seuil d'intervention, une surveillance échographique répétée est mise en place, renforcée tous les 6 mois au-delà de 45 mm. Le contrôle des facteurs de risque, en particulier l'arrêt du tabac (qui accélère la croissance d'environ 3 fois), est indispensable pendant tout le suivi. Au-delà de 50-55 mm, le risque de rupture devient suffisamment important pour proposer une intervention « à froid » : chirurgie conventionnelle à ciel ouvert (exclusion et interposition d'une prothèse) ou traitement endovasculaire par endoprothèse, moins invasif et préféré chez les sujets à haut risque chirurgical si l'anatomie est favorable. Après chirurgie conventionnelle, la surveillance repose sur l'échodoppler (recherche de faux anévrisme anastomotique) ; après endoprothèse, une surveillance scanner/échographique au long cours recherche des endofuites pouvant faire reprogresser l'anévrisme.","src":"p. 185-186"},{"id":"225-open-13","type":"OPEN","rank":"A","objective":"225-obj-15","tags":["urgence","clinique"],"difficulty":2,"prompt":"Un homme de 70 ans, connu porteur d'un anévrisme de l'aorte abdominale de 48 mm suivi par échographie, se présente aux urgences pour une douleur lombaire brutale et une tension artérielle à 85/50 mmHg. Quelle est votre prise en charge ?","rubric":[{"point":"Reconnaître une suspicion de rupture d'AAA, urgence vitale absolue","weight":2},{"point":"Ne pas retarder la prise en charge par des examens autres que le scanner diagnostique","weight":2},{"point":"Orientation immédiate vers un centre de chirurgie vasculaire","weight":1},{"point":"Scanner abdominal en urgence pour confirmer le diagnostic et préciser la localisation","weight":2},{"point":"Discussion entre chirurgie conventionnelle et endoprothèse selon le terrain et l'expérience de l'équipe","weight":1}],"model":"Cette présentation (douleur lombaire brutale et hypotension chez un porteur connu d'AAA) évoque fortement une fissuration ou une rupture d'anévrisme, urgence absolue. Le patient doit être orienté sans délai vers un centre spécialisé de chirurgie vasculaire. Seul le scanner abdominal diagnostique, confirmant le diagnostic et précisant la localisation de la rupture, ne doit pas retarder la prise en charge chez un patient en état de choc. Le traitement, chirurgical conventionnel ou par endoprothèse selon le terrain et l'expérience de l'équipe, doit être réalisé le plus rapidement possible, les chances de survie étant d'autant plus grandes que la prise en charge est rapide.","src":"p. 186"},{"id":"225-qroc-401","type":"QROC","rank":"A","objective":"225-obj-17","tags":["diagnostic"],"difficulty":1,"question":"À quel moment surviennent les douleurs abdominales de l'angor digestif (ischémie mésentérique chronique) ?","answer":"En postprandial","accept":["postprandial","apres les repas","post-prandial"],"keywords":["prandi"],"explanation":"L'ischémie mésentérique chronique symptomatique réalise un angor digestif : douleurs postprandiales conduisant à une restriction alimentaire et un amaigrissement.","src":"p. 166-167"},{"id":"225-qroc-402","type":"QROC","rank":"A","objective":"225-obj-17","tags":["examens","urgence"],"difficulty":1,"question":"Quel examen confirme le diagnostic d'ischémie mésentérique aiguë ?","answer":"L'angioscanner abdominal","accept":["angioscanner","angio-scanner","angiotdm"],"keywords":["angioscan"],"explanation":"L'ischémie mésentérique aiguë, urgence vitale, est confirmée par l'angioscanner, qui ne doit pas être retardé.","src":"p. 167, 187"},{"id":"225-qroc-403","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Quel syndrome associe atteinte aorto-iliaque, claudication fessière et troubles de l'érection ?","answer":"Le syndrome de Leriche","accept":["leriche"],"keywords":["leriche"],"explanation":"Le syndrome de Leriche traduit une atteinte aorto-iliaque avec claudication fessière et troubles de l'érection.","src":"p. 168-170"},{"id":"225-qroc-404","type":"QROC","rank":"A","objective":"225-obj-03","tags":["définition","diagnostic"],"difficulty":2,"question":"Quelle pression de cheville définit l'ischémie critique ?","answer":"< 50 mmHg","accept":["50"],"keywords":["50"],"explanation":"L'ischémie critique se définit par une pression de cheville < 50 mmHg ou une pression d'hallux < 30 mmHg, avec douleurs de décubitus > 15 jours.","src":"p. 168-170"},{"id":"225-qroc-405","type":"QROC","rank":"A","objective":"225-obj-04","tags":["examens","diagnostic"],"difficulty":1,"question":"En dessous de quelle valeur d'IPS l'AOMI est-elle qualifiée de sévère ?","answer":"IPS < 0,70","accept":["0,7","0.7","0,70"],"keywords":["0,7"],"explanation":"IPS normal 1,00-1,40 ; AOMI si < 0,90 ; AOMI sévère si < 0,70 ; médiacalcose si > 1,40.","src":"p. 170-173"},{"id":"225-qroc-406","type":"QROC","rank":"A","objective":"225-obj-04","tags":["examens"],"difficulty":3,"question":"Quelle baisse de l'IPS après un test de marche est évocatrice d'AOMI ?","answer":"Une baisse > 20 %","accept":["20"],"keywords":["20"],"explanation":"Après effort, une baisse de pression de cheville > 30 mmHg ou de l'IPS > 20 % est évocatrice d'AOMI chez un patient symptomatique à IPS de repos normal.","src":"p. 170-173"},{"id":"225-qroc-407","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelle classe de traitement antithrombotique est indiquée chez tout patient ayant une AOMI symptomatique ?","answer":"Un antiplaquettaire (aspirine ou clopidogrel)","accept":["antiplaquettaire","antiagregant","aspirine","clopidogrel"],"keywords":["plaquet"],"explanation":"Un antiplaquettaire (aspirine ou clopidogrel) est indiqué chez tout AOMI symptomatique ; il est discuté si l'AOMI est asymptomatique isolée.","src":"p. 175-178"},{"id":"225-qroc-408","type":"QROC","rank":"A","objective":"225-obj-06","tags":["pronostic"],"difficulty":2,"question":"Quelle est la mortalité à 5 ans des patients en ischémie critique ?","answer":"Environ 70 %","accept":["70"],"keywords":["70"],"explanation":"Le pronostic de l'ischémie permanente est grave, comparable à certains cancers : la mortalité à 5 ans en ischémie critique avoisine 70 %.","src":"p. 175-178"},{"id":"225-qroc-409","type":"QROC","rank":"A","objective":"225-obj-07","tags":["physiopathologie"],"difficulty":2,"question":"Au bout de combien de temps les cellules musculaires souffrent-elles lors d'une ischémie aiguë de membre ?","answer":"Dès 6 à 8 heures","accept":["6-8","6 a 8"],"keywords":["6"],"explanation":"Les cellules nerveuses souffrent dès 2 heures, les cellules musculaires dès 6-8 heures (rhabdomyolyse), la nécrose cutanée apparaît vers la 24e heure.","src":"p. 178-180"},{"id":"225-qroc-410","type":"QROC","rank":"A","objective":"225-obj-07","tags":["diagnostic","urgence"],"difficulty":3,"question":"Quel grade de Rutherford correspond à une ischémie aiguë immédiatement menaçante avec déficit sensitif au-delà des orteils ?","answer":"Grade IIb","accept":["iib","2b"],"keywords":["iib"],"explanation":"Le grade IIb (immédiatement menaçante) associe un déficit sensitif au-delà des orteils et un déficit moteur modéré ; la récupération n'est possible qu'en urgence immédiate.","src":"p. 178-180"},{"id":"225-qroc-411","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":1,"question":"Quel est le traitement de référence d'une ischémie aiguë par embolie sur artère saine ?","answer":"L'embolectomie à la sonde de Fogarty","accept":["fogarty","embolectomie"],"keywords":["embolectom"],"explanation":"L'embolectomie à la sonde de Fogarty sous contrôle angiographique est la méthode de référence de l'embolie sur artère saine.","src":"p. 182-183"},{"id":"225-qroc-412","type":"QROC","rank":"A","objective":"225-obj-10","tags":["définition"],"difficulty":1,"question":"Quelle augmentation de diamètre par rapport au segment sus-jacent définit un anévrisme ?","answer":"Plus de 50 %","accept":["50"],"keywords":["50"],"explanation":"Un anévrisme est une dilatation localisée et durable dont le diamètre dépasse de plus de 50 % celui du segment sus-jacent.","src":"p. 183-185"},{"id":"225-qroc-413","type":"QROC","rank":"A","objective":"225-obj-10","tags":["pronostic"],"difficulty":2,"question":"Quel est le risque annuel de rupture d'un AAA de diamètre supérieur à 60 mm ?","answer":"Environ 15 % par an","accept":["15"],"keywords":["15"],"explanation":"Le risque de rupture croît avec le diamètre : 0,4 %/an si < 40 mm, 3 %/an à 50-59 mm, 15 %/an au-delà de 60 mm.","src":"p. 183-185"},{"id":"225-qroc-414","type":"QROC","rank":"A","objective":"225-obj-13","tags":["examens","surveillance"],"difficulty":1,"question":"Quel examen permet le dépistage et la surveillance du diamètre d'un AAA ?","answer":"L'échographie abdominale","accept":["echographie","echo abdominale"],"keywords":["echo"],"explanation":"L'échographie abdominale dépiste, mesure le diamètre maximal et assure le suivi de l'AAA ; le scanner injecté est l'examen préthérapeutique.","src":"p. 183-185"},{"id":"225-qroc-415","type":"QROC","rank":"A","objective":"225-obj-12","tags":["diagnostic"],"difficulty":3,"question":"Quelle complication cardiaque révèle une fistule aorto-cave compliquant un AAA ?","answer":"Une insuffisance cardiaque à débit élevé","accept":["insuffisance cardiaque","haut debit","debit eleve"],"keywords":["debit"],"explanation":"Une fistule aorto-cave se révèle par une insuffisance cardiaque à débit élevé ; une fistule aorto-digestive par une hémorragie digestive.","src":"p. 183-185"},{"id":"225-qroc-416","type":"QROC","rank":"B","objective":"225-obj-11","tags":["épidémiologie","diagnostic"],"difficulty":1,"question":"Chez qui le dépistage échographique de l'AAA est-il recommandé en population générale ?","answer":"Chez l'homme de plus de 65 ans","accept":["homme > 65","homme de plus de 65 ans"],"keywords":["homme","65"],"explanation":"Le dépistage échographique est recommandé chez l'homme > 65 ans, ou plus jeune en cas de facteurs de risque (tabac, athérome, antécédents familiaux).","src":"p. 183-185"},{"id":"225-qroc-417","type":"QROC","rank":"B","objective":"225-obj-11","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'étiologie de l'AAA dans 80 à 90 % des cas ?","answer":"L'athérome","accept":["atherome","atherosclerose","atheromateux"],"keywords":["atherom"],"explanation":"Dans 80-90 % des cas, l'AAA survient sur un terrain athéromateux, souvent associé à une AOMI ou une atteinte coronarienne ou carotidienne.","src":"p. 183-185"},{"id":"225-qroc-418","type":"QROC","rank":"B","objective":"225-obj-14","tags":["surveillance"],"difficulty":2,"question":"Au-delà de quel diamètre la surveillance échographique d'un AAA asymptomatique est-elle renforcée tous les 6 mois ?","answer":"Au-delà de 45 mm","accept":["45"],"keywords":["45"],"explanation":"La surveillance échographique est renforcée (tous les 6 mois) si le diamètre dépasse 45 mm, l'intervention étant programmée au-delà de 50-55 mm.","src":"p. 185-187"},{"id":"225-qroc-420","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quels sont les deux principaux facteurs de risque de l'AOMI ?","answer":"Le tabagisme et le diabète","accept":["tabac et diabete","tabagisme et diabete"],"keywords":["taba","diabet"],"explanation":"Le tabagisme (plus fréquent chez le sujet jeune) et le diabète (formes distales plus graves) sont les deux principaux facteurs de risque de l'AOMI.","src":"p. 167-168"},{"id":"225-qcm-501","type":"QRM","rank":"A","objective":"225-obj-17","tags":["ischémie mésentérique aiguë","sémiologie"],"difficulty":2,"stem":"Concernant le diagnostic de l'ischémie mésentérique aiguë, quelles propositions sont exactes ?","options":[{"t":"La douleur abdominale aiguë est pauvre en signes physiques.","ok":true,"why":"Elément de la triade évocatrice."},{"t":"L'infarctus digestif est fréquent du fait de la pauvreté des collatérales.","ok":false,"why":"Il est rare grâce aux nombreuses collatéralités."},{"t":"Un arrêt des matières et des gaz fait partie de la triade évocatrice.","ok":false,"why":"La triade comporte au contraire une vidange digestive accélérée (vomissements et/ou diarrhée)."},{"t":"Le diagnostic est confirmé par une échographie abdominale.","ok":false,"why":"C'est l'angioscanner qui confirme le diagnostic."},{"t":"Un contexte emboligène, comme une fibrillation atriale, est évocateur.","ok":true,"why":"Elément de la triade évocatrice."}],"explanation":"Triade évocatrice : douleur aiguë pauvre en signes physiques, vidange digestive accélérée, arguments emboligènes ; le diagnostic est confirmé par l'angioscanner ; l'infarctus digestif est rare grâce aux collatérales.","src":"p. 167, 187"},{"id":"225-qcm-502","type":"QRM","rank":"A","objective":"225-obj-16","tags":["ischémie mésentérique chronique","prise en charge"],"difficulty":2,"stem":"Concernant l'ischémie mésentérique chronique, quelles propositions sont exactes ?","options":[{"t":"Son traitement de référence est l'anticoagulation curative au long cours.","ok":false,"why":"Le traitement repose sur la revascularisation, de préférence endovasculaire."},{"t":"Elle est liée à une sténose athéromateuse des artères rénales.","ok":false,"why":"La sténose des artères rénales donne une HTA rénovasculaire ; l'ischémie mésentérique chronique relève d'une sténose du tronc cœliaque et/ou des artères mésentériques."},{"t":"L'artériographie n'est réalisée que pour un geste endovasculaire.","ok":true,"why":"Le diagnostic repose sur écho-Doppler, angioscanner ou angio-IRM."},{"t":"La revascularisation est de préférence endovasculaire.","ok":true,"why":"Le texte le précise."},{"t":"Elle est toujours symptomatique.","ok":false,"why":"Elle est souvent asymptomatique."}],"explanation":"L'ischémie mésentérique chronique (sténose du tronc cœliaque et/ou des mésentériques), souvent asymptomatique, peut donner un angor digestif ; diagnostic par écho-Doppler, angioscanner ou angio-IRM ; traitement : revascularisation, de préférence endovasculaire.","src":"p. 166, 187"},{"id":"225-qcm-503","type":"QRM","rank":"A","objective":"225-obj-01","tags":["épidémiologie","AOMI"],"difficulty":2,"stem":"Concernant l'épidémiologie de l'AOMI, quelles propositions sont exactes ?","options":[{"t":"Le pic de présentation est plus précoce chez la femme que chez l'homme.","ok":false,"why":"Le pic se situe entre 60 et 75 ans chez l'homme et entre 70 et 80 ans chez la femme : il est plus tardif chez la femme."},{"t":"Sa prévalence clinique atteint 10 à 15 % après 60 ans.","ok":false,"why":"Les formes cliniques touchent 1 à 5 % des plus de 60 ans ; 10-15 % correspond à la prévalence si l'on inclut les formes asymptomatiques."},{"t":"Pour un cas clinique, on compte 2 à 4 formes infracliniques, ce qui justifie un dépistage ciblé.","ok":true,"why":"Le texte le précise."},{"t":"C'est la première localisation de l'athérosclérose.","ok":false,"why":"C'est la 3e localisation, après le cœur et le cerveau."},{"t":"Elle touche plus souvent l'homme.","ok":true,"why":"Le texte le précise."}],"explanation":"L'AOMI, 3e localisation de l'athérosclérose, prédomine chez l'homme dans sa forme symptomatique ; pic de présentation entre 60 et 75 ans chez l'homme et entre 70 et 80 ans chez la femme ; prévalence clinique 1–5 % après 60 ans, 10–15 % en incluant les formes asymptomatiques (2 à 4 formes infracliniques pour un cas clinique).","src":"p. 167-168"},{"id":"225-qcm-504","type":"QRM","rank":"A","objective":"225-obj-03","tags":["classification","Leriche-Fontaine","Rutherford"],"difficulty":2,"stem":"Quelles correspondances entre les classifications de Leriche-Fontaine et de Rutherford de l'AOMI sont exactes ?","options":[{"t":"Stade III de Leriche-Fontaine ↔ grade II (catégorie 4) de Rutherford","ok":true,"why":"Douleur ischémique de repos."},{"t":"Stade II de Leriche-Fontaine ↔ grade I (catégories 1 à 3) de Rutherford","ok":true,"why":"Claudication légère à sévère."},{"t":"La catégorie 4 de Rutherford correspond à une perte de substance majeure.","ok":false,"why":"La catégorie 4 correspond à la douleur ischémique de repos ; la perte de substance aux catégories 5-6."},{"t":"Le stade I de Leriche-Fontaine correspond à la claudication intermittente.","ok":false,"why":"Le stade I est asymptomatique ; la claudication correspond au stade II."},{"t":"Stade IV de Leriche-Fontaine ↔ grade III (catégories 5-6) de Rutherford","ok":true,"why":"Ulcération/gangrène ↔ perte de substance faible à majeure."}],"explanation":"Leriche-Fontaine I/II/III/IV (asymptomatique, claudication, douleur de repos, ulcération ou gangrène) correspond à Rutherford 0/I (1-3)/II (4)/III (5-6).","src":"p. 168-170"},{"id":"225-qcm-505","type":"QRM","rank":"A","objective":"225-obj-04","tags":["examen clinique","AOMI"],"difficulty":1,"stem":"Concernant l'examen physique d'un patient suspect d'AOMI, quelles propositions sont exactes ?","options":[{"t":"L'absence isolée d'un pouls pédieux suffit à affirmer l'AOMI.","ok":false,"why":"Le pouls pédieux est absent congénitalement chez 5 % des sujets."},{"t":"Il comprend une palpation abdominale et poplitée à la recherche d'un anévrisme.","ok":true,"why":"Le texte le précise."},{"t":"Il est toujours bilatéral et comparatif.","ok":true,"why":"Le texte le précise."},{"t":"Le temps de recoloration cutanée est raccourci au niveau du pied en cas d'AOMI.","ok":false,"why":"Il est au contraire allongé au pied et aux orteils (normalement inférieur à 3 secondes)."},{"t":"La palpation des pouls se limite au pouls pédieux.","ok":false,"why":"On recherche les pouls fémoral, poplité, tibial postérieur et pédieux."}],"explanation":"Examen bilatéral et comparatif : inspection, palpation (froideur, pouls fémoral, poplité, tibial postérieur, pédieux, recoloration < 3 s), auscultation des trajets vasculaires, recherche d'anévrisme abdominal et poplité.","src":"p. 170-173"},{"id":"225-qcm-506","type":"QRM","rank":"A","objective":"225-obj-04","tags":["TcPO2","ischémie critique"],"difficulty":2,"stem":"Concernant la mesure de la pression transcutanée en oxygène (TcPO2), quelles propositions sont exactes ?","options":[{"t":"Une valeur > 35 mmHg traduit une hypoxie critique.","ok":false,"why":"Une TcPO2 > 35 mmHg traduit une bonne compensation."},{"t":"Une valeur entre 10 et 35 mmHg témoigne d'une bonne compensation métabolique.","ok":false,"why":"Entre 10 et 35 mmHg, la TcPO2 traduit une hypoxie continue ; c'est une valeur supérieure à 35 mmHg qui témoigne d'une bonne compensation."},{"t":"Une valeur < 10 mmHg traduit une hypoxie critique.","ok":true,"why":"Seuil d'hypoxie critique."},{"t":"À l'état basal, sans hyperémie, elle distingue une peau saine d'une peau ischémique.","ok":false,"why":"À l'état basal, la PO2 cutanée est très basse (3 à 4 mmHg), sans différence entre peau saine et ischémique : une hyperémie par la chaleur est nécessaire pour que l'examen soit discriminant."},{"t":"Elle guide le niveau d'une amputation.","ok":true,"why":"L'amputation se fait en zone saine et bien oxygénée, guidée par la TcPO2."}],"explanation":"TcPO2 mesurée après hyperémie (à l'état basal, 3 à 4 mmHg sans différence entre peau saine et ischémique) : normale > 50 mmHg au dos du pied, > 35 mmHg bonne compensation, 10–35 mmHg hypoxie continue, < 10 mmHg hypoxie critique ; utile dans l'ischémie critique et pour guider le niveau d'une amputation.","src":"p. 170-173, 175-178"},{"id":"225-qcm-507","type":"QRM","rank":"B","objective":"225-obj-03","tags":["diagnostic différentiel","ulcère"],"difficulty":1,"stem":"Devant un ulcère du membre inférieur, quels diagnostics différentiels de l'ulcère artériel sont cités ?","options":[{"t":"Ulcère « suspendu » de la face antérieure de la jambe","ok":false,"why":"C'est une localisation possible de l'ulcère artériel lui-même, pas un diagnostic différentiel."},{"t":"Syndrome régional douloureux complexe","ok":false,"why":"Il est cité parmi les diagnostics différentiels des douleurs de décubitus, non des ulcères."},{"t":"Ulcère veineux","ok":true,"why":"Cité parmi les différentiels d'ulcère."},{"t":"Canal lombaire étroit","ok":false,"why":"C'est un différentiel des douleurs à la marche, non des ulcères."},{"t":"Ulcère neuropathique","ok":true,"why":"Cité parmi les différentiels d'ulcère."}],"explanation":"Diagnostics différentiels de l'ulcère artériel cités : ulcères veineux, microcirculatoire, neuropathique et traumatique. L'ulcère « suspendu » de face antérieure de jambe est une localisation de l'ulcère artériel ; le canal lombaire étroit (douleurs à la marche) et le syndrome régional douloureux complexe (douleurs de décubitus) relèvent d'autres listes de différentiels.","src":"p. 174"},{"id":"225-qcm-508","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement local","réadaptation"],"difficulty":2,"stem":"Concernant le traitement à visée locale de l'AOMI, quelles propositions sont exactes ?","options":[{"t":"La réadaptation est idéalement supervisée et associée à une éducation thérapeutique.","ok":true,"why":"Le texte le précise."},{"t":"Les prostaglandines sont possibles en ischémie critique non revascularisable.","ok":true,"why":"Le texte le précise."},{"t":"Une marche régulière de 30 à 45 minutes, au moins 3 fois par semaine, est recommandée.","ok":true,"why":"Rythme de marche cité."},{"t":"Les traitements vasoactifs améliorent le pronostic vital.","ok":false,"why":"Ils n'ont pas d'effet pronostique."},{"t":"Les traitements vasoactifs (ex. pentoxifylline) ont un bénéfice modeste sur le périmètre de marche.","ok":true,"why":"Bénéfice modeste, sans effet pronostique."}],"explanation":"Traitement local : arrêt du tabac, marche régulière (idéalement réadaptation supervisée + ETP), vasoactifs à bénéfice modeste sans effet pronostique, prostaglandines en ischémie critique non revascularisable, revascularisation selon le stade.","src":"p. 175-178"},{"id":"225-qcm-509","type":"QRM","rank":"A","objective":"225-obj-05","tags":["revascularisation","AOMI"],"difficulty":2,"stem":"Concernant la revascularisation dans l'AOMI, quelles propositions sont exactes ?","options":[{"t":"L'angioplastie endovasculaire (± stent) s'adresse aux lésions courtes et proximales.","ok":true,"why":"Le texte le précise."},{"t":"Elle est proposée à tout claudicant, quel que soit son périmètre de marche.","ok":false,"why":"Chez le claudicant, elle n'est discutée qu'en cas de claudication sévère invalidante (< 100 m), notamment après échec du traitement médical."},{"t":"Une bithérapie antiplaquettaire de 1 à 6 mois suit une angioplastie.","ok":true,"why":"Durée citée."},{"t":"Elle est systématiquement proposée en cas d'ischémie permanente.","ok":true,"why":"Le texte le précise."},{"t":"Pontage ou endartériectomie s'adressent aux lésions étendues.","ok":true,"why":"Le texte le précise."}],"explanation":"Revascularisation systématique en ischémie permanente, discutée si claudication invalidante < 100 m ; angioplastie pour lésions courtes/proximales (bithérapie antiplaquettaire 1–6 mois), chirurgie pour lésions étendues ; surveillance clinique et écho-Doppler.","src":"p. 175-178"},{"id":"225-qcm-510","type":"QRM","rank":"A","objective":"225-obj-07","tags":["ischémie aiguë","physiopathologie"],"difficulty":2,"stem":"Concernant la physiopathologie de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Sa gravité dépend de la pression artérielle systémique.","ok":true,"why":"Déterminant de gravité cité."},{"t":"La nécrose cutanée apparaît vers la 24e heure.","ok":true,"why":"Délai cité."},{"t":"Sa gravité est d'autant plus grande que la collatéralité est abondante.","ok":false,"why":"Une collatéralité abondante limite au contraire la baisse de débit ; c'est son absence qui explique la sévérité de l'embolie sur artère saine."},{"t":"Sa gravité dépend de la qualité du lit d'aval.","ok":true,"why":"Déterminant de gravité cité."},{"t":"L'occlusion de la bifurcation aortique donne typiquement une ischémie unilatérale modérée.","ok":false,"why":"Elle donne une ischémie bilatérale sévère pouvant aller jusqu'au collapsus."}],"explanation":"La gravité dépend de la PA systémique, de la collatéralité et du lit d'aval ; nerfs souffrant dès 2 h, muscles dès 6–8 h, peau vers 24 h ; l'occlusion de la bifurcation aortique donne une ischémie bilatérale sévère.","src":"p. 178-180"},{"id":"225-qcm-511","type":"QRM","rank":"B","objective":"225-obj-08","tags":["ischémie aiguë","thrombose in situ","étiologies"],"difficulty":2,"stem":"Parmi les causes suivantes, lesquelles sont citées comme causes de thrombose artérielle in situ ?","options":[{"t":"Tumeur de l'aorte","ok":false,"why":"Les tumeurs aortiques sont citées parmi les sources aortiques d'embolie, non parmi les causes de thrombose in situ."},{"t":"Endocardite infectieuse","ok":false,"why":"C'est une cause cardiaque d'embolie, non de thrombose in situ."},{"t":"Fibrillation atriale","ok":false,"why":"C'est une cause cardiaque d'embolie, non de thrombose in situ."},{"t":"Anévrisme poplité thrombosé","ok":true,"why":"Cité parmi les causes de thrombose in situ."},{"t":"Myxome de l'atrium","ok":false,"why":"C'est une cause cardiaque d'embolie."}],"explanation":"Thrombose in situ : AOMI, artériopathies non athéromateuses, anévrisme poplité thrombosé, déshydratation du sujet âgé, kyste adventiciel, dissection, coagulopathies, causes iatrogènes (cathétérisme, TIH, ergotisme). Embolie : causes cardiaques (fibrillation atriale, endocardite, myxome…) et aortiques (athérome, anévrisme, aortites, tumeurs).","src":"p. 181-182"},{"id":"225-qcm-512","type":"QRM","rank":"B","objective":"225-obj-08","tags":["ischémie aiguë","embolie"],"difficulty":2,"stem":"Concernant l'ischémie aiguë par embolie sur artères saines, quelles propositions sont exactes ?","options":[{"t":"La source peut être aortique (athérome, anévrisme, aortite, tumeur).","ok":true,"why":"Causes aortiques citées."},{"t":"La douleur est brutale, aiguë et sévère du fait de l'absence de collatérales.","ok":true,"why":"Le texte le précise."},{"t":"Elle touche plutôt un sujet âgé ayant une AOMI connue.","ok":false,"why":"C'est le terrain de la thrombose in situ ; l'embolie survient classiquement chez un sujet plus jeune sans antécédent vasculaire connu (mais pouvant avoir une cardiopathie)."},{"t":"Elle est typiquement favorisée par une déshydratation ou une hémoconcentration.","ok":false,"why":"La déshydratation et l'hémoconcentration du sujet âgé sont des causes de thrombose in situ ; l'embolie peut être précédée de palpitations (arythmie)."},{"t":"L'installation est progressive grâce à une collatéralité préalable.","ok":false,"why":"Cette présentation évoque une thrombose in situ."}],"explanation":"L'embolie sur artère saine survient classiquement chez un sujet plus jeune sans antécédent vasculaire (mais parfois cardiopathe), avec une douleur brutale et sévère faute de collatérales, parfois précédée de palpitations ; ses sources sont cardiaques (fibrillation atriale…) ou aortiques. Un terrain âgé artériopathe ou une déshydratation orientent vers une thrombose in situ.","src":"p. 181-182"},{"id":"225-qcm-513","type":"QRM","rank":"A","objective":"225-obj-09","tags":["ischémie aiguë","syndrome de revascularisation"],"difficulty":2,"stem":"Concernant la prise en charge des conséquences métaboliques et générales d'une ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Le membre est maintenu surélevé.","ok":false,"why":"Le membre est placé en position légèrement déclive."},{"t":"Les CPK sont surveillées.","ok":true,"why":"Avec ionogramme, urée et créatininémie."},{"t":"La diurèse est surveillée par sonde urinaire.","ok":true,"why":"Le texte le précise."},{"t":"L'acidose est corrigée par bicarbonates IV.","ok":true,"why":"Le texte le précise."},{"t":"Le remplissage vasculaire est contre-indiqué.","ok":false,"why":"La correction hémodynamique (remplissage) fait partie du traitement médical immédiat."}],"explanation":"Surveillance diurèse (sonde), ionogramme, urée, créatininémie, CPK ; bicarbonates IV, traitement de l'hyperkaliémie (chélateur, voire dialyse), lavage de membre ; position légèrement déclive ; correction hémodynamique.","src":"p. 182-183"},{"id":"225-qcm-514","type":"QRM","rank":"A","objective":"225-obj-10","tags":["AAA","histoire naturelle"],"difficulty":2,"stem":"Concernant l'épidémiologie et l'histoire naturelle de l'anévrisme de l'aorte abdominale (AAA), quelles propositions sont exactes ?","options":[{"t":"Le tabagisme actif accélère la croissance d'environ 3 fois.","ok":true,"why":"Le texte le précise."},{"t":"La croissance moyenne est de 2 à 4 mm par an.","ok":true,"why":"Chiffre cité, variable individuellement."},{"t":"Entre 75 et 84 ans, elle est de 5 % chez l'homme et de 3 % chez la femme.","ok":true,"why":"Chiffres cités."},{"t":"Le risque de rupture est d'environ 0,4 %/an pour un diamètre de 50 à 59 mm.","ok":false,"why":"Il est d'environ 3 %/an à 50-59 mm ; 0,4 %/an concerne les AAA < 40 mm."},{"t":"Sa prévalence est en baisse dans les pays occidentaux.","ok":true,"why":"Le texte le précise."}],"explanation":"AAA : prévalence 2–5 % chez l'homme > 65 ans ; croissance 2–4 mm/an (× 3 si tabagisme actif) ; rupture ≈ 0,4 %/an si < 40 mm, 3 %/an à 50–59 mm, 15 %/an au-delà de 60 mm.","src":"p. 183-187"},{"id":"225-qru-501","type":"QRU","rank":"A","objective":"225-obj-10","tags":["anévrisme","physiopathologie"],"difficulty":2,"stem":"Quel mécanisme explique la perte de résistance de la paroi artérielle à la distension au cours d'un anévrisme ?","options":[{"t":"Occlusion embolique de la lumière artérielle","ok":false,"why":"Il s'agit d'un mécanisme d'ischémie aiguë."},{"t":"Destruction des fibres élastiques et fragmentation du collagène de la média sous l'effet d'enzymes comme les métalloprotéases","ok":true,"why":"C'est le mécanisme décrit."},{"t":"Hyperplasie intimale sténosante","ok":false,"why":"Ce n'est pas le mécanisme décrit."},{"t":"Calcification isolée de la média (médiacalcose)","ok":false,"why":"La médiacalcose rend les artères incompressibles (IPS > 1,40), sans être le mécanisme décrit de l'anévrisme."},{"t":"Spasme artériel prolongé","ok":false,"why":"Ce n'est pas le mécanisme décrit."}],"explanation":"La média perd sa résistance à la distension par destruction des fibres élastiques et fragmentation du collagène, sous l'effet d'enzymes comme les métalloprotéases.","src":"p. 183-185"},{"id":"225-qru-502","type":"QRU","rank":"B","objective":"225-obj-14","tags":["AAA","traitement endovasculaire"],"difficulty":2,"stem":"Un homme de 78 ans, à haut risque chirurgical (BPCO sévère, insuffisance cardiaque), a un AAA sous-rénal asymptomatique de 58 mm avec une anatomie favorable. Quelle prise en charge est la plus adaptée ?","options":[{"t":"Chirurgie à ciel ouvert, préférable chez le sujet à haut risque","ok":false,"why":"L'endoprothèse est préférée chez le sujet à haut risque chirurgical."},{"t":"Artériographie pour mesurer le diamètre avant toute décision","ok":false,"why":"L'artériographie n'est pas utile (sous-estime la taille en cas de thrombus mural)."},{"t":"Traitement médical seul, l'intervention étant réservée à la rupture","ok":false,"why":"Une intervention à froid est indiquée au-delà du seuil de 50-55 mm."},{"t":"Surveillance échographique tous les 6 mois","ok":false,"why":"Au-delà de 50-55 mm, une intervention à froid est programmée."},{"t":"Traitement endovasculaire par endoprothèse introduite par voie fémorale","ok":true,"why":"Moins invasif, préféré chez le sujet à haut risque chirurgical si l'anatomie est favorable."}],"explanation":"Au-delà de 50–55 mm : intervention à froid, chirurgie ouverte ou endoprothèse ; l'endoprothèse est préférée chez le sujet à haut risque chirurgical si l'anatomie est favorable, avec surveillance des endofuites.","src":"p. 185-187"},{"id":"225-qru-503","type":"QRU","rank":"A","objective":"225-obj-15","tags":["AAA","embolie","urgence"],"difficulty":2,"stem":"Un porteur d'AAA de 52 mm présente une ischémie aiguë du membre inférieur par embolie à partir du thrombus intra-anévrismal. Quelle est la priorité ?","options":[{"t":"Un antiplaquettaire seul avec réévaluation à 1 mois","ok":false,"why":"L'ischémie aiguë est une urgence de revascularisation."},{"t":"Une amputation d'emblée","ok":false,"why":"Elle n'est indiquée d'emblée que si l'ischémie est dépassée."},{"t":"La revascularisation urgente du membre, la cure de l'AAA étant secondaire","ok":true,"why":"Le texte le précise."},{"t":"Une surveillance échographique rapprochée de l'AAA","ok":false,"why":"L'ischémie aiguë impose une revascularisation urgente."},{"t":"La cure de l'AAA en urgence avant toute revascularisation du membre","ok":false,"why":"La revascularisation du membre est prioritaire."}],"explanation":"En cas d'ischémie aiguë de membre par embolie à partir d'un AAA, la revascularisation du membre est urgente, la cure de l'AAA étant secondaire.","src":"p. 185-187"},{"id":"225-qru-504","type":"QRU","rank":"A","objective":"225-obj-10","tags":["anévrisme poplité"],"difficulty":2,"stem":"Concernant l'anévrisme de l'artère poplitée, quelle proposition est exacte ?","options":[{"t":"Il est le plus souvent découvert lors d'une rupture.","ok":false,"why":"Il est surtout découvert par une masse battante poplitée, un écho-Doppler systématique ou une complication ischémique."},{"t":"Son dépistage repose sur l'artériographie.","ok":false,"why":"Le dépistage repose sur l'écho-Doppler."},{"t":"Il est associé à un AAA dans environ 30 % des cas et bilatéral dans près de la moitié des cas.","ok":true,"why":"Chiffres cités."},{"t":"Un anévrisme poplité controlatéral ne justifie aucun dépistage.","ok":false,"why":"Un échodoppler est indiqué en cas de risque élevé (AAA ou anévrisme poplité controlatéral)."},{"t":"Il ne se découvre jamais à la palpation.","ok":false,"why":"Il peut être découvert par une masse battante au creux poplité."}],"explanation":"L'anévrisme poplité est associé à un AAA dans ≈ 30 % des cas, bilatéral une fois sur deux ; il est découvert par la palpation, par un écho-Doppler (dépistage si AAA ou AP controlatéral) ou devant une artériopathie ou une ischémie aiguë.","src":"p. 186"},{"id":"225-qru-505","type":"QRU","rank":"A","objective":"225-obj-16","tags":["athérome aortique","facteurs de risque"],"difficulty":1,"stem":"Quel facteur de risque est le plus associé à l'athérome aortique ?","options":[{"t":"L'hypertension artérielle","ok":false,"why":"Le texte désigne le tabagisme comme facteur le plus associé."},{"t":"La sédentarité","ok":false,"why":"Le texte désigne le tabagisme comme facteur le plus associé."},{"t":"Le tabagisme","ok":true,"why":"Le texte indique que le tabagisme est le facteur le plus associé."},{"t":"L'hypercholestérolémie","ok":false,"why":"Le texte désigne le tabagisme comme facteur le plus associé."},{"t":"Le diabète","ok":false,"why":"Le texte désigne le tabagisme comme facteur le plus associé."}],"explanation":"L'athérome aortique prédomine à la bifurcation et à l'origine des branches ; le tabagisme en est le facteur le plus associé ; il peut se compliquer d'embolies et marque un surrisque CV global.","src":"p. 166-167"},{"id":"225-qroc-501","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":2,"question":"Quelle est la prévalence de l'AOMI après 60 ans si l'on intègre les formes infracliniques ?","answer":"10 à 15 %","accept":["10-15 %","10 à 15 pour cent"],"keywords":["10","15"],"explanation":"La prévalence clinique est de 1–5 % après 60 ans et atteint 10–15 % avec les formes infracliniques.","src":"p. 167-168"},{"id":"225-qroc-502","type":"QROC","rank":"A","objective":"225-obj-03","tags":["claudication"],"difficulty":1,"question":"En combien de temps la douleur de claudication intermittente cède-t-elle à l'arrêt de la marche ?","answer":"En moins de 5 minutes","accept":["< 5 minutes","moins de 5 min"],"keywords":["minute"],"explanation":"La claudication est une crampe du mollet à la marche cédant en moins de 5 minutes à l'arrêt.","src":"p. 168-170"},{"id":"225-qroc-503","type":"QROC","rank":"A","objective":"225-obj-03","tags":["ischémie critique"],"difficulty":2,"question":"Quelle pression d'hallux définit l'ischémie critique ?","answer":"Moins de 30 mmHg","accept":["< 30 mmHg","inférieure à 30 mmHg"],"keywords":["30"],"explanation":"L'ischémie critique est définie par une pression de cheville < 50 mmHg ou une pression d'hallux < 30 mmHg.","src":"p. 168-170"},{"id":"225-qroc-504","type":"QROC","rank":"A","objective":"225-obj-04","tags":["index de pression d'orteil","médiacalcose"],"difficulty":2,"question":"En dessous de quelle valeur l'index de pression d'orteil est-il pathologique ?","answer":"Inférieur à 0,70","accept":["< 0,70","0,70","0,7"],"keywords":["0,7"],"explanation":"En cas de médiacalcose (IPS > 1,40), l'IPS est remplacé par l'index de pression d'orteil, pathologique si < 0,70.","src":"p. 170-173"},{"id":"225-qroc-505","type":"QROC","rank":"A","objective":"225-obj-04","tags":["TcPO2"],"difficulty":2,"question":"En dessous de quelle valeur de TcPO2 parle-t-on d'hypoxie critique ?","answer":"Moins de 10 mmHg","accept":["< 10 mmHg","10 mmHg"],"keywords":["10"],"explanation":"TcPO2 : > 50 mmHg normale, > 35 mmHg bonne compensation, 10–35 mmHg hypoxie continue, < 10 mmHg hypoxie critique.","src":"p. 170-173"},{"id":"225-qroc-506","type":"QROC","rank":"A","objective":"225-obj-05","tags":["réentraînement","traitement"],"difficulty":2,"question":"Pendant combien de temps est proposé le réentraînement à raison de 3 séances par semaine dans l'AOMI ?","answer":"12 semaines","accept":["12 sem","douze semaines"],"keywords":["12","semaine"],"explanation":"Le traitement à visée générale comprend un réentraînement 3 fois par semaine pendant 12 semaines.","src":"p. 175-178"},{"id":"225-qroc-507","type":"QROC","rank":"A","objective":"225-obj-07","tags":["ischémie aiguë","chronologie"],"difficulty":1,"question":"Vers quelle heure apparaît la nécrose cutanée au cours d'une ischémie aiguë de membre ?","answer":"Vers la 24e heure","accept":["24 heures","24 h","24e heure"],"keywords":["24"],"explanation":"Souffrance nerveuse dès 2 h, musculaire dès 6–8 h, nécrose cutanée vers la 24e heure.","src":"p. 178-180"},{"id":"225-qroc-508","type":"QROC","rank":"A","objective":"225-obj-09","tags":["aponévrotomie","syndrome des loges"],"difficulty":2,"question":"Quelle loge est habituellement concernée par l'aponévrotomie de décompression après revascularisation tardive d'une ischémie aiguë ?","answer":"La loge antéro-externe de jambe","accept":["loge antéro-externe","loge antérolatérale de jambe","antéro-externe"],"keywords":["antero","externe"],"explanation":"L'aponévrotomie de décompression, en général de la loge antéro-externe de jambe, est systématique en cas de revascularisation tardive.","src":"p. 182-183"},{"id":"225-qroc-509","type":"QROC","rank":"B","objective":"225-obj-14","tags":["AAA","suivi"],"difficulty":2,"question":"Quelle complication l'écho-Doppler de surveillance recherche-t-il après chirurgie conventionnelle d'un AAA ?","answer":"Faux anévrisme anastomotique","accept":["faux anévrisme","faux anévrisme de l'anastomose"],"keywords":["faux","anastomo"],"explanation":"Après chirurgie conventionnelle : surveillance écho-Doppler (faux anévrisme anastomotique, thrombose exceptionnelle) ; après endoprothèse : recherche d'endofuites.","src":"p. 185-187"},{"id":"225-qroc-510","type":"QROC","rank":"A","objective":"225-obj-12","tags":["AAA","fistule"],"difficulty":2,"question":"Quelle manifestation révèle une fistule aorto-digestive compliquant un AAA ?","answer":"Une hémorragie digestive","accept":["hémorragie digestive","saignement digestif"],"keywords":["hemorragie","digestive"],"explanation":"Une fistule aorto-cave donne une insuffisance cardiaque à débit élevé ; une fistule aorto-digestive, une hémorragie digestive.","src":"p. 183-185"},{"id":"225-qroc-601","type":"QROC","rank":"A","objective":"225-obj-16","tags":["définition","étiologie"],"difficulty":1,"question":"Quels sont les deux mécanismes possibles de l'occlusion artérielle responsable d'une ischémie mésentérique aiguë ?","answer":"Thrombose in situ ou embolie","accept":["thrombose et embolie","embolie et thrombose","thrombose in situ ou embolie","embolie ou thrombose"],"keywords":["thromb","embol"],"explanation":"L'ischémie mésentérique aiguë est une interruption brutale de la perfusion d'une partie de l'intestin par occlusion d'une ou plusieurs artères digestives, par thrombose in situ ou par embolie. L'infarctus reste rare grâce aux nombreuses collatérales, mais c'est une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge.","src":"p. 167"},{"id":"225-qroc-602","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","pièges"],"difficulty":2,"question":"Dans le tableau classique d'ischémie mésentérique aiguë, quelle caractéristique de l'examen physique abdominal accompagne la douleur abdominale aiguë ?","answer":"Une paucité de signes physiques","accept":["paucité","pauvre","pauvreté","peu de signes"],"keywords":["pauc"],"explanation":"Le tableau classique associe une douleur abdominale aiguë avec peu de signes physiques, une vidange digestive accélérée (vomissements et/ou diarrhée) et des indices de cause embolique, notamment une fibrillation atriale. Cette discordance fait partie des pièges de la présentation.","src":"p. 167"},{"id":"225-qroc-603","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","diagnostic"],"difficulty":1,"question":"Dans l'ischémie mésentérique chronique, quel signe physique éventuel évoque une sténose artérielle viscérale ?","answer":"Un souffle abdominal","accept":["souffle abdominal","souffle"],"keywords":["souffle"],"explanation":"L'ischémie mésentérique chronique se manifeste par un angor digestif (douleurs après les repas, amaigrissement si le patient limite ses repas). Les signes physiques se limitent à l'éventuelle présence d'un souffle abdominal.","src":"p. 166"},{"id":"225-qroc-604","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie","diagnostic"],"difficulty":2,"question":"On estime que, pour chaque cas d'AOMI clinique, un certain nombre de patients ont une forme infraclinique : combien ?","answer":"Deux à quatre","accept":["2 à 4","2-4","deux à quatre","2 et 4"],"keywords":["2","4"],"explanation":"L'AOMI clinique n'est que la partie visible : chaque cas clinique s'accompagne de deux à quatre formes infracliniques. Cela souligne l'intérêt du dépistage des formes infracliniques pour mieux prévenir la maladie.","src":"p. 168"},{"id":"225-qroc-605","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie","épidémiologie"],"difficulty":2,"question":"Quelle proportion des atteintes artérielles oblitérantes des membres inférieurs est d'origine athéromateuse ?","answer":"Plus de 95 %","accept":["plus de 95 %","95 %","> 95 %"],"keywords":["95"],"explanation":"L'AOMI est synonyme d'atteinte athéromateuse des membres inférieurs et représente plus de 95 % des atteintes artérielles oblitérantes. Les artériopathies non athéromateuses (inflammatoires, postradiques, post-traumatiques, toxiques, dysplasie fibromusculaire, etc.) sont minoritaires.","src":"p. 174"},{"id":"225-qroc-606","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Où siègent le plus souvent les ulcères de l'ischémie permanente d'une AOMI ?","answer":"Zones de frottement ou d'appui (orteils, bord externe du pied, talon)","accept":["frottement","appui","orteil","talon","bord externe du pied"],"keywords":["appui"],"explanation":"Les ulcères siègent surtout aux zones de frottement ou d'appui (orteil, dos et bord externe du pied, talon), parfois à la face antérieure de la jambe (ulcère « suspendu »). Ils surviennent spontanément ou après un traumatisme minime et peuvent creuser jusqu'à l'aponévrose ou l'os.","src":"p. 169"},{"id":"225-qroc-607","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Dans l'ischémie permanente, quelle position améliore les douleurs de décubitus ?","answer":"La position déclive (jambe pendante au bord du lit)","accept":["position déclive","déclive","jambe pendante","jambes pendantes","pendante"],"keywords":["declive"],"explanation":"Les douleurs de décubitus (brûlures des orteils et de l'avant-pied) apparaissent après quelques minutes à quelques heures de décubitus. Elles s'améliorent en position déclive, ce qui oblige le patient à laisser la jambe pendante au bord du lit, voire à se lever plusieurs fois la nuit.","src":"p. 169"},{"id":"225-qroc-608","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic différentiel neurologique donne des douleurs ou des paresthésies du mollet ou du pied à l'effort, cédant au repos ?","answer":"Un canal lombaire étroit","accept":["canal lombaire étroit","canal lombaire"],"keywords":["canal lombaire"],"explanation":"Chez le sujet âgé, plusieurs causes de douleur à la marche peuvent coexister avec l'AOMI : neurologiques (canal lombaire étroit, sciatalgie, atteinte médullaire), rhumatologiques, veineuses ou musculaires.","src":"p. 174"},{"id":"225-qroc-609","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle classe médicamenteuse peut provoquer des douleurs musculaires mimant un tableau d'AOMI ?","answer":"Les statines","accept":["statines","statine"],"keywords":["statine"],"explanation":"Les douleurs musculaires sous statines peuvent parfois mimer une AOMI, mais attention aux tableaux intriqués : les deux diagnostics peuvent coexister.","src":"p. 174"},{"id":"225-qroc-610","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Comment calcule-t-on l'index de pression systolique (IPS) d'un membre ?","answer":"PAS de cheville / PAS du bras (valeurs les plus élevées)","accept":["pression systolique de cheville sur pression systolique du bras","pas cheville sur pas bras","pas cheville pas bras","cheville sur bras","cheville bras","pression cheville pression bras"],"keywords":["cheville","bras"],"explanation":"L'IPS est le rapport de la pression systolique de cheville (la plus élevée des deux artères, tibiale postérieure et pédieuse) sur la pression systolique la plus élevée des deux bras, mesurées au brassard et au doppler de poche. La cheville est au numérateur.","src":"p. 170-171"},{"id":"225-qroc-611","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","pronostic"],"difficulty":2,"question":"En dehors du diagnostic d'AOMI, à quoi sert aussi l'IPS ?","answer":"Marqueur de risque cardiovasculaire","accept":["risque cardiovasculaire","marqueur de risque","risque cv"],"keywords":["risque"],"explanation":"L'IPS est aussi un marqueur de risque cardiovasculaire : une valeur inférieure à 0,90 est associée à un risque élevé d'accident coronarien ou cérébral, fatal ou non.","src":"p. 171"},{"id":"225-qroc-612","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie","pièges"],"difficulty":2,"question":"Quelles vérifications préalables impose l'injection de produit de contraste iodé d'un angioscanner des artères des membres inférieurs ?","answer":"Les allergies et la fonction rénale","accept":["allergies et fonction rénale","allergie et fonction rénale","fonction rénale et allergies","fonction rénale et allergie"],"keywords":["allerg","renal"],"explanation":"L'angioscanner étudie le chenal circulant et la paroi, mais nécessite du produit de contraste iodé : on vérifie au préalable les allergies et la fonction rénale. L'angio-IRM évite l'irradiation, mais le gadolinium est contre-indiqué en cas d'insuffisance rénale sévère.","src":"p. 172-173"},{"id":"225-qroc-613","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quel est l'objectif du traitement à visée générale d'un patient atteint d'AOMI ?","answer":"Améliorer le pronostic cardiovasculaire et vital","accept":["pronostic cardiovasculaire","pronostic vital","risque cardiovasculaire"],"keywords":["pronostic"],"explanation":"Le traitement à visée générale (contrôle des facteurs de risque, antiplaquettaire, statine, IEC) s'applique à tout stade et vise le pronostic cardiovasculaire et vital. Le traitement à visée locale vise, lui, les symptômes et le pronostic du membre.","src":"p. 175"},{"id":"225-qroc-614","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quel est l'objectif du traitement à visée locale de l'AOMI ?","answer":"Traiter l'ischémie (symptômes) et améliorer le pronostic du membre","accept":["pronostic du membre","traiter l'ischémie","résoudre les symptômes"],"keywords":["membre"],"explanation":"Le traitement à visée locale (marche régulière, traitements vasoactifs, revascularisation, soins de plaies, amputation) cherche à résoudre les symptômes en traitant l'ischémie et à améliorer le pronostic du membre, à la différence du traitement général qui vise le pronostic cardiovasculaire.","src":"p. 175-177"},{"id":"225-qroc-615","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle classe d'antihypertenseurs peut être considérée chez tout patient atteint d'AOMI, quel que soit son niveau de pression artérielle, en l'absence de contre-indication ?","answer":"Un IEC ou un sartan","accept":["iec","sartan","enzyme de conversion","ara2","ara ii"],"keywords":["iec"],"explanation":"Un traitement par inhibiteur de l'enzyme de conversion (ou sartan) peut être considéré chez tous les patients avec AOMI, quel que soit leur niveau de pression artérielle, en l'absence de contre-indication ; les IEC ont un intérêt pronostique.","src":"p. 175"},{"id":"225-qroc-616","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","pièges"],"difficulty":2,"question":"Dans quelle situation de l'AOMI les bêtabloquants doivent-ils être utilisés avec prudence, même en cas d'indication formelle ?","answer":"En cas d'ischémie critique sans revascularisation possible","accept":["ischémie critique","ischémie critique non revascularisable"],"keywords":["critique"],"explanation":"Les bêtabloquants ne sont proposés qu'en cas d'indication formelle (cardiopathie ischémique, insuffisance cardiaque à fraction d'éjection altérée, certaines arythmies), avec prudence en cas d'ischémie critique sans revascularisation possible.","src":"p. 175"},{"id":"225-qroc-617","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","prévention"],"difficulty":1,"question":"Lors d'une séance de marche d'entraînement, à quel moment le patient claudicant doit-il ralentir le pas ou s'arrêter quelques minutes ?","answer":"Au seuil de la douleur","accept":["seuil de la douleur","au seuil de la douleur","seuil douloureux","dès que la douleur"],"keywords":["seuil","douleur"],"explanation":"La marche régulière (au minimum 30-45 minutes, au moins 3 fois par semaine, de préférence supervisée) se fait en ralentissant le pas ou en s'arrêtant quelques minutes au seuil de la douleur.","src":"p. 175"},{"id":"225-qroc-618","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","physiopathologie"],"difficulty":2,"question":"Quel mécanisme vasculaire l'arrêt du tabac et la marche régulière favorisent-ils dans l'AOMI ?","answer":"Le développement de la circulation collatérale","accept":["circulation collatérale","collatérale","collatéralité"],"keywords":["collat"],"explanation":"L'arrêt du tabac et la marche régulière favorisent la circulation collatérale et l'état métabolique musculaire (augmentation du pool mitochondrial), ce qui allonge la distance de marche, voire fait disparaître la claudication.","src":"p. 175"},{"id":"225-qroc-619","type":"QROC","rank":"A","objective":"225-obj-06","tags":["complications","prévention"],"difficulty":1,"question":"Chez un patient porteur d'une AOMI ou d'un AAA, quelles autres localisations de l'athérome faut-il rechercher ?","answer":"Une maladie coronarienne et une sténose carotidienne","accept":["coronarienne et carotidienne","coronaire et carotide"],"keywords":["coron","carot"],"explanation":"Les autres atteintes athéromateuses sont très fréquentes chez l'artéritique et le porteur d'AAA : il faut rechercher une maladie coronarienne sous-jacente et une sténose carotidienne (atteinte cérébrovasculaire), dès l'interrogatoire et l'examen cardiovasculaire général.","src":"p. 170, 188"},{"id":"225-qroc-620","type":"QROC","rank":"A","objective":"225-obj-07","tags":["définition","urgence"],"difficulty":1,"question":"Comment définit-on l'ischémie aiguë d'un membre inférieur ?","answer":"Interruption brutale du flux artériel (hypoxie tissulaire abrupte)","accept":["interruption brutale","arrêt brutal du flux","interruption brutale du flux artériel"],"keywords":["brutal"],"explanation":"C'est une interruption brutale du flux artériel responsable d'une hypoxie tissulaire abrupte pouvant aboutir à la nécrose. C'est une urgence vasculaire : le pronostic du membre, voire du patient, est engagé.","src":"p. 178"},{"id":"225-qroc-621","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique","urgence"],"difficulty":2,"question":"Quel tableau réalise l'occlusion aiguë de la bifurcation aortique ?","answer":"Une ischémie bilatérale sévère avec paralysie sensitivomotrice","accept":["ischémie bilatérale sévère","ischémie bilatérale","ischémie des deux membres"],"keywords":["bilat"],"explanation":"Dans le cas le plus grave, l'occlusion de la bifurcation aortique provoque une ischémie bilatérale sévère avec paralysie sensitivomotrice. Les signes généraux sont alors souvent au premier plan, jusqu'au collapsus cardiovasculaire.","src":"p. 179"},{"id":"225-qroc-622","type":"QROC","rank":"A","objective":"225-obj-09","tags":["imagerie","diagnostic"],"difficulty":2,"question":"En cas d'embolie, que peut révéler l'artériographie en plus de localiser l'oblitération ?","answer":"D'autres emboles asymptomatiques (homo- ou controlatéraux)","accept":["autres emboles","emboles asymptomatiques","emboles"],"keywords":["embol"],"explanation":"L'artériographie, le plus souvent réalisée au bloc opératoire, localise l'oblitération, précise son aspect (athérome, anévrisme, dissection) et apprécie le réseau d'aval. En cas d'embolie, elle peut aussi révéler d'autres emboles asymptomatiques.","src":"p. 180"},{"id":"225-qroc-623","type":"QROC","rank":"A","objective":"225-obj-09","tags":["diagnostic","pièges"],"difficulty":2,"question":"À quel moment réalise-t-on le bilan cardiaque étiologique (Holter ECG, ETT, voire ETO) d'une ischémie aiguë de membre ?","answer":"Après la revascularisation","accept":["après la revascularisation","après revascularisation","une fois revascularisé"],"keywords":["apres","revascular"],"explanation":"Avant l'intervention, on se limite à l'examen clinique complété par l'auscultation cardiaque, l'ECG, la palpation abdominale et un bilan de coagulation. Holter ECG, ETT (voire ETO ou IRM) et bilan artériel complémentaire ne sont faits qu'après la revascularisation.","src":"p. 182"},{"id":"225-qroc-624","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","complications"],"difficulty":2,"question":"Quel traitement compense progressivement l'acidose métabolique du syndrome de revascularisation ?","answer":"L'alcalinisation par bicarbonates IV","accept":["bicarbonate","alcalinisation"],"keywords":["bicarbon"],"explanation":"Après revascularisation, on recherche systématiquement une acidose métabolique hyperkaliémique et une insuffisance rénale aiguë (diurèse horaire, ionogramme, urée, créatinine, CPK). L'acidose est compensée progressivement par des bicarbonates IV ; la kaliémie nécessite un chélateur du potassium, voire une dialyse.","src":"p. 183"},{"id":"225-qroc-625","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","pièges"],"difficulty":1,"question":"Quelle prise en charge peut être la seule solution chez un malade très âgé et moribond présentant une ischémie aiguë de membre ?","answer":"Une prise en charge palliative","accept":["palliative","soins palliatifs"],"keywords":["palliat"],"explanation":"Il faut évaluer rapidement la fonction cardiaque, les comorbidités et l'état général (pathologie incurable ou fortement handicapante). Une prise en charge palliative est parfois la seule solution chez un malade très âgé et moribond.","src":"p. 182"},{"id":"225-qroc-626","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","pièges"],"difficulty":2,"question":"Quelle erreur de prise en charge est qualifiée d'inacceptable devant une ischémie aiguë de membre ?","answer":"Retarder la prise en charge par des examens d'imagerie inutiles","accept":["retarder la prise en charge","retard de prise en charge","retarder l'intervention","examens inutiles"],"keywords":["retard"],"explanation":"Le diagnostic d'ischémie aiguë est clinique : aucune exploration ne doit retarder l'intervention, notamment en cas d'atteinte neurologique (grade II), et l'équipe chirurgicale doit être alertée au plus tôt.","src":"p. 180, 188"},{"id":"225-qroc-627","type":"QROC","rank":"A","objective":"225-obj-10","tags":["diagnostic","imagerie"],"difficulty":2,"question":"Quelles autres localisations anévrismales recherche-t-on, notamment à l'échographie, chez un patient porteur d'un AAA ?","answer":"Les artères poplitées et iliaques","accept":["poplitées et iliaques","iliaques et poplitées","poplitée et iliaque","iliaque et poplitée"],"keywords":["poplit","iliaq"],"explanation":"L'échographie abdominale dépiste l'AAA, mesure son diamètre maximal et assure son suivi ; elle recherche aussi les localisations associées les plus fréquentes, poplitées et iliaques. Un anévrisme poplité est lui-même associé à un AAA dans environ 30 % des cas.","src":"p. 184, 186"},{"id":"225-qroc-628","type":"QROC","rank":"A","objective":"225-obj-10","tags":["pronostic","épidémiologie"],"difficulty":2,"question":"Quel est le risque annuel de rupture d'un anévrisme de l'aorte sous-rénale de 50 à 59 mm de diamètre ?","answer":"Environ 3 % par an","accept":["3 %","3 % par an","3 pour cent"],"keywords":["3"],"explanation":"Le risque de rupture augmente de façon exponentielle avec le diamètre : très faible (0,4 %/an) en dessous de 40 mm, 3 % entre 50 et 59 mm, 15 % au-delà de 60 mm. À diamètre égal, il est près de 4 fois plus élevé chez la femme.","src":"p. 184"},{"id":"225-qroc-629","type":"QROC","rank":"A","objective":"225-obj-10","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel signe palpatoire fait évoquer un anévrisme de l'artère poplitée ?","answer":"Une masse battante au creux poplité (pouls « trop bien perçu »)","accept":["masse battante","battante","pouls trop bien perçu","trop bien perçu"],"keywords":["battante"],"explanation":"L'anévrisme poplité asymptomatique est découvert à la palpation d'une masse battante au creux poplité (pouls « trop bien perçu »), à l'échodoppler (surtout si AAA ou anévrisme poplité controlatéral), ou au stade d'artériopathie progressive, voire d'ischémie aiguë.","src":"p. 186"},{"id":"225-qroc-630","type":"QROC","rank":"A","objective":"225-obj-10","tags":["épidémiologie","étiologie"],"difficulty":1,"question":"Quels sont les deux principaux facteurs de risque d'AAA, en dehors de l'âge ?","answer":"Le tabagisme et les antécédents familiaux d'anévrisme","accept":["tabagisme et antécédents familiaux","tabac et antécédents familiaux","antécédents familiaux et tabagisme","antécédents familiaux et tabac"],"keywords":["taba","famil"],"explanation":"En dehors de l'âge, les principaux facteurs de risque d'AAA sont le tabagisme et les antécédents familiaux d'anévrisme. Les sujets ayant une autre localisation aortique (thoracique) ou artérielle périphérique sont à plus haut risque d'AAA, alors que les diabétiques sont moins souvent atteints.","src":"p. 183"},{"id":"225-qroc-631","type":"QROC","rank":"A","objective":"225-obj-11","tags":["étiologie","pièges"],"difficulty":2,"question":"Quelle maladie métabolique est moins souvent retrouvée chez les patients porteurs d'un AAA ?","answer":"Le diabète","accept":["diabète","diabétique"],"keywords":["diab"],"explanation":"En dehors de l'âge, les principaux facteurs de risque d'AAA sont le tabagisme et les antécédents familiaux d'anévrisme ; les diabétiques sont moins souvent atteints, à l'inverse de l'AOMI où le diabète est un facteur de risque majeur.","src":"p. 183"},{"id":"225-qroc-632","type":"QROC","rank":"A","objective":"225-obj-10","tags":["épidémiologie","pronostic"],"difficulty":2,"question":"À diamètre égal, chez quel sexe le risque de rupture d'un AAA est-il le plus élevé ?","answer":"Chez la femme (près de 4 fois plus)","accept":["femme","sexe féminin","féminin"],"keywords":["femme"],"explanation":"L'AAA est plus fréquent chez l'homme, mais à diamètre égal le risque de rupture est près de 4 fois plus important chez la femme.","src":"p. 184"},{"id":"225-qroc-633","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel signe retrouvé à la palpation abdominale évoque un anévrisme de l'aorte abdominale ?","answer":"Une masse battante et expansive en région para-ombilicale","accept":["masse battante","battante"],"keywords":["battante"],"explanation":"Un AAA asymptomatique est le plus souvent découvert fortuitement : à la palpation abdominale (masse battante et expansive en région para-ombilicale, avec ou sans souffle) ou, plus souvent, lors d'une imagerie abdominale (échographie, scanner ou IRM).","src":"p. 184"},{"id":"225-qroc-634","type":"QROC","rank":"A","objective":"225-obj-13","tags":["imagerie","pièges"],"difficulty":2,"question":"Pourquoi l'artériographie est-elle inadaptée pour mesurer la taille d'un AAA ?","answer":"Elle ne visualise que la lumière artérielle (thrombus mural fréquent)","accept":["lumière","thrombus mural","thrombus"],"keywords":["lumiere"],"explanation":"L'artériographie ne montre que la lumière artérielle et ne donne pas une mesure fiable du diamètre, à cause de la grande fréquence du thrombus mural intra-anévrismal. Le scanner avec injection est l'examen préthérapeutique de référence.","src":"p. 185"},{"id":"225-qroc-635","type":"QROC","rank":"A","objective":"225-obj-15","tags":["clinique","urgence"],"difficulty":1,"question":"Que fait craindre le caractère douloureux d'un anévrisme de l'aorte abdominale ?","answer":"Une rupture imminente (fissuration)","accept":["rupture imminente","rupture","fissuration"],"keywords":["ruptur"],"explanation":"Un AAA douloureux (douleur abdominale ou lombaire, avec ou sans choc hémorragique) est une urgence vitale : la douleur fait craindre une rupture imminente et impose une orientation immédiate vers un centre spécialisé de chirurgie vasculaire, où un scanner abdominal confirme le diagnostic.","src":"p. 184"},{"id":"225-qroc-636","type":"QROC","rank":"B","objective":"225-obj-15","tags":["traitement","urgence"],"difficulty":2,"question":"Quelle technique, alternative à la chirurgie ouverte, peut aussi traiter un AAA rompu chez un patient à très haut risque périopératoire ?","answer":"L'endoprothèse (traitement endovasculaire)","accept":["endoprothèse","endovasculaire","traitement endovasculaire"],"keywords":["endo"],"explanation":"L'AAA rompu est une urgence absolue : aucune imagerie autre que le scanner diagnostique ne doit retarder l'intervention chez un patient en choc hémorragique. L'endoprothèse est aussi proposée dans l'anévrisme rompu, d'autant plus souvent que le risque périopératoire est très élevé et que l'équipe est expérimentée.","src":"p. 186"},{"id":"225-qroc-637","type":"QROC","rank":"B","objective":"225-obj-14","tags":["suivi","imagerie"],"difficulty":2,"question":"Quels examens assurent la surveillance au long cours d'une endoprothèse aortique ?","answer":"Scanner ou échographie (de contraste)","accept":["scanner","échographie de contraste","échographie"],"keywords":["scanner"],"explanation":"Les endoprothèses nécessitent une surveillance régulière par scanner ou échographie de contraste, pour suivre le sac anévrismal et la position de la prothèse et détecter les endofuites, qui entretiennent l'évolutivité de l'anévrisme et un risque de rupture.","src":"p. 186"},{"id":"225-qroc-638","type":"QROC","rank":"B","objective":"225-obj-14","tags":["prévention","complications"],"difficulty":2,"question":"Pourquoi une antibioprophylaxie peut-elle se justifier avant un acte à risque bactérien chez un porteur de prothèse artérielle ?","answer":"Risque d'infection de la prothèse lors d'une bactériémie","accept":["infection de la prothèse","infection de prothèse"],"keywords":["infect"],"explanation":"En présence d'une prothèse artérielle, une bactériémie expose à un risque d'infection de la prothèse, ce qui peut justifier une antibioprophylaxie lors de tout acte thérapeutique à risque bactérien.","src":"p. 186"}],"edn":[{"id":"225-kfp-01","type":"KFP","rank":"A","objective":"225-obj-03","difficulty":2,"scenario":"Mme B., 68 ans, diabétique de type 2 et tabagique, consulte pour une gêne du mollet gauche apparaissant après environ 250 mètres de marche, cédant rapidement à l'arrêt. Elle rapporte aussi une fatigabilité inhabituelle à la marche depuis quelques mois. L'examen retrouve un pouls pédieux gauche non perçu et un IPS à 0,68 à gauche.","questions":[{"stem":"Quel est le stade clinique le plus probable selon la classification de Leriche et Fontaine ?","max":1,"options":["Stade I","Stade II","Stade III","Stade IV","Stade 0","Ischémie mésentérique","Syndrome des loges","Médiacalcose isolée"],"correct":[1],"explanation":"La claudication intermittente à la marche, cédant au repos, correspond au stade II de Leriche et Fontaine."},{"stem":"Quelle valeur d'IPS ce résultat traduit-il ?","max":1,"options":["Une AOMI sévère","Un IPS normal","Une médiacalcose","Une absence d'AOMI","Une ischémie critique certaine","Un IPS non interprétable","Une AOMI légère non significative","Un test de marche positif"],"correct":[0],"explanation":"Un IPS inférieur à 0,70 définit une AOMI sévère."},{"stem":"Quels examens sont appropriés à ce stade, en l'absence de projet de revascularisation immédiat ?","max":2,"options":["Échodoppler artériel des membres inférieurs","Angioscanner des membres inférieurs","Contrôle des facteurs de risque cardiovasculaire","Artériographie diagnostique","Test de marche sur tapis roulant","IRM cérébrale systématique","Dosage des D-dimères","Bilan hépatique systématique"],"correct":[0,2],"explanation":"L'échodoppler est l'examen de 1re intention pour localiser les lésions, et le contrôle des facteurs de risque est indispensable à tout stade ; l'angioscanner et l'artériographie ne sont utiles qu'en vue d'une revascularisation."}],"src":"p. 168-172"},{"id":"225-kfp-02","type":"KFP","rank":"A","objective":"225-obj-07","difficulty":3,"scenario":"M. R., 58 ans, en fibrillation atriale connue mais non traitée, présente brutalement une douleur intense du pied et de la jambe droite. À l'examen : membre froid, pâle, pouls poplité et distaux abolis, sensibilité conservée, motricité normale.","questions":[{"stem":"Quel grade de sévérité selon la classification de Rutherford correspond à ce tableau ?","max":1,"options":["Grade I","Grade IIa","Grade IIb","Grade III","Grade 0","Grade IV","Non classable","Grade attribué uniquement après imagerie"],"correct":[0],"explanation":"L'absence de déficit sensitif et moteur correspond au grade I (viable, pas de menace immédiate)."},{"stem":"Quelle est la mesure thérapeutique à instaurer en priorité, dès le diagnostic posé ?","max":1,"options":["Une anticoagulation par héparine non fractionnée","Une antibiothérapie probabiliste","Une corticothérapie","Un traitement thrombolytique systémique d'emblée","Une amputation d'emblée","Un jeûne strict prolongé","Une kinésithérapie de mobilisation immédiate","Une simple surveillance sans traitement"],"correct":[0],"explanation":"L'anticoagulation par héparine non fractionnée doit être débutée dès le diagnostic, après prélèvement du bilan de coagulation."},{"stem":"Quel(s) élément(s) du bilan étiologique cardiaque doi(ven)t être réalisé(s) sans retarder la prise en charge ?","max":2,"options":["Un ECG","Une auscultation cardiaque","Une échographie cardiaque transœsophagienne immédiate systématique","Une coronarographie systématique en urgence","Une palpation abdominale à la recherche d'un anévrisme","Un holter-ECG de 7 jours avant tout traitement","Une IRM cardiaque en urgence","Un cathétérisme droit"],"correct":[0,1],"explanation":"L'examen clinique initial est complété par un ECG et une auscultation cardiaque à la recherche d'une arythmie, sans retarder la revascularisation ; les autres examens cardiaques plus lourds sont réalisés secondairement."}],"src":"p. 178-182"},{"id":"225-kfp-03","type":"KFP","rank":"A","objective":"225-obj-12","difficulty":2,"scenario":"M. T., 71 ans, fumeur, est adressé pour une masse abdominale battante et expansive découverte à la palpation lors d'une consultation systématique. Il est asymptomatique par ailleurs. Une échographie confirme un anévrisme de l'aorte abdominale sous-rénale mesuré à 52 mm.","questions":[{"stem":"Quel examen complémentaire est indiqué pour préciser le bilan préthérapeutique ?","max":1,"options":["Un scanner abdominopelvien injecté","Une artériographie diagnostique isolée","Un dosage des D-dimères","Une IRM cérébrale","Une coloscopie","Un test de marche","Une biopsie de la paroi aortique","Un dosage de la ferritine"],"correct":[0],"explanation":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence, précisant le diamètre et l'anatomie de l'anévrisme."},{"stem":"Compte tenu du diamètre mesuré, quelle est la conduite à tenir la plus appropriée ?","max":1,"options":["Programmer une intervention « à froid »","Surveiller par échographie tous les 5 ans","Ne réaliser aucune surveillance particulière","Traiter uniquement par antibiotiques","Attendre l'apparition de symptômes avant tout geste","Proposer une simple aponévrotomie","Réaliser une amputation préventive","Prescrire un traitement anticoagulant curatif isolé"],"correct":[0],"explanation":"Au-delà de 50-55 mm, le risque de rupture devient important et justifie une intervention programmée « à froid »."},{"stem":"Quel(s) élément(s) doi(ven)t être surveillé(s) après le traitement, quelle que soit la technique choisie ?","max":2,"options":["Le risque cardiovasculaire général persistant","L'apparition d'une complication locale (faux anévrisme ou endofuite selon la technique)","Le taux de plaquettes de façon hebdomadaire à vie","La fonction thyroïdienne annuelle","La persistance du contrôle des facteurs de risque","La fonction pulmonaire par EFR annuelle","La glycémie capillaire quotidienne à vie chez le non-diabétique","Le poids uniquement"],"correct":[0,1],"explanation":"Après traitement, le risque cardiovasculaire persiste et doit être contrôlé, avec une surveillance adaptée à la technique (échodoppler après chirurgie, scanner/écho après endoprothèse pour dépister les endofuites)."}],"src":"p. 183-186"},{"id":"225-tcs-01","type":"TCS","rank":"A","objective":"225-obj-04","difficulty":2,"vignette":"Un homme de 62 ans, tabagique, consulte pour une douleur du mollet droit apparaissant à la marche. L'examen clinique retrouve un pouls pédieux droit faible.","items":[{"hypothesis":"Si vous pensiez à une AOMI","newInfo":"et que vous constatez un IPS mesuré à 0,80 à droite","panel":[0,0,1,8,6],"explanation":"Un IPS à 0,80 est inférieur à 0,90 : il confirme le diagnostic d'AOMI, sans être sévère (< 0,70)."},{"hypothesis":"Si vous pensiez à une AOMI sévère","newInfo":"et que vous constatez un IPS mesuré à 0,65 à droite","panel":[0,0,1,5,9],"explanation":"Un IPS inférieur à 0,70 définit une AOMI sévère, ce qui renforce fortement cette hypothèse."},{"hypothesis":"Si vous pensiez à une médiacalcose","newInfo":"et que vous constatez un IPS mesuré à 1,55 à droite chez ce patient par ailleurs non diabétique","panel":[0,1,2,9,3],"explanation":"Un IPS très élevé oriente vers une médiacalcose, bien que celle-ci soit plus classique chez le diabétique ; la pression d'orteil doit alors être mesurée."},{"hypothesis":"Si vous pensiez à une claudication d'origine artérielle plutôt que neurogène","newInfo":"et que vous constatez que la douleur cède en moins de 5 minutes à l'arrêt de la marche, sans position antalgique particulière","panel":[0,0,1,8,6],"explanation":"La sédation rapide (< 5 minutes) de la douleur à l'arrêt est un argument classique en faveur d'une claudication artérielle plutôt que neurogène."}],"src":"p. 168-171"},{"id":"225-tcs-02","type":"TCS","rank":"A","objective":"225-obj-07","difficulty":3,"vignette":"Un homme de 66 ans consulte aux urgences pour une douleur brutale de la jambe gauche apparue il y a 4 heures, avec un membre froid et des pouls abolis en aval du genou.","items":[{"hypothesis":"Si vous pensiez à une ischémie aiguë de grade I (viable)","newInfo":"et que vous constatez une sensibilité et une motricité parfaitement conservées","panel":[0,0,1,8,6],"explanation":"L'absence de tout déficit sensitivomoteur est compatible avec un grade I, sans menace immédiate."},{"hypothesis":"Si vous pensiez à une ischémie de grade IIb (immédiatement menaçante)","newInfo":"et que vous constatez une anesthésie du pied dépassant les orteils avec un déficit moteur modéré","panel":[0,0,1,5,9],"explanation":"Un déficit sensitif au-delà des orteils associé à un déficit moteur modéré définit le grade IIb, nécessitant une prise en charge immédiate."},{"hypothesis":"Si vous pensiez à une origine embolique plutôt que thrombotique","newInfo":"et que vous constatez que ce patient est en fibrillation atriale connue non anticoagulée, sans antécédent d'AOMI","panel":[0,0,1,6,8],"explanation":"Un contexte de fibrillation atriale chez un patient sans antécédent artériel oriente fortement vers une origine embolique sur artère saine."},{"hypothesis":"Si vous pensiez qu'un échodoppler pouvait être réalisé sans délai avant la revascularisation","newInfo":"et que vous constatez l'apparition d'une anesthésie du pied","panel":[9,4,1,0,1],"explanation":"L'apparition d'un déficit neurologique (grade II) impose de ne plus retarder l'intervention par un examen complémentaire, contrairement au grade I."}],"src":"p. 178-182"},{"id":"225-tcs-03","type":"TCS","rank":"A","objective":"225-obj-14","difficulty":2,"vignette":"Un homme de 70 ans, fumeur actif, est suivi pour un anévrisme de l'aorte abdominale sous-rénale de 42 mm, stable sur les dernières échographies.","items":[{"hypothesis":"Si vous pensiez qu'une simple surveillance échographique annuelle suffisait","newInfo":"et que le diamètre reste stable à 42 mm sur plusieurs contrôles","panel":[0,0,2,9,4],"explanation":"En dessous de 45 mm, une surveillance échographique standard est adaptée en l'absence de croissance rapide."},{"hypothesis":"Si vous pensiez qu'une surveillance renforcée tous les 6 mois était nécessaire","newInfo":"et que le diamètre passe à 47 mm lors du contrôle suivant","panel":[0,0,1,8,6],"explanation":"Au-delà de 45 mm, la surveillance échographique doit être renforcée à un rythme semestriel."},{"hypothesis":"Si vous pensiez qu'une intervention programmée devenait indiquée","newInfo":"et que le diamètre atteint 56 mm sur le contrôle suivant","panel":[0,0,1,5,9],"explanation":"Au-delà de 50-55 mm, le risque de rupture devient important et une intervention « à froid » est indiquée."},{"hypothesis":"Si vous pensiez que l'arrêt du tabac ralentirait la progression de l'anévrisme","newInfo":"et que le patient poursuit son tabagisme malgré les conseils","panel":[0,0,1,3,11],"explanation":"La poursuite du tabagisme accélère nettement la croissance de l'anévrisme (environ 3 fois plus rapide), renforçant l'intérêt de son arrêt."}],"src":"p. 185-186"},{"id":"225-kfp-51","type":"KFP","rank":"A","objective":"225-obj-17","difficulty":2,"scenario":"Mme L., 79 ans, en fibrillation atriale permanente dont l'anticoagulation a été interrompue il y a 2 semaines, consulte aux urgences pour une douleur abdominale brutale et très intense apparue il y a 3 heures, suivie de vomissements et d'une diarrhée. L'abdomen est souple et peu douloureux à la palpation, contrastant avec l'intensité de la douleur. PA 135/80 mmHg, FC 110/min irrégulière.","questions":[{"stem":"Quels éléments de ce tableau composent la triade évocatrice d'une ischémie mésentérique aiguë ?","max":3,"options":["Douleur abdominale aiguë pauvre en signes physiques","Vidange digestive accélérée (vomissements, diarrhée)","Contexte emboligène (fibrillation atriale)","Tachycardie à 110/min","Âge supérieur à 75 ans","Sexe féminin","Pression artérielle normale"],"correct":[0,1,2],"explanation":"La triade évocatrice associe douleur abdominale aiguë pauvre en signes physiques, vidange digestive accélérée et arguments emboligènes (FA)."},{"stem":"Quel examen demandez-vous pour confirmer le diagnostic ?","max":1,"options":["Angioscanner abdominal","Échodoppler des artères digestives","Électrocardiogramme","Échocardiographie transthoracique","Coloscopie","Bilan de coagulation"],"correct":[0],"explanation":"L'angioscanner confirme le diagnostic d'ischémie mésentérique aiguë. L'ECG et l'échocardiographie orientent vers une source embolique sans confirmer l'occlusion ; l'échodoppler digestif sert au diagnostic de la forme chronique."},{"stem":"L'angioscanner confirme une occlusion embolique de l'artère mésentérique supérieure avec des signes de souffrance d'un segment grêle. Quels sont les principes du traitement ?","max":2,"options":["Revascularisation endovasculaire ou chirurgicale","Résection des segments intestinaux nécrosés","Surveillance clinique simple en attendant une aggravation","Traitement antalgique seul","Coloscopie de contrôle à 48 h","Héparine seule, sans geste chirurgical"],"correct":[0,1],"explanation":"L'ischémie mésentérique aiguë est une urgence chirurgicale : le traitement associe résection des segments intestinaux nécrosés et revascularisation (chirurgicale ou endovasculaire)."}],"src":"p. 166-167, 182, 187"},{"id":"225-kfp-52","type":"KFP","rank":"A","objective":"225-obj-05","difficulty":3,"scenario":"M. P., 74 ans, diabétique de type 2 depuis 20 ans, ancien fumeur, consulte pour des douleurs nocturnes de l'avant-pied droit depuis 3 semaines, qu'il soulage en laissant pendre la jambe hors du lit. Il présente un ulcère de la pulpe du 2e orteil droit. Les pouls distaux droits ne sont pas perçus. L'IPS droit mesuré au doppler de poche est à 1,50.","questions":[{"stem":"Comment interprétez-vous l'IPS et quels examens réalisez-vous pour évaluer l'ischémie ?","max":3,"options":["L'IPS > 1,40 traduit une médiacalcose et n'est pas interprétable","Mesure de la pression d'orteil (index de pression d'orteil)","Mesure de la TcPO2","L'IPS > 1,40 élimine une AOMI","L'IPS à 1,50 est normal","Artériographie diagnostique en 1re intention","Scintigraphie myocardique"],"correct":[0,1,2],"explanation":"Un IPS > 1,40 traduit une médiacalcose (fréquente chez le diabétique) : on le remplace par l'index de pression d'orteil ; la TcPO2 est utile dans l'ischémie critique. L'artériographie est réservée à la revascularisation."},{"stem":"À quel stade de Leriche-Fontaine classez-vous cette artériopathie ?","max":1,"options":["Stade IV","Stade III","Stade II","Stade I","Grade I de Rutherford","Catégorie 0 de Rutherford"],"correct":[0],"explanation":"La présence d'un ulcère (trouble trophique) classe l'artériopathie au stade IV de Leriche-Fontaine (grade III, catégories 5-6 de Rutherford)."},{"stem":"Quelles mesures thérapeutiques retenez-vous ?","max":4,"options":["Revascularisation systématiquement proposée après bilan d'imagerie","Statine","Antiplaquettaire (aspirine ou clopidogrel)","Soins de plaies multidisciplinaires","Pentoxifylline pour améliorer le pronostic vital","Amputation d'emblée de l'avant-pied","Surélévation permanente du membre la nuit","Abstention de revascularisation en l'absence de claudication"],"correct":[0,1,2,3],"explanation":"En ischémie permanente, la revascularisation est systématiquement proposée ; statine et antiplaquettaire sont indiqués chez tout AOMI symptomatique ; soins de plaies multidisciplinaires ; l'amputation est un dernier recours ; les vasoactifs n'ont pas d'effet pronostique."}],"src":"p. 168-178"},{"id":"225-tcs-51","type":"TCS","rank":"A","objective":"225-obj-05","difficulty":2,"vignette":"Un homme de 67 ans, ancien fumeur, a une AOMI confirmée (IPS gauche à 0,62) révélée par une claudication du mollet gauche. Il reçoit une statine et un antiplaquettaire.","items":[{"hypothesis":"Si vous envisagiez une revascularisation,","newInfo":"et que son périmètre de marche est de 800 m avec une gêne modérée,","panel":[6,7,2,0,0],"explanation":"Chez le claudicant, la revascularisation n'est discutée qu'en cas de claudication sévère invalidante (< 100 m) : l'hypothèse est affaiblie."},{"hypothesis":"Si vous envisagiez une revascularisation,","newInfo":"et qu'il présente depuis 3 semaines des douleurs de décubitus soulagées jambe pendante,","panel":[0,0,0,3,12],"explanation":"L'ischémie permanente impose de proposer systématiquement une revascularisation."},{"hypothesis":"Si vous envisagiez une revascularisation,","newInfo":"et que sa claudication est devenue invalidante à 80 m malgré un traitement médical bien conduit,","panel":[0,0,1,7,7],"explanation":"Une claudication invalidante < 100 m après échec du traitement médical fait discuter la revascularisation."},{"hypothesis":"Si vous envisagiez une angioplastie endovasculaire,","newInfo":"et que l'imagerie montre une lésion courte et proximale,","panel":[0,0,1,6,8],"explanation":"L'angioplastie (± stent) s'adresse aux lésions courtes et proximales."},{"hypothesis":"Si vous envisagiez une angioplastie endovasculaire,","newInfo":"et que l'imagerie montre des lésions étendues,","panel":[4,8,3,0,0],"explanation":"Les lésions étendues relèvent plutôt de la chirurgie (pontage, endartériectomie), des techniques hybrides restant possibles."}],"src":"p. 175-178"},{"id":"225-tcs-52","type":"TCS","rank":"A","objective":"225-obj-17","difficulty":2,"vignette":"Une femme de 77 ans consulte aux urgences pour une douleur abdominale brutale et intense évoluant depuis 2 heures.","items":[{"hypothesis":"Si vous pensiez à une ischémie mésentérique aiguë,","newInfo":"et qu'elle est en fibrillation atriale et a arrêté son anticoagulant,","panel":[0,0,1,6,8],"explanation":"Un contexte emboligène (FA) fait partie de la triade évocatrice."},{"hypothesis":"Si vous pensiez à une ischémie mésentérique aiguë,","newInfo":"et que l'abdomen est souple et peu douloureux, contrastant avec l'intensité de la douleur,","panel":[0,0,1,6,8],"explanation":"Une douleur aiguë pauvre en signes physiques fait partie de la triade évocatrice."},{"hypothesis":"Si vous envisagiez de demander un angioscanner abdominal,","newInfo":"et qu'elle présente des vomissements et une diarrhée,","panel":[0,0,2,6,7],"explanation":"La vidange digestive accélérée complète la triade évocatrice, ce qui renforce l'indication de l'angioscanner, examen qui confirme le diagnostic."}],"src":"p. 167, 187"}],"trees":[{"id":"225-tree-01","title":"Démarche diagnostique devant une suspicion d'AOMI","rank":"A","objective":"225-obj-04","intro":"L'index de pression systolique (IPS) est le premier examen à réaliser devant une suspicion d'artériopathie oblitérante des membres inférieurs.","root":"n1","nodes":{"n1":{"type":"question","text":"Le patient se plaint-il de douleur à la marche ou plutôt de douleur/troubles trophiques permanents ?","options":[{"label":"Douleur à la marche (claudication)","to":"n2"},{"label":"Douleur ou troubles trophiques au repos","to":"n9"}]},"n2":{"type":"action","text":"Mesurer l'index de pression systolique (IPS) au repos.","to":"n3"},"n3":{"type":"question","text":"Quel est le résultat de l'IPS ?","options":[{"label":"< 0,90","to":"n4"},{"label":"1,00-1,40 mais patient symptomatique","to":"n5"},{"label":"> 1,40","to":"n6"}]},"n4":{"type":"end","tone":"ok","text":"AOMI confirmée ; compléter par un échodoppler artériel des membres inférieurs.","note":"IPS < 0,90 sur au moins une cheville ; < 0,70 définit une AOMI sévère."},"n5":{"type":"action","text":"Réaliser un test de marche sur tapis roulant (protocole de Strandness : 3,2 km/h, pente 10 %).","to":"n7"},"n6":{"type":"action","text":"Suspecter une médiacalcose : mesurer la pression (index) d'orteil.","to":"n6b"},"n6b":{"type":"question","text":"L'index de pression d'orteil est-il < 0,70 ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n8b"}]},"n7":{"type":"question","text":"Après l'effort, la pression de cheville chute-t-elle > 30 mmHg ou l'IPS > 20 % ?","options":[{"label":"Oui","to":"n8"},{"label":"Non","to":"n8b"}]},"n8":{"type":"end","tone":"ok","text":"AOMI démasquée par le test de marche malgré un IPS de repos normal."},"n8b":{"type":"end","tone":"info","text":"Évoquer un diagnostic différentiel de la claudication (canal lombaire étroit, claudication veineuse, cause rhumatologique ou musculaire)."},"n9":{"type":"action","text":"Rechercher une ischémie critique : pression de cheville < 50 mmHg ou d'hallux < 30 mmHg.","to":"n10"},"n10":{"type":"end","tone":"warn","text":"Ischémie permanente/critique : discuter systématiquement une revascularisation."}},"src":"p. 170-172"},{"id":"225-tree-02","title":"Stratégie de prise en charge de la claudication intermittente","rank":"A","objective":"225-obj-05","intro":"Le traitement des facteurs de risque et l'antiplaquettaire s'appliquent à tous les patients ; la suite dépend du retentissement fonctionnel.","root":"n1","nodes":{"n1":{"type":"action","text":"Débuter contrôle des facteurs de risque, statine et antiplaquettaire (± IEC si HTA ou insuffisance cardiaque).","to":"n2"},"n2":{"type":"question","text":"Périmètre de marche < 100 m et/ou atteinte aorto-iliaque sévère et extensive ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"end","tone":"warn","text":"Envisager d'emblée une revascularisation (angioplastie ou chirurgie)."},"n4":{"type":"action","text":"Proposer une réadaptation à la marche, de préférence supervisée, avec éducation thérapeutique.","to":"n5"},"n5":{"type":"question","text":"Disparition de la claudication ou allongement significatif du périmètre de marche ?","options":[{"label":"Oui","to":"n6"},{"label":"Non, échec du traitement médical bien conduit","to":"n3"}]},"n6":{"type":"end","tone":"ok","text":"Poursuivre la réadaptation et le traitement médical ; réévaluer périodiquement."}},"src":"p. 176-177"},{"id":"225-tree-03","title":"Prise en charge de l'ischémie aiguë de membre selon la sévérité","rank":"A","objective":"225-obj-09","intro":"Le degré d'urgence dépend du grade de sévérité de Rutherford ; aucune exploration ne doit retarder l'intervention en cas de déficit neurologique.","root":"n1","nodes":{"n1":{"type":"action","text":"Débuter sans délai héparine non fractionnée, antalgiques et soins locaux.","to":"n2"},"n2":{"type":"question","text":"Quel est le grade de sévérité (Rutherford) ?","options":[{"label":"Grade I (viable, pas de déficit)","to":"n3"},{"label":"Grade IIa/IIb (déficit sensitif ± moteur)","to":"n5"},{"label":"Grade III (irréversible)","to":"n7"}]},"n3":{"type":"action","text":"Un échodoppler peut être réalisé sans perte de temps si les conditions le permettent, puis débuter le bilan étiologique.","to":"n4"},"n4":{"type":"end","tone":"info","text":"Revascularisation dans les heures suivantes (thrombolyse, thromboaspiration, thrombectomie ou pontage selon le contexte)."},"n5":{"type":"action","text":"N'engager aucune exploration retardant la prise en charge ; alerter l'équipe chirurgicale au plus tôt.","to":"n6"},"n6":{"type":"end","tone":"danger","text":"Revascularisation en urgence absolue (thrombectomie/pontage)."},"n7":{"type":"end","tone":"danger","text":"Ischémie dépassée : amputation d'emblée."}},"src":"p. 179-180"},{"id":"225-tree-04","title":"Orientation étiologique devant une ischémie aiguë de membre","rank":"B","objective":"225-obj-08","intro":"Deux grands tableaux s'opposent, sans être toujours totalement distincts : la thrombose in situ et l'embolie sur artère saine.","root":"n1","nodes":{"n1":{"type":"question","text":"Sujet âgé, facteurs de risque cardiovasculaire, antécédent d'AOMI, douleur d'intensité moyenne d'installation progressive ?","options":[{"label":"Oui, tableau évocateur de thrombose","to":"n2"},{"label":"Non : sujet jeune, douleur brutale et sévère, sans antécédent vasculaire","to":"n4"}]},"n2":{"type":"action","text":"Orienter vers une thrombose artérielle in situ ; rechercher une AOMI controlatérale, une déshydratation ou une coagulopathie.","to":"n3"},"n3":{"type":"end","tone":"info","text":"Bilan étiologique : auscultation cardiaque, ECG, palpation abdominale, bilan de coagulation."},"n4":{"type":"action","text":"Orienter vers une embolie sur artère saine ; rechercher une cardiopathie emboligène (fibrillation atriale, infarctus, endocardite, myxome).","to":"n5"},"n5":{"type":"question","text":"L'auscultation cardiaque, l'ECG ou la palpation abdominale retrouvent-ils une source embolique ?","options":[{"label":"Oui (ex. fibrillation atriale, anévrisme aortique)","to":"n6"},{"label":"Non, bilan initial négatif","to":"n7"}]},"n6":{"type":"end","tone":"ok","text":"Traiter la cause après revascularisation (ex. anticoagulation au long cours si fibrillation atriale)."},"n7":{"type":"end","tone":"info","text":"Compléter à distance par un bilan cardiaque (Holter, ETT ± ETO/IRM) et un bilan artériel (échodoppler, angioscanner)."}},"src":"p. 181-183"},{"id":"225-tree-05","title":"Surveillance et décision d'intervention d'un anévrisme de l'aorte abdominale asymptomatique","rank":"B","objective":"225-obj-14","intro":"Le diamètre de l'anévrisme est le principal facteur prédictif de rupture et détermine le rythme de surveillance et l'indication opératoire.","root":"n1","nodes":{"n1":{"type":"question","text":"Quel est le diamètre de l'anévrisme de l'aorte abdominale ?","options":[{"label":"< 45 mm","to":"n2"},{"label":"45-54 mm","to":"n3"},{"label":"> 50-55 mm","to":"n5"}]},"n2":{"type":"end","tone":"ok","text":"Surveillance échographique standard et contrôle des facteurs de risque (arrêt du tabac)."},"n3":{"type":"action","text":"Renforcer la surveillance échographique (tous les 6 mois) et intensifier le contrôle des facteurs de risque.","to":"n4"},"n4":{"type":"end","tone":"info","text":"Réévaluer le diamètre à 6 mois ; discuter l'intervention si le seuil est atteint ou si progression rapide."},"n5":{"type":"question","text":"Le patient est-il à haut risque chirurgical, avec une anatomie favorable au traitement endovasculaire ?","options":[{"label":"Oui","to":"n6"},{"label":"Non ou anatomie défavorable","to":"n7"}]},"n6":{"type":"end","tone":"ok","text":"Traitement endovasculaire (endoprothèse) avec surveillance itérative à la recherche d'endofuites."},"n7":{"type":"end","tone":"ok","text":"Chirurgie conventionnelle à ciel ouvert (exclusion et interposition d'une prothèse)."}},"src":"p. 185-186"},{"id":"225-tree-06","title":"Conduite à tenir devant un anévrisme de l'aorte abdominale symptomatique","rank":"A","objective":"225-obj-15","intro":"Toute douleur chez un porteur connu ou suspecté d'AAA doit faire craindre une fissuration ou une rupture, urgence absolue.","root":"n1","nodes":{"n1":{"type":"question","text":"Douleur abdominale ou lombaire chez un patient porteur (connu ou suspecté) d'un AAA ?","options":[{"label":"Oui, avec choc hémorragique","to":"n2"},{"label":"Oui, patient hémodynamiquement stable","to":"n4"}]},"n2":{"type":"action","text":"Diriger en urgence vers un centre de chirurgie vasculaire ; ne réaliser que le scanner diagnostique.","to":"n3"},"n3":{"type":"end","tone":"danger","text":"Traitement en urgence absolue : chirurgie à ciel ouvert ou endoprothèse selon l'expérience de l'équipe."},"n4":{"type":"action","text":"Réaliser un scanner abdominal pour confirmer une fissuration/rupture ou une autre complication.","to":"n5"},"n5":{"type":"question","text":"Le scanner confirme-t-il une fissuration ou une complication (fistule, embolie, syndrome inflammatoire) ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n6"}]},"n6":{"type":"end","tone":"info","text":"Reprendre la surveillance programmée selon le diamètre de l'anévrisme."}},"src":"p. 184-186"}],"treatments":{"data":[{"id":"225-tx-01","rank":"A","class":"Contrôle des facteurs de risque cardiovasculaire","molecules":[],"context":"Mesure de fond appliquée à tout stade d'AOMI et chez tout porteur d'anévrisme de l'aorte.","indications":["Arrêt du tabac","Équilibre du diabète","Contrôle tensionnel","Contrôle du LDL-cholestérol","Régime méditerranéen, IMC cible 20-25 kg/m²"],"contraindications":[],"sideEffects":[],"monitoring":["HbA1c cible < 7 %","PAS 120-129 mmHg, PAD 70-79 mmHg","LDL-cholestérol < 0,55 g/L avec réduction ≥ 50 %"],"interactions":[],"pearls":["S'applique à tous les stades de l'AOMI, symptomatique ou non.","Le tabagisme accélère aussi la progression d'un anévrisme de l'aorte abdominale."],"src":"p. 175"},{"id":"225-tx-02","rank":"A","class":"Antiplaquettaires","molecules":["aspirine","clopidogrel"],"context":"Réduction du risque de complications cardiovasculaires (infarctus, AVC) chez le patient artériopathe.","indications":["AOMI symptomatique (systématique)","AOMI asymptomatique avec autre localisation athéromateuse (discuté)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Débattu en cas d'AOMI purement asymptomatique isolée."],"src":"p. 175"},{"id":"225-tx-03","rank":"A","class":"Statines","molecules":["statine"],"context":"Traitement hypolipémiant systématique du patient AOMI, quel que soit le LDL initial.","indications":["Tout patient AOMI"],"contraindications":[],"sideEffects":[],"monitoring":["LDL-cholestérol cible < 0,55 g/L (< 1,4 mmol/L) avec réduction ≥ 50 % par rapport à la valeur initiale"],"interactions":[],"pearls":["L'instauration d'une statine peut s'accompagner d'une augmentation du périmètre de marche.","Des douleurs musculaires sous statines peuvent mimer une claudication et créer un piège diagnostique."],"src":"p. 175-176"},{"id":"225-tx-04","rank":"A","class":"Inhibiteurs de l'enzyme de conversion (IEC) / sartans","molecules":["IEC","sartan"],"context":"Intérêt pronostique chez le patient AOMI, pouvant être envisagé quel que soit le niveau tensionnel en l'absence de contre-indication.","indications":["AOMI, notamment si HTA associée"],"contraindications":[],"sideEffects":[],"monitoring":["Cible de pression artérielle < 140/90 mmHg"],"interactions":[],"pearls":[],"src":"p. 175"},{"id":"225-tx-05","rank":"A","class":"Bêtabloquants","molecules":[],"context":"Utilisables chez le patient AOMI en présence d'une indication cardiologique formelle.","indications":["Cardiopathie ischémique associée","Insuffisance cardiaque à fraction d'éjection altérée","Certaines arythmies"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Prudence en cas d'ischémie critique non revascularisable."],"src":"p. 175"},{"id":"225-tx-07","rank":"B","class":"Traitements vasoactifs","molecules":["pentoxifylline"],"context":"Bénéfice modeste sur le périmètre de marche de la claudication, sans effet pronostique démontré à long terme.","indications":["Amélioration symptomatique modeste du périmètre de marche"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Plusieurs molécules de cette classe ont été retirées du marché pour futilité ou déremboursées."],"src":"p. 176"},{"id":"225-tx-08","rank":"B","class":"Prostaglandines","molecules":["prostaglandines"],"context":"Ischémie critique non revascularisable, en perfusions quotidiennes durant plusieurs semaines en milieu spécialisé.","indications":["Ischémie critique non revascularisable"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 176"},{"id":"225-tx-09","rank":"A","class":"Réadaptation à la marche et arrêt du tabac (traitement à visée locale)","molecules":[],"context":"Traitement de première ligne de la claudication non invalidante, idéalement supervisé.","indications":["Claudication intermittente"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Marche régulière 30-45 min, ≥ 3 fois/semaine, en s'arrêtant au seuil de la douleur.","La réadaptation supervisée donne de meilleurs résultats que le programme non supervisé et s'accompagne d'une éducation thérapeutique."],"src":"p. 175-176"},{"id":"225-tx-10","rank":"A","class":"Angioplastie endovasculaire (± stent) de l'AOMI","molecules":[],"context":"Technique de revascularisation de référence pour les lésions courtes et proximales.","indications":["Ischémie permanente","Claudication sévère invalidante après échec du traitement médical bien conduit"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance clinique et écho-Doppler systématique après le geste"],"interactions":[],"pearls":["Bithérapie antiplaquettaire poursuivie 1 à 6 mois après le geste selon sa localisation.","L'angioplastie sous-adventicielle peut être proposée en cas d'occlusion longue."],"src":"p. 176"},{"id":"225-tx-11","rank":"A","class":"Chirurgie de revascularisation (pontage, endartériectomie) de l'AOMI","molecules":[],"context":"Traitée essentiellement par pontage (matériel veineux de préférence) pour court-circuiter les lésions étendues.","indications":["Ischémie permanente","Claudication sévère invalidante après échec du traitement médical"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance clinique et écho-Doppler systématique après le geste"],"interactions":[],"pearls":["Pontages les plus fréquents : aorto-bi-iliaque (ou bifémoral), fémoropoplité, fémorojambier.","Techniques hybrides possibles (chirurgie associée à l'endovasculaire)."],"src":"p. 176"},{"id":"225-tx-12","rank":"A","class":"Amputation","molecules":[],"context":"Geste ultime en l'absence de toute possibilité de revascularisation.","indications":["Ischémie dépassée","Échec de la revascularisation avec désordres métaboliques majeurs"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Doit être réalisée en zone saine et bien oxygénée, guidée par la mesure de TcPO2.","Préférer une amputation limitée (orteil, transmétatarsienne) ou sous le genou pour permettre l'appareillage."],"src":"p. 176-177"},{"id":"225-tx-13","rank":"A","class":"Anticoagulation par héparine non fractionnée (ischémie aiguë de membre)","molecules":["héparine non fractionnée"],"context":"Débutée dès le diagnostic d'ischémie aiguë, après le prélèvement du bilan de coagulation.","indications":["Ischémie aiguë de membre, dès la suspicion diagnostique"],"contraindications":[],"sideEffects":[],"monitoring":["TCA cible entre 2 et 3"],"interactions":[],"pearls":["Posologie : bolus de 5 000 UI puis perfusion continue de 500 UI/kg/j."],"src":"p. 182"},{"id":"225-tx-14","rank":"A","class":"Embolectomie à la sonde de Fogarty","molecules":[],"context":"Méthode de revascularisation de référence de l'embolie sur artère saine, réalisée sous contrôle angiographique.","indications":["Ischémie aiguë de membre par embolie sur artère saine"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Peut aussi être utilisée sur des artères athéromateuses."],"src":"p. 182"},{"id":"225-tx-15","rank":"B","class":"Thrombolyse in situ / thromboaspiration","molecules":[],"context":"Alternative à l'embolectomie lorsque le lit d'aval jambier est de mauvaise qualité et l'ischémie peu sévère.","indications":["Ischémie aiguë peu sévère avec lit d'aval jambier de mauvaise qualité"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance en milieu spécialisé avec contrôles angiographiques répétés"],"interactions":[],"pearls":["Injection du fibrinolytique directement dans le thrombus via un cathéter laissé en place plusieurs heures."],"src":"p. 182"},{"id":"225-tx-16","rank":"A","class":"Aponévrotomie de décompression","molecules":[],"context":"Geste systématique en cas de revascularisation tardive pour prévenir ou traiter le syndrome des loges.","indications":["Syndrome des loges","Revascularisation tardive d'une ischémie aiguë"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Le plus souvent réalisée sur la loge antéro-externe de jambe ; d'autres loges, y compris le pied, peuvent être décomprimées."],"src":"p. 178-183"},{"id":"225-tx-17","rank":"A","class":"Traitement des conséquences métaboliques de la revascularisation","molecules":["bicarbonates","polystyrène sulfonate de sodium"],"context":"Prise en charge du syndrome de revascularisation (acidose, hyperkaliémie, insuffisance rénale).","indications":["Acidose métabolique et hyperkaliémie post-revascularisation","Insuffisance rénale aiguë débutante"],"contraindications":[],"sideEffects":[],"monitoring":["Diurèse (sonde urinaire), ionogramme, urée, créatininémie, CPK"],"interactions":[],"pearls":["Recours possible à la dialyse en cas d'échec.","Lavage de membre au sérum physiologique associé."],"src":"p. 183"},{"id":"225-tx-18","rank":"A","class":"Chirurgie conventionnelle de l'anévrisme de l'aorte abdominale (mise à plat-greffe)","molecules":[],"context":"Exclusion de la zone anévrismale et interposition d'une prothèse vasculaire.","indications":["AAA > 50-55 mm de diamètre, intervention « à froid »","AAA rompu"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance écho-Doppler à long terme (risque de faux anévrisme anastomotique)"],"interactions":[],"pearls":["La thrombose de la prothèse est exceptionnelle."],"src":"p. 185-186"},{"id":"225-tx-19","rank":"A","class":"Traitement endovasculaire de l'anévrisme de l'aorte abdominale (endoprothèse)","molecules":[],"context":"Moins invasif, préféré chez les sujets à haut risque chirurgical si l'anatomie est favorable.","indications":["AAA > 50-55 mm avec anatomie favorable","AAA rompu, notamment si très haut risque périopératoire"],"contraindications":["Anatomie défavorable limitant la faisabilité"],"sideEffects":[],"monitoring":["Surveillance itérative au long cours par scanner et échographie de contraste (endofuites)"],"interactions":[],"pearls":["Les endofuites peuvent faire progresser voire rompre l'anévrisme malgré le traitement."],"src":"p. 186"},{"id":"225-tx-20","rank":"B","class":"Antibioprophylaxie chez le porteur de prothèse vasculaire","molecules":[],"context":"Justifiée lors de tout acte à risque bactérien du fait du risque d'infection de la prothèse.","indications":["Geste à risque bactérien chez un porteur de prothèse vasculaire ou d'endoprothèse"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 186"},{"id":"225-tx-21","rank":"A","class":"Revascularisation des ischémies mésentériques (chronique et aiguë)","molecules":[],"context":"Forme chronique : revascularisation de préférence endovasculaire ; forme aiguë : résection des segments intestinaux infarcis associée à une revascularisation endovasculaire ou chirurgicale.","indications":["Ischémie mésentérique chronique symptomatique (angor digestif)","Ischémie mésentérique aiguë, associée à la résection des segments intestinaux infarcis"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 166-167, 187"}],"strategies":[{"id":"225-strat-01","rank":"A","title":"Traitement de fond de l'AOMI, tous stades confondus","content":"**Objectif** : améliorer le pronostic cardiovasculaire et vital global.\n\n- Contrôle des facteurs de risque : arrêt du tabac, équilibre du diabète (HbA1c < 7 %), objectif tensionnel PAS 120-129 / PAD 70-79 mmHg, IMC 20-25 kg/m², régime méditerranéen, réentraînement 3 fois/semaine pendant 12 semaines.\n- Statine systématique, cible LDL < 0,55 g/L avec réduction ≥ 50 %.\n- Antiplaquettaire (aspirine ou clopidogrel) si AOMI symptomatique ; discuté si asymptomatique isolée.\n- IEC (ou sartan) d'intérêt pronostique, cible PA < 140/90 mmHg.\n- Bêtabloquant possible si indication cardiologique formelle, prudence en ischémie critique non revascularisable.","src":"p. 175"},{"id":"225-strat-02","rank":"A","title":"Stratégie de prise en charge de la claudication intermittente","content":"1. Dans tous les cas : prise en charge des facteurs de risque cardiovasculaire, statine, antiplaquettaire (± IEC si HTA ou insuffisance cardiaque).\n2. Si claudication très invalidante (périmètre de marche < 100 m) ou atteinte aorto-iliaque sévère et extensive : envisager d'emblée une revascularisation.\n3. Sinon : réadaptation à la marche, de préférence supervisée en centre de réadaptation.\n4. Si disparition de la claudication ou allongement significatif du périmètre de marche : poursuite du traitement médical.\n5. En cas d'échec du traitement médical bien conduit : envisager une revascularisation (angioplastie ou chirurgie).","src":"p. 176-177"},{"id":"225-strat-03","rank":"A","title":"Indications de la revascularisation dans l'AOMI","content":"- Systématiquement proposée en cas d'**ischémie permanente**.\n- Discutée en cas de **claudication sévère invalidante**, notamment après échec du traitement médical bien conduit (réadaptation incluse), ou d'emblée si périmètre de marche très faible (< 100 m) avec fort retentissement fonctionnel ou atteinte aorto-iliaque sévère.\n- Choix de la technique selon l'étendue et la sévérité des lésions : angioplastie endovasculaire ± stent pour les lésions courtes/proximales (bithérapie antiplaquettaire 1-6 mois), chirurgie (pontage, endartériectomie) pour les lésions étendues ; techniques hybrides possibles.\n- Surveillance clinique et écho-Doppler systématique après le geste, quelle que soit la méthode.","src":"p. 176"},{"id":"225-strat-04","rank":"A","title":"Prise en charge de l'ischémie aiguë de membre selon le degré d'urgence","content":"1. Dès la suspicion : héparine non fractionnée, antalgiques et soins locaux, quel que soit le grade.\n2. **Grade III (irréversible)** : amputation.\n3. **Grade IIa/IIb (viable avec déficit sensitif ± moteur)** : revascularisation en urgence absolue (thrombectomie/pontage), sans aucune exploration retardant l'intervention.\n4. **Grade I (viable)** : imagerie possible sans perte de temps, puis revascularisation dans les heures suivantes (thrombolyse, thromboaspiration, thrombectomie ou pontage) et bilan étiologique.\n5. Dans tous les cas : traitement médical associé (anticoagulation, analgésie, correction des troubles hydroélectrolytiques) et surveillance des conséquences métaboliques de la revascularisation.","src":"p. 179-183"},{"id":"225-strat-05","rank":"A","title":"Surveillance et traitement de l'anévrisme de l'aorte abdominale selon le diamètre","content":"- Diamètre < 45 mm : surveillance échographique standard, contrôle des facteurs de risque.\n- Diamètre approchant le seuil d'intervention (> 45 mm) : surveillance échographique renforcée, tous les 6 mois.\n- Diamètre > 50-55 mm : intervention programmée « à froid », chirurgie conventionnelle (mise à plat-greffe) ou endoprothèse selon le terrain et l'anatomie.\n- Après traitement, quel qu'il soit : surveillance à vie du risque cardiovasculaire général, écho-Doppler après chirurgie (faux anévrisme), scanner/échographie après endoprothèse (endofuites).","src":"p. 185-186"},{"id":"225-strat-06","rank":"A","title":"Conduite à tenir devant un anévrisme de l'aorte abdominale symptomatique","content":"1. Douleur abdominale ou lombaire chez un porteur (connu ou suspecté) d'AAA : urgence absolue.\n2. Aucune imagerie autre que le scanner diagnostique ne doit retarder l'intervention chez un patient en choc hémorragique.\n3. Diriger le patient sans délai vers un centre spécialisé de chirurgie vasculaire.\n4. Traitement chirurgical à ciel ouvert ou par endoprothèse (de plus en plus proposée même en contexte de rupture), selon l'expérience de l'équipe et le terrain.\n5. En cas d'ischémie aiguë de membre par embolie à partir de l'AAA : revascularisation du membre en urgence, cure de l'AAA secondairement.","src":"p. 184-186"}]},"cases":[{"id":"225-case-01","title":"M. Lefèvre, 64 ans, douleur du mollet à la marche","rank":"A","summary":"Claudication intermittente révélant une AOMI, du diagnostic à une revascularisation après échec du traitement médical, puis épisode d'ischémie aiguë.","difficulty":2,"timeline":["Consultation initiale","Bilan diagnostique","Diagnostic et sévérité","Traitement médical","Échec médical et revascularisation","Suivi à long terme et complication"],"steps":[{"id":"225-case-01-s01","phase":0,"narrative":"M. Lefèvre, 64 ans, tabagique à 40 paquets-années, consulte pour une gêne du mollet gauche apparaissant systématiquement après 300 mètres de marche et cédant rapidement à l'arrêt.","question":{"type":"QRM","stem":"Quels éléments de l'interrogatoire faut-il rechercher chez ce patient ?","options":[{"t":"Le délai de disparition de la douleur à l'arrêt de la marche","ok":true,"why":"Une disparition en moins de 5 minutes est caractéristique de la claudication artérielle."},{"t":"La présence de troubles de l'érection","ok":true,"why":"Ils peuvent s'intégrer dans un syndrome de Leriche en cas d'atteinte aorto-iliaque."},{"t":"Un antécédent d'angor ou de symptômes neurologiques déficitaires","ok":true,"why":"L'AOMI est fréquemment associée à d'autres atteintes athéromateuses à rechercher systématiquement."},{"t":"La notion de douleur nocturne calmée en position debout","ok":false,"why":"C'est la position déclive, pas la position debout prolongée, qui soulage les douleurs de décubitus de l'ischémie permanente."},{"t":"La prise d'un traitement par statine, source possible de myalgies simulatrices","ok":true,"why":"Les douleurs musculaires sous statine peuvent mimer une claudication et constituer un piège diagnostique."}],"explanation":"La claudication artérielle typique cède en moins de 5 minutes ; il faut aussi rechercher un syndrome de Leriche, les autres atteintes athéromateuses et éliminer les diagnostics différentiels, notamment médicamenteux."},"reveal":"Le patient rapporte une disparition de la douleur en 3 minutes environ, sans trouble de l'érection ni antécédent cardiovasculaire connu ; il ne prend pas de statine.","src":"p. 168-169"},{"id":"225-case-01-s02","phase":0,"narrative":"À l'examen bilatéral et comparatif, le pouls pédieux gauche est aboli, le pouls poplité est perçu ; le temps de recoloration cutanée est de 2 secondes.","question":{"type":"QRU","stem":"Quel examen complémentaire réaliser en première intention ?","options":[{"t":"Échodoppler artériel des membres inférieurs","ok":false,"why":"C'est l'examen de 1re intention pour localiser une sténose, mais il n'est pas le tout premier geste devant une suspicion clinique."},{"t":"Index de pression systolique (IPS)","ok":true,"why":"L'IPS est l'examen de première intention devant toute suspicion d'AOMI."},{"t":"Angioscanner des membres inférieurs","ok":false,"why":"Il n'est demandé qu'en vue d'une revascularisation, pas en première intention."},{"t":"Artériographie","ok":false,"why":"Elle est réservée aux procédures de revascularisation."},{"t":"Test de marche sur tapis roulant","ok":false,"why":"Il est utile seulement si l'IPS de repos est normal chez un patient symptomatique."}],"explanation":"L'IPS, simple et non invasif, est le premier examen à réaliser devant une suspicion clinique d'AOMI."},"reveal":"L'IPS est mesuré au doppler de poche des deux côtés.","src":"p. 170-171"},{"id":"225-case-01-s03","phase":1,"narrative":"L'IPS retrouve 0,65 à gauche et 1,05 à droite.","question":{"type":"QRM","stem":"Comment interpréter ce résultat ?","options":[{"t":"Le diagnostic d'AOMI est confirmé côté gauche","ok":true,"why":"Un IPS < 0,90 sur au moins une cheville affirme le diagnostic d'AOMI."},{"t":"L'AOMI gauche est sévère","ok":true,"why":"Un IPS inférieur à 0,70 (ici 0,65) définit une AOMI sévère."},{"t":"Un IPS élevé à droite éliminerait formellement toute atteinte controlatérale","ok":false,"why":"Un IPS normal n'élimine pas une AOMI infraclinique ou débutante controlatérale."},{"t":"Il faut envisager une médiacalcose devant ce résultat","ok":false,"why":"La médiacalcose se traduit par un IPS anormalement élevé (> 1,40), non par un IPS abaissé."},{"t":"Cet IPS abaissé est aussi un marqueur de risque cardiovasculaire général","ok":true,"why":"Un IPS bas est associé à un risque accru d'événement coronarien ou cérébral, au-delà de son intérêt diagnostique local."}],"explanation":"Un IPS < 0,90 confirme l'AOMI ; ici 0,65 est même inférieur au seuil de sévérité de 0,70, ce qui doit être noté."},"reveal":"Le compte-rendu conclut à une AOMI gauche sévère (IPS 0,65) et une absence d'AOMI droite au repos.","src":"p. 171"},{"id":"225-case-01-s04","phase":1,"narrative":"M. Lefèvre demande des précisions sur le stade de sa maladie.","question":{"type":"QROC","question":"Quel stade de la classification de Leriche et Fontaine correspond à la situation clinique actuelle de M. Lefèvre ?","answer":"Stade II (claudication intermittente)","accept":["stade 2","II","claudication"],"keywords":["Leriche","Fontaine","claudication"],"explanation":"Le patient présente une claudication intermittente sans douleur de repos ni trouble trophique, correspondant au stade II de Leriche et Fontaine (catégorie Rutherford I à III selon la sévérité)."},"reveal":"Le patient est informé qu'il s'agit d'un stade II, avec un risque cardiovasculaire global à évaluer.","src":"p. 168-169"},{"id":"225-case-01-s05","phase":2,"narrative":"Le médecin souhaite préciser la localisation et la sévérité des lésions avant toute décision thérapeutique.","question":{"type":"QRM","stem":"Quel(s) examen(s) complémentaire(s) est/sont justifié(s) à ce stade ?","options":[{"t":"Échodoppler artériel des membres inférieurs","ok":true,"why":"C'est l'examen de 1re intention pour localiser et quantifier les sténoses."},{"t":"Angioscanner des membres inférieurs d'emblée","ok":false,"why":"Il n'est indiqué qu'en vue d'un projet de revascularisation, pas en routine diagnostique."},{"t":"Bilan des autres localisations athéromateuses (ECG, recherche de souffle carotidien)","ok":true,"why":"L'AOMI impose un bilan cardiovasculaire général du fait de la fréquence des atteintes associées."},{"t":"Artériographie systématique","ok":false,"why":"Elle est réservée aux procédures de revascularisation."},{"t":"Bilan lipidique et glycémique","ok":true,"why":"Le bilan des facteurs de risque cardiovasculaire fait partie de l'évaluation initiale."}],"explanation":"L'échodoppler artériel et le bilan des facteurs de risque et des autres localisations athéromateuses sont les examens pertinents à ce stade ; l'imagerie en coupe n'est utile qu'en cas de projet de revascularisation."},"reveal":"L'échodoppler confirme une sténose serrée de l'artère fémorale superficielle gauche ; le bilan ne retrouve pas d'autre localisation symptomatique.","src":"p. 172-175"},{"id":"225-case-01-s06","phase":2,"narrative":"Le bilan étiologique retrouve un tabagisme actif, une hypercholestérolémie et une pression artérielle à 148/92 mmHg.","question":{"type":"QRM","stem":"Quels facteurs de risque de l'AOMI sont présents chez ce patient ?","options":[{"t":"Le tabagisme","ok":true,"why":"C'est l'un des deux principaux facteurs de risque de l'AOMI, plus fréquent chez le sujet jeune."},{"t":"L'hypercholestérolémie","ok":true,"why":"Elle est fréquemment associée à l'AOMI."},{"t":"L'hypertension artérielle","ok":true,"why":"Elle est fréquemment associée à l'AOMI."},{"t":"Le diabète","ok":false,"why":"Aucun élément du dossier ne rapporte de diabète chez ce patient."},{"t":"L'âge du patient élimine tout risque supplémentaire de progression","ok":false,"why":"L'âge n'élimine rien ; ce n'est pas un facteur protecteur mentionné."}],"explanation":"Le tabagisme, l'hypercholestérolémie et l'HTA sont les facteurs de risque retrouvés chez ce patient ; le diabète n'est pas présent ici."},"reveal":"Un sevrage tabagique et une statine sont proposés en association au traitement antiplaquettaire.","src":"p. 168, 175"},{"id":"225-case-01-s07","phase":3,"narrative":"Le traitement de fond est mis en place.","question":{"type":"QRM","stem":"Quelles mesures thérapeutiques générales sont indiquées chez ce patient AOMI symptomatique ?","options":[{"t":"Antiplaquettaire (aspirine ou clopidogrel)","ok":true,"why":"Indiqué chez tout patient AOMI symptomatique."},{"t":"Statine avec objectif de LDL < 0,55 g/L","ok":true,"why":"Traitement systématique, avec réduction ≥ 50 % du LDL initial."},{"t":"Arrêt du tabac","ok":true,"why":"Mesure de fond indispensable à tout stade de la maladie."},{"t":"Anticoagulation curative systématique par AVK","ok":false,"why":"L'antithrombotique indiqué chez tout patient AOMI symptomatique est un antiplaquettaire (aspirine ou clopidogrel), pas un AVK."},{"t":"Objectif tensionnel PAS 120-129 / PAD 70-79 mmHg","ok":true,"why":"C'est la cible tensionnelle recommandée chez le patient AOMI."}],"explanation":"Le traitement de fond de l'AOMI symptomatique repose sur le contrôle des facteurs de risque (arrêt du tabac, cibles tensionnelles), une statine (LDL < 0,55 g/L) et un antiplaquettaire (aspirine ou clopidogrel), et non sur une anticoagulation par AVK."},"reveal":"M. Lefèvre débute aspirine, statine et un inhibiteur de l'enzyme de conversion, avec sevrage tabagique accompagné.","src":"p. 175"},{"id":"225-case-01-s08","phase":3,"narrative":"En complément du traitement médicamenteux, le médecin propose une prise en charge non pharmacologique.","question":{"type":"QROC","question":"Quelle mesure non médicamenteuse est le traitement de première ligne de la claudication non invalidante ?","answer":"La marche régulière, idéalement supervisée (réadaptation)","accept":["réadaptation à la marche","réentraînement à la marche","marche supervisée"],"keywords":["marche","supervisée","réadaptation"],"explanation":"La réadaptation à la marche, de préférence supervisée, associée à une éducation thérapeutique, est le traitement de première ligne de la claudication non invalidante."},"reveal":"Le patient est orienté vers un programme de réadaptation à la marche supervisée, avec un objectif de 30 à 45 minutes au moins 3 fois par semaine.","src":"p. 175-176"},{"id":"225-case-01-s09","phase":4,"narrative":"Six mois plus tard, malgré une observance correcte et l'arrêt du tabac, le périmètre de marche reste inférieur à 90 mètres et impacte fortement la vie quotidienne du patient.","question":{"type":"QRM","stem":"Que faut-il envisager à ce stade ?","options":[{"t":"Une revascularisation, du fait de l'échec du traitement médical bien conduit avec périmètre de marche < 100 m","ok":true,"why":"La revascularisation est discutée en cas de claudication sévère invalidante après échec du traitement médical bien mené."},{"t":"Un simple renforcement du traitement vasoactif sans autre exploration","ok":false,"why":"Le bénéfice des traitements vasoactifs est modeste et sans effet pronostique ; ce n'est pas la priorité devant cet échec."},{"t":"Une nouvelle imagerie en vue d'un projet de revascularisation (angioscanner ou angio-IRM)","ok":true,"why":"Ces examens sont indiqués lorsqu'une revascularisation est envisagée."},{"t":"L'arrêt de la statine puisque le LDL est désormais à l'objectif","ok":false,"why":"La statine doit être poursuivie au long cours indépendamment du résultat sur la claudication."},{"t":"Une amputation d'emblée","ok":false,"why":"L'amputation est le geste ultime, réservé à l'absence de toute possibilité de revascularisation."}],"explanation":"Après échec du traitement médical bien conduit avec un périmètre de marche sévèrement réduit, la revascularisation doit être discutée, précédée d'une imagerie dédiée."},"reveal":"Un angioscanner confirme une sténose serrée et courte de l'artère fémorale superficielle gauche, accessible à un traitement endovasculaire.","src":"p. 176"},{"id":"225-case-01-s10","phase":4,"narrative":"La sténose est courte et proximale.","question":{"type":"QRU","stem":"Quelle technique de revascularisation est la plus adaptée à cette lésion ?","options":[{"t":"Pontage fémoropoplité d'emblée","ok":false,"why":"La chirurgie est plutôt réservée aux lésions étendues, non aux lésions courtes et proximales."},{"t":"Angioplastie endovasculaire ± stent","ok":true,"why":"Les résultats de l'angioplastie sont d'autant plus favorables que les lésions sont courtes et proximales."},{"t":"Amputation transmétatarsienne","ok":false,"why":"Non indiquée : il ne s'agit pas d'une ischémie dépassée."},{"t":"Aponévrotomie de décompression","ok":false,"why":"Ce geste concerne le syndrome des loges de l'ischémie aiguë, sans rapport avec cette situation."},{"t":"Sympathectomie lombaire","ok":false,"why":"Cette technique n'est pas mentionnée comme option de revascularisation dans ce contexte."}],"explanation":"Pour une lésion courte et proximale, l'angioplastie endovasculaire (± stent) est privilégiée, suivie d'une bithérapie antiplaquettaire de 1 à 6 mois."},"reveal":"Le patient bénéficie d'une angioplastie avec pose de stent, suivie d'une bithérapie antiplaquettaire pendant 3 mois et d'une surveillance écho-Doppler.","src":"p. 176"},{"id":"225-case-01-s11","phase":5,"narrative":"Deux ans plus tard, M. Lefèvre, dont le suivi cardiologique a révélé une fibrillation atriale méconnue, se présente aux urgences pour une douleur brutale et intense du membre inférieur droit, avec un pied froid et livide, sans trouble sensitif ni moteur.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir immédiate ?","options":[{"t":"Débuter une anticoagulation par héparine non fractionnée après prélèvement du bilan de coagulation","ok":true,"why":"L'anticoagulation est débutée dès le diagnostic d'ischémie aiguë, après le prélèvement du bilan de coagulation."},{"t":"Attendre le résultat des D-dimères avant toute imagerie","ok":false,"why":"Piège classique : aucune exploration ne doit retarder la prise en charge d'une ischémie aiguë, a fortiori l'attente d'un dosage biologique non spécifique de ce contexte."},{"t":"Évoquer en priorité une origine embolique devant le contexte de fibrillation atriale","ok":true,"why":"La fibrillation atriale est la principale cause cardiaque d'embolie artérielle des membres."},{"t":"Réaliser d'emblée une amputation puisque le tableau est douloureux","ok":false,"why":"L'amputation n'est envisagée qu'en cas d'ischémie dépassée (grade III) ou d'échec de revascularisation, non à ce stade."},{"t":"Alerter l'équipe chirurgicale vasculaire sans délai","ok":true,"why":"Le pronostic dépend de la rapidité de la prise en charge d'une ischémie aiguë."}],"explanation":"Devant ce tableau typique d'ischémie aiguë sans déficit neurologique (grade I), le traitement médical est débuté sans délai et l'équipe chirurgicale alertée, sans attendre de biologie non contributive."},"reveal":"L'échodoppler réalisé sans perte de temps confirme une occlusion fémorale droite ; une embolectomie à la sonde de Fogarty est réalisée en urgence, orientée par le contexte de fibrillation atriale.","src":"p. 179-182"},{"id":"225-case-01-s12","phase":5,"narrative":"La revascularisation est un succès ; le patient est revu en consultation de suivi à distance de l'épisode aigu.","question":{"type":"QROC","question":"Quel traitement étiologique au long cours doit être instauré du fait du contexte de fibrillation atriale ?","answer":"Une anticoagulation au long cours","accept":["anticoagulant au long cours","AOD ou AVK au long cours"],"keywords":["anticoagulation","long cours","fibrillation"],"explanation":"En cas d'ischémie aiguë d'origine embolique liée à une fibrillation atriale, le traitement étiologique à distance repose sur une anticoagulation au long cours."},"reveal":"Une anticoagulation au long cours est instaurée ; le suivi de l'AOMI et le contrôle des facteurs de risque cardiovasculaire sont poursuivis, le pronostic restant grave à long terme.","src":"p. 183"}]},{"id":"225-case-02","title":"Mme Vasseur, 72 ans, masse battante découverte à l'examen","rank":"A","summary":"Anévrisme de l'aorte abdominale de découverte fortuite, du dépistage à la surveillance, puis à la décision d'intervention.","difficulty":2,"timeline":["Découverte fortuite","Confirmation diagnostique","Surveillance initiale","Progression du diamètre","Décision thérapeutique","Suivi post-opératoire"],"steps":[{"id":"225-case-02-s01","phase":0,"narrative":"Mme Vasseur, 72 ans, hypertendue et ancienne fumeuse, consulte son médecin traitant pour le renouvellement de son traitement antihypertenseur. À la palpation abdominale systématique, celui-ci perçoit une masse battante et expansive péri-ombilicale.","question":{"type":"QRM","stem":"Que faut-il suspecter et rechercher devant cette découverte ?","options":[{"t":"Un anévrisme de l'aorte abdominale","ok":true,"why":"Une masse battante et expansive de l'abdomen évoque en premier lieu un anévrisme de l'aorte."},{"t":"Un souffle abdominal à l'auscultation","ok":true,"why":"Un souffle peut accompagner la masse anévrismale et doit être recherché."},{"t":"Des pouls périphériques et une recherche d'anévrisme poplité","ok":true,"why":"Les anévrismes poplités sont fréquemment associés à l'AAA et doivent être recherchés systématiquement."},{"t":"Une origine exclusivement tumorale, sans autre exploration nécessaire","ok":false,"why":"Le caractère battant et expansif oriente avant tout vers une origine vasculaire, à explorer avant d'évoquer une autre cause."},{"t":"Les autres facteurs de risque cardiovasculaire de la patiente","ok":true,"why":"L'AAA est le plus souvent associé à un terrain athéromateux qu'il convient de caractériser."}],"explanation":"Une masse battante et expansive péri-ombilicale évoque en premier lieu un AAA ; l'examen doit rechercher un souffle, une localisation poplitée associée et les facteurs de risque athéromateux."},"reveal":"Le médecin décide de compléter par une imagerie abdominale.","src":"p. 183-184"},{"id":"225-case-02-s02","phase":0,"narrative":"Le médecin doit choisir l'examen de dépistage le plus adapté.","question":{"type":"QRU","stem":"Quel examen de première intention prescrire ?","options":[{"t":"Scanner abdominopelvien injecté","ok":false,"why":"C'est l'examen préthérapeutique de référence, pas l'examen de dépistage de première intention."},{"t":"Échographie abdominale","ok":true,"why":"L'échographie abdominale est l'examen de dépistage, de mesure et de surveillance de l'AAA."},{"t":"Artériographie","ok":false,"why":"Elle n'est pas utile au diagnostic d'AAA, car elle sous-estime la taille en cas de thrombus mural."},{"t":"IRM abdominale","ok":false,"why":"Elle est réservée comme alternative en cas de contre-indication au scanner, pas en dépistage de première intention."},{"t":"Angioscanner des membres inférieurs","ok":false,"why":"Cet examen explore les artères des membres inférieurs, non l'aorte abdominale."}],"explanation":"L'échographie abdominale est l'examen de dépistage recommandé, non invasif, permettant de mesurer le diamètre et d'assurer le suivi."},"reveal":"L'échographie confirme un anévrisme de l'aorte abdominale sous-rénale mesuré à 42 mm de diamètre.","src":"p. 184"},{"id":"225-case-02-s03","phase":1,"narrative":"Le diagnostic d'AAA est confirmé à 42 mm.","question":{"type":"QRM","stem":"Concernant l'étiologie de cet anévrisme, quelles propositions sont exactes ?","options":[{"t":"Dans 80 à 90 % des cas, l'AAA survient sur un terrain athéromateux","ok":true,"why":"C'est la cause prédominante de l'AAA, souvent associée à une AOMI ou une atteinte coronarienne."},{"t":"Une maladie du tissu élastique (Marfan, Ehlers-Danlos, Loeys-Dietz) peut être en cause dans les formes familiales","ok":true,"why":"Ces maladies génétiques sont citées parmi les étiologies des formes non athéromateuses."},{"t":"Une aortite (Takayasu, Horton) peut être responsable d'un AAA","ok":true,"why":"Les aortites sont une étiologie possible, plus rare que l'origine athéromateuse."},{"t":"Le diabète est le principal facteur de risque d'AAA","ok":false,"why":"Les diabétiques sont au contraire décrits comme moins souvent atteints d'AAA."},{"t":"Les antécédents familiaux d'anévrisme ne jouent aucun rôle","ok":false,"why":"Les antécédents familiaux d'anévrisme sont au contraire un facteur de risque reconnu, en dehors de l'âge et du tabac."}],"explanation":"L'athérome est la cause prédominante de l'AAA (80-90 %), avec des formes familiales (maladies du tissu élastique) ou secondaires à une aortite ; le diabète n'est pas un facteur de risque, contrairement au tabac et aux antécédents familiaux."},"reveal":"Le bilan ne retrouve pas de contexte familial ni de signe d'aortite ; l'origine est jugée athéromateuse.","src":"p. 184"},{"id":"225-case-02-s04","phase":1,"narrative":"Devant ce diagnostic, le médecin complète le bilan de localisation.","question":{"type":"QROC","question":"Quelles autres localisations anévrismales faut-il systématiquement rechercher devant un AAA ?","answer":"Les localisations poplitées et iliaques","accept":["anévrismes poplités","anévrismes iliaques","poplité et iliaque"],"keywords":["poplité","iliaque"],"explanation":"L'échographie de dépistage recherche également les localisations poplitées et iliaques, fréquemment associées à l'AAA."},"reveal":"Aucune localisation poplitée ou iliaque associée n'est retrouvée chez cette patiente.","src":"p. 184-187"},{"id":"225-case-02-s05","phase":2,"narrative":"Le diamètre de 42 mm ne justifie pas d'intervention immédiate.","question":{"type":"QRM","stem":"Quelles sont les modalités de prise en charge à ce stade ?","options":[{"t":"Surveillance échographique répétée","ok":true,"why":"Les anévrismes de petite taille sont surveillés par des échographies répétées."},{"t":"Contrôle strict des facteurs de risque cardiovasculaire, notamment arrêt du tabac","ok":true,"why":"Le contrôle des facteurs de risque est indispensable pendant toute la période de suivi, la progression étant plus rapide en cas de tabagisme persistant."},{"t":"Intervention chirurgicale programmée immédiate","ok":false,"why":"Le seuil d'intervention à froid se situe à 50-55 mm ; 42 mm ne justifie pas d'intervention immédiate."},{"t":"Antibioprophylaxie systématique en l'absence de tout geste invasif","ok":false,"why":"L'antibioprophylaxie ne concerne que les gestes à risque bactérien chez un porteur de prothèse, non la simple surveillance d'un anévrisme natif."},{"t":"Recherche et prise en charge du risque cardiovasculaire global","ok":true,"why":"Le porteur d'AAA a un risque de décès cardiovasculaire bien supérieur à celui de rupture, justifiant une prise en charge globale."}],"explanation":"À 42 mm, la prise en charge repose sur la surveillance échographique et le contrôle rigoureux des facteurs de risque cardiovasculaire, la patiente étant à haut risque de complication cardiovasculaire globale."},"reveal":"Une surveillance échographique annuelle est programmée et l'arrêt du tabac est fortement encouragé.","src":"p. 185-186"},{"id":"225-case-02-s06","phase":2,"narrative":"La patiente peine à arrêter le tabac malgré les conseils reçus.","question":{"type":"OPEN","prompt":"Expliquez à la patiente, en quelques phrases, pourquoi l'arrêt du tabac est particulièrement important dans sa situation.","rubric":[{"point":"Le tabagisme actif accélère la croissance de l'anévrisme (environ 3 fois plus rapide)","weight":2},{"point":"Le tabac est un facteur de risque majeur de progression et de complication cardiovasculaire","weight":1},{"point":"Le risque principal chez le porteur d'AAA reste le risque cardiovasculaire global, pas seulement la rupture","weight":1}],"model":"La poursuite du tabagisme accélère nettement la croissance de l'anévrisme, environ trois fois plus vite que chez un non-fumeur. Au-delà du risque local, le tabac est aussi le principal facteur de risque cardiovasculaire général : chez une porteuse d'AAA, le risque de décès par complication cardiovasculaire (infarctus, AVC) est bien plus élevé que celui de rupture de l'anévrisme lui-même. L'arrêt du tabac est donc une priorité, autant pour l'anévrisme que pour le pronostic global."},"reveal":"Une consultation d'aide au sevrage tabagique est organisée.","src":"p. 186"},{"id":"225-case-02-s07","phase":3,"narrative":"Deux ans plus tard, l'échographie de contrôle retrouve un anévrisme mesurant désormais 48 mm de diamètre.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir devant cette progression ?","options":[{"t":"Renforcer la surveillance échographique, à un rythme semestriel","ok":true,"why":"Au-delà de 45 mm, la surveillance échographique est renforcée, tous les 6 mois."},{"t":"Programmer une intervention chirurgicale immédiate","ok":false,"why":"Le seuil habituel d'intervention (50-55 mm) n'est pas encore atteint."},{"t":"Renforcer le contrôle des facteurs de risque cardiovasculaire","ok":true,"why":"Le contrôle des facteurs de risque reste indispensable pendant toute la surveillance."},{"t":"Arrêter toute surveillance puisque le diamètre reste inférieur à 50 mm","ok":false,"why":"Au contraire, la surveillance doit être renforcée à l'approche du seuil d'intervention."},{"t":"Envisager d'emblée une endoprothèse quelle que soit l'anatomie","ok":false,"why":"Une intervention n'est envisagée qu'au-delà du seuil de 50-55 mm, sous réserve d'une anatomie et d'un terrain adaptés."}],"explanation":"Entre 45 et 50 mm, la surveillance échographique est renforcée (tous les 6 mois) et le contrôle des facteurs de risque poursuivi, sans indication opératoire immédiate."},"reveal":"Le rythme de surveillance est porté à 6 mois.","src":"p. 185-186"},{"id":"225-case-02-s08","phase":3,"narrative":"Un an après, l'échographie retrouve un anévrisme à 56 mm de diamètre, sans douleur ni signe de complication.","question":{"type":"QRM","stem":"Que faut-il envisager à ce stade ?","options":[{"t":"Une intervention programmée « à froid »","ok":true,"why":"Au-delà de 50-55 mm, le risque de rupture devient important et une intervention programmée est indiquée."},{"t":"Un scanner abdominopelvien injecté pour préciser le diamètre et l'anatomie avant l'intervention","ok":true,"why":"C'est l'examen préthérapeutique de référence, précisant diamètre et anatomie en vue de l'intervention."},{"t":"Une simple surveillance échographique supplémentaire sans projet opératoire","ok":false,"why":"Le seuil d'intervention est atteint ; la simple surveillance n'est plus suffisante."},{"t":"Une artériographie pour mesurer précisément le diamètre de l'anévrisme","ok":false,"why":"L'artériographie n'est pas utile pour mesurer un AAA car elle sous-estime la taille en présence de thrombus mural."},{"t":"Une amputation de principe","ok":false,"why":"Ce geste n'a aucun rapport avec la prise en charge d'un anévrisme de l'aorte abdominale."}],"explanation":"Au-delà de 50-55 mm, une intervention à froid est programmée, précédée d'un scanner abdominopelvien injecté, examen préthérapeutique de référence."},"reveal":"Le scanner confirme un anévrisme de 56 mm, sous-rénal, avec une anatomie favorable à un traitement endovasculaire.","src":"p. 185-186"},{"id":"225-case-02-s09","phase":4,"narrative":"Compte tenu de son âge et de comorbidités modérées, l'équipe discute la meilleure technique.","question":{"type":"QRU","stem":"Quel traitement privilégier chez cette patiente, compte tenu d'une anatomie favorable ?","options":[{"t":"Chirurgie conventionnelle à ciel ouvert uniquement","ok":false,"why":"Ce n'est pas la seule option ; le traitement endovasculaire est envisageable si l'anatomie est favorable."},{"t":"Traitement endovasculaire par endoprothèse","ok":true,"why":"Moins invasif, il est proposé lorsque l'anatomie est favorable, y compris chez des patients à risque non nécessairement élevé après information éclairée."},{"t":"Abstention thérapeutique définitive","ok":false,"why":"Au-delà du seuil de 50-55 mm, une intervention est indiquée, pas l'abstention."},{"t":"Simple surveillance rapprochée sans intervention","ok":false,"why":"Le seuil d'intervention étant dépassé, la surveillance seule n'est plus adaptée."},{"t":"Embolectomie à la sonde de Fogarty","ok":false,"why":"Ce geste concerne la revascularisation d'une ischémie aiguë de membre, non le traitement d'un AAA."}],"explanation":"Avec une anatomie favorable, le traitement endovasculaire par endoprothèse, moins invasif, est une option de choix après information éclairée de la patiente."},"reveal":"Après information de la patiente sur les bénéfices et la nécessité d'une surveillance itérative, elle opte pour le traitement endovasculaire.","src":"p. 186"},{"id":"225-case-02-s10","phase":4,"narrative":"Avant l'intervention, la patiente demande quelles complications sont spécifiquement surveillées après la pose d'une endoprothèse.","question":{"type":"QROC","question":"Quelle complication spécifique du traitement endovasculaire doit être recherchée par la surveillance itérative ?","answer":"Une endofuite","accept":["endofuite","fuite péri-prothétique"],"keywords":["endofuite"],"explanation":"Les endofuites, flux maintenant une pression dans le sac anévrismal, peuvent faire progresser voire rompre l'anévrisme et justifient une surveillance itérative par scanner ou échographie de contraste."},"reveal":"L'endoprothèse est posée sans complication immédiate.","src":"p. 186"},{"id":"225-case-02-s11","phase":5,"narrative":"La patiente est revue en consultation de suivi post-opératoire.","question":{"type":"QRM","stem":"Quelles sont les modalités de surveillance à mettre en place ?","options":[{"t":"Surveillance au long cours par scanner ou échographie de contraste à la recherche d'endofuites","ok":true,"why":"C'est la surveillance spécifique recommandée après pose d'une endoprothèse."},{"t":"Antibioprophylaxie lors de tout geste à risque bactérien du fait de la prothèse","ok":true,"why":"Le risque infectieux de la prothèse vasculaire justifie une antibioprophylaxie lors des gestes à risque bactérien."},{"t":"Poursuite du contrôle des facteurs de risque cardiovasculaire","ok":true,"why":"Le risque cardiovasculaire persiste même après un traitement réussi de l'anévrisme."},{"t":"Arrêt de toute surveillance dès la sortie d'hospitalisation","ok":false,"why":"Une surveillance itérative au long cours est au contraire indispensable après endoprothèse."},{"t":"Reprise du tabac désormais sans conséquence","ok":false,"why":"Le contrôle des facteurs de risque, notamment le tabac, reste essentiel après traitement de l'AAA."}],"explanation":"Après endoprothèse, la surveillance associe imagerie itérative (endofuites), antibioprophylaxie lors des gestes à risque bactérien et poursuite du contrôle des facteurs de risque cardiovasculaire."},"reveal":"Un scanner de contrôle à 1 mois ne retrouve pas d'endofuite.","src":"p. 186"},{"id":"225-case-02-s12","phase":5,"narrative":"Un an après l'intervention, la patiente se porte bien et demande si elle est désormais guérie.","question":{"type":"OPEN","prompt":"Expliquez à la patiente pourquoi un suivi cardiovasculaire reste nécessaire malgré le succès du traitement de son anévrisme.","rubric":[{"point":"Le traitement de l'anévrisme ne traite pas la maladie athéromateuse sous-jacente","weight":2},{"point":"Le porteur d'AAA reste à haut risque cardiovasculaire (coronarien, cérébral)","weight":1},{"point":"Nécessité de poursuivre la surveillance de l'endoprothèse et le contrôle des facteurs de risque","weight":1}],"model":"Le traitement de l'anévrisme a supprimé le risque local de rupture, mais il ne traite pas la maladie athéromateuse qui en est la cause. Un patient porteur d'AAA reste exposé à un risque élevé de complication cardiovasculaire, coronarienne ou cérébrale, plus important que le risque local. Il faut donc poursuivre le contrôle des facteurs de risque et la surveillance régulière de l'endoprothèse au long cours."},"reveal":"Le suivi cardiovasculaire et la surveillance de l'endoprothèse sont poursuivis annuellement.","src":"p. 186"}]},{"id":"225-case-03","title":"M. Tanguy, 70 ans, douleurs abdominales après les repas","rank":"A","summary":"Ischémie mésentérique chronique méconnue se compliquant d'un épisode d'ischémie mésentérique aiguë sur probable embolie.","difficulty":3,"timeline":["Consultation pour douleurs abdominales","Bilan diagnostique","Diagnostic et traitement","Complication aiguë","Prise en charge en urgence"],"steps":[{"id":"225-case-03-s01","phase":0,"narrative":"M. Tanguy, 70 ans, polyathéromateux (AOMI connue, tabagisme), consulte pour des douleurs abdominales apparaissant systématiquement 20 à 30 minutes après les repas, associées à un amaigrissement de 6 kg en quelques mois.","question":{"type":"QRM","stem":"Quels éléments orientent vers une ischémie mésentérique chronique ?","options":[{"t":"Le caractère postprandial systématique des douleurs","ok":true,"why":"C'est la présentation typique de l'angor digestif de l'ischémie mésentérique chronique."},{"t":"Le terrain polyathéromateux du patient","ok":true,"why":"Les sténoses digestives partagent le même terrain athéromateux que l'AOMI."},{"t":"L'amaigrissement lié à la restriction alimentaire","ok":true,"why":"La crainte de déclencher la douleur conduit à une restriction alimentaire et à un amaigrissement."},{"t":"La présence de vomissements et diarrhées explosifs depuis plusieurs heures","ok":false,"why":"Ce tableau évoque plutôt une forme aiguë, non la forme chronique progressive décrite ici."},{"t":"Une douleur exclusivement nocturne et positionnelle","ok":false,"why":"Ce n'est pas la présentation typique de l'angor digestif, qui est déclenché par le repas."}],"explanation":"Le caractère postprandial des douleurs, le terrain athéromateux et l'amaigrissement par restriction alimentaire orientent vers une ischémie mésentérique chronique (angor digestif)."},"reveal":"L'examen recherche un souffle abdominal.","src":"p. 166-167"},{"id":"225-case-03-s02","phase":0,"narrative":"L'auscultation abdominale retrouve un souffle épigastrique discret.","question":{"type":"QROC","question":"Quel terme désigne le tableau clinique de douleurs abdominales postprandiales par sténose artérielle digestive ?","answer":"L'angor digestif","accept":["angine digestive"],"keywords":["angor","digestif"],"explanation":"Ce tableau douloureux postprandial lié à une sténose artérielle viscérale est appelé angor digestif."},"reveal":"Le médecin prescrit une exploration vasculaire digestive.","src":"p. 166"},{"id":"225-case-03-s03","phase":1,"narrative":"Le médecin doit choisir l'examen de première intention.","question":{"type":"QRU","stem":"Quel examen prescrire en première intention pour explorer une suspicion de sténose artérielle digestive ?","options":[{"t":"Échodoppler des artères digestives","ok":true,"why":"Il fait partie des examens de première intention pour diagnostiquer une sténose artérielle viscérale, avec l'angioscanner et l'angio-IRM."},{"t":"Artériographie digestive","ok":false,"why":"Elle n'est réalisée que dans le cadre d'un geste de revascularisation par voie endovasculaire."},{"t":"Coloscopie","ok":false,"why":"Non mentionnée comme examen de la sténose artérielle digestive dans ce chapitre."},{"t":"Mesure de l'index de pression systolique","ok":false,"why":"L'IPS rapporte la pression systolique de cheville à celle du bras : il explore les artères des membres inférieurs, pas les artères digestives."},{"t":"Électrocardiogramme","ok":false,"why":"Il ne diagnostique pas une sténose artérielle digestive, qui repose sur l'échodoppler, l'angioscanner ou l'angio-IRM."}],"explanation":"L'échodoppler des artères digestives (ou l'angioscanner/angio-IRM) est l'examen de première intention pour diagnostiquer une sténose artérielle viscérale."},"reveal":"L'échodoppler des artères digestives retrouve une sténose serrée du tronc cœliaque.","src":"p. 166, 170"},{"id":"225-case-03-s04","phase":1,"narrative":"Le diagnostic d'ischémie mésentérique chronique est retenu.","question":{"type":"QRM","stem":"Quelles sont les modalités de traitement adaptées à cette situation ?","options":[{"t":"Revascularisation, de préférence par voie endovasculaire","ok":true,"why":"Le traitement de l'ischémie mésentérique chronique repose sur la revascularisation, préférentiellement endovasculaire."},{"t":"L'artériographie n'est réalisée qu'au cours du geste de revascularisation endovasculaire","ok":true,"why":"Elle n'a pas de place en simple exploration diagnostique."},{"t":"Anticoagulation curative au long cours comme traitement de référence","ok":false,"why":"Le traitement de référence est la revascularisation, pas l'anticoagulation."},{"t":"Résection intestinale systématique","ok":false,"why":"La résection des segments nécrosés concerne la forme aiguë, pas la forme chronique."},{"t":"Abstention thérapeutique malgré l'angor digestif","ok":false,"why":"Une ischémie mésentérique chronique symptomatique relève d'une revascularisation."}],"explanation":"Le traitement de l'ischémie mésentérique chronique repose sur la revascularisation, de préférence endovasculaire ; l'artériographie n'est réalisée qu'au cours du geste endovasculaire. La résection intestinale concerne la forme aiguë."},"reveal":"M. Tanguy bénéficie d'une revascularisation endovasculaire du tronc cœliaque ; ses douleurs postprandiales disparaissent.","src":"p. 166, 187"},{"id":"225-case-03-s05","phase":2,"narrative":"Six mois plus tard, le patient va bien, sans récidive de douleur postprandiale.","question":{"type":"QROC","question":"Quel examen n'est réalisé, dans la prise en charge de l'ischémie mésentérique, que lors d'un geste de revascularisation endovasculaire ?","answer":"L'artériographie","accept":["artériographie digestive"],"keywords":["artériographie"],"explanation":"L'artériographie n'est réalisée que lors d'une procédure de revascularisation par voie endovasculaire, jamais en simple exploration diagnostique."},"reveal":"Le suivi se poursuit sans complication.","src":"p. 166"},{"id":"225-case-03-s06","phase":2,"narrative":"Lors d'une consultation de suivi, le cardiologue découvre une fibrillation atriale paroxystique méconnue.","question":{"type":"QRM","stem":"Quelles sont les conséquences possibles de cette découverte chez ce patient ?","options":[{"t":"Un risque accru d'embolie artérielle, notamment digestive ou des membres","ok":true,"why":"La fibrillation atriale est une cause classique d'embolie sur artères saines ou déjà pathologiques."},{"t":"La nécessité de discuter une anticoagulation au long cours","ok":true,"why":"La fibrillation atriale justifie la discussion d'un traitement anticoagulant préventif des complications emboliques."},{"t":"Une contre-indication définitive à tout traitement antiplaquettaire","ok":false,"why":"Il n'est pas mentionné de contre-indication de ce type ; c'est plutôt la question de l'association ou du remplacement qui se pose."},{"t":"Une disparition du risque d'ischémie mésentérique aiguë","ok":false,"why":"Au contraire, la fibrillation atriale majore le risque d'ischémie mésentérique aiguë d'origine embolique."},{"t":"L'absence de toute conséquence pratique","ok":false,"why":"La découverte d'une fibrillation atriale a des implications thérapeutiques et de surveillance importantes."}],"explanation":"La fibrillation atriale expose à un risque accru d'embolie artérielle (dont digestive) et impose de discuter une anticoagulation au long cours."},"reveal":"Une anticoagulation est discutée mais différée par le patient, qui refuse initialement le traitement.","src":"p. 167, 181"},{"id":"225-case-03-s07","phase":3,"narrative":"Quelques semaines plus tard, M. Tanguy consulte aux urgences pour une douleur abdominale aiguë intense apparue brutalement, avec vomissements et diarrhée, sans grande anomalie à l'examen abdominal.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir la plus appropriée ?","options":[{"t":"Suspecter une ischémie mésentérique aiguë devant ce contexte emboligène et cette triade clinique","ok":true,"why":"La triade douleur abdominale aiguë pauvre en signes physiques, vidange digestive accélérée et contexte emboligène (fibrillation atriale) est évocatrice d'ischémie mésentérique aiguë."},{"t":"Différer l'imagerie puisque l'examen abdominal est peu parlant","ok":false,"why":"Piège : la douleur aiguë pauvre en signes physiques fait justement partie de la triade ; c'est une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge."},{"t":"Demander en urgence un angioscanner abdominal","ok":true,"why":"Le diagnostic d'ischémie mésentérique aiguë est confirmé par l'angioscanner."},{"t":"Rassurer le patient et le renvoyer à domicile avec des antalgiques simples","ok":false,"why":"Ce tableau chez un patient à risque emboligène est une urgence vitale potentielle, à ne pas banaliser."},{"t":"Rechercher des arguments emboligènes complémentaires (auscultation cardiaque, ECG)","ok":true,"why":"Le bilan étiologique en contexte emboligène potentiel fait partie de la prise en charge initiale."}],"explanation":"Devant cette triade évocatrice chez un patient en fibrillation atriale, il faut suspecter une ischémie mésentérique aiguë, demander en urgence un angioscanner qui confirme le diagnostic, et rechercher des arguments emboligènes."},"reveal":"Le patient est immédiatement adressé pour un angioscanner abdominal en urgence.","src":"p. 167, 187"},{"id":"225-case-03-s08","phase":3,"narrative":"L'angioscanner doit être interprété.","question":{"type":"QRU","stem":"Quel examen confirme le diagnostic d'ischémie mésentérique aiguë ?","options":[{"t":"L'angioscanner abdominal","ok":true,"why":"C'est l'examen qui confirme le diagnostic."},{"t":"L'échodoppler des artères digestives","ok":false,"why":"Il sert au diagnostic de la sténose de l'ischémie mésentérique chronique ; la forme aiguë est confirmée par l'angioscanner."},{"t":"L'échocardiographie transthoracique","ok":false,"why":"Elle recherche une source cardiaque d'embolie mais ne confirme pas l'occlusion artérielle digestive."},{"t":"La coloscopie","ok":false,"why":"Elle ne confirme pas une occlusion artérielle digestive."},{"t":"L'artériographie diagnostique en première intention","ok":false,"why":"L'artériographie n'est pas l'examen diagnostique de première intention."}],"explanation":"L'ischémie mésentérique aiguë est une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge ; le diagnostic est confirmé par l'angioscanner."},"reveal":"L'angioscanner confirme une occlusion embolique de l'artère mésentérique supérieure.","src":"p. 166-167, 182, 187"},{"id":"225-case-03-s09","phase":4,"narrative":"Le chirurgien digestif est immédiatement contacté.","question":{"type":"QRM","stem":"Quels éléments composent la prise en charge de cette ischémie mésentérique aiguë ?","options":[{"t":"Résection des segments intestinaux nécrosés","ok":true,"why":"C'est la base du traitement en cas de nécrose digestive constituée."},{"t":"Geste de revascularisation associé, par voie endovasculaire ou chirurgicale","ok":true,"why":"Le traitement associe à la résection des segments nécrosés une revascularisation, chirurgicale ou endovasculaire."},{"t":"Anticoagulation au long cours à discuter à distance, du fait de la fibrillation atriale","ok":true,"why":"À plus long terme, le traitement étiologique d'une cause embolique est à envisager, par exemple une anticoagulation au long cours en cas de fibrillation atriale."},{"t":"Surveillance simple sans aucun geste, la vidange digestive étant rassurante","ok":false,"why":"Le tableau confirmé par l'angioscanner impose un geste urgent (résection et revascularisation), non une simple surveillance."},{"t":"Antibiothérapie seule, sans geste chirurgical","ok":false,"why":"Le traitement de référence associe résection et revascularisation, pas une antibiothérapie isolée."}],"explanation":"La prise en charge associe résection des segments nécrosés et revascularisation en urgence, puis un traitement étiologique au long cours (anticoagulation devant la fibrillation atriale)."},"reveal":"Le patient est opéré en urgence : résection d'un segment grêle nécrosé et revascularisation par voie chirurgicale.","src":"p. 167, 183, 187"},{"id":"225-case-03-s11","phase":4,"narrative":"Avant sa sortie, le patient s'interroge sur la suite de sa prise en charge au long cours.","question":{"type":"OPEN","prompt":"Résumez les grands axes du traitement au long cours à mettre en place chez ce patient après cet épisode d'ischémie mésentérique aiguë d'origine embolique.","rubric":[{"point":"Anticoagulation au long cours du fait de la fibrillation atriale, cause probable de l'embolie","weight":2},{"point":"Poursuite du contrôle des facteurs de risque cardiovasculaire (tabac, etc.)","weight":1}],"model":"Le traitement étiologique au long cours repose avant tout sur une anticoagulation, la fibrillation atriale étant la cause probable de l'embolie mésentérique. Le contrôle des facteurs de risque cardiovasculaire, notamment un sevrage tabagique complet, doit être poursuivi compte tenu du terrain polyathéromateux."},"reveal":"Une anticoagulation au long cours est finalement acceptée par le patient, associée à un suivi cardiovasculaire régulier.","src":"p. 167, 183"}]},{"id":"225-case-51","title":"M. Garnier, 71 ans, douleur lombaire brutale","rank":"A","summary":"Anévrisme de l'aorte abdominale fissuré chez un patient à haut risque, du diagnostic en urgence au traitement endovasculaire, au suivi et à la recherche des autres localisations.","difficulty":2,"timeline":["Accueil aux urgences","Confirmation diagnostique","Histoire naturelle","Traitement en urgence","Suivi post-opératoire","Autres localisations","Prévention et dépistage familial"],"steps":[{"phase":0,"narrative":"M. Garnier, 71 ans, fumeur actif, coronarien et insuffisant respiratoire chronique sévère, est amené aux urgences pour une douleur lombaire gauche brutale et intense. PA 105/65 mmHg, FC 102/min. On palpe une masse para-ombilicale battante et expansive. Il se savait porteur d'un « anévrisme de l'aorte » dont il avait interrompu la surveillance.","question":{"type":"QRU","stem":"Quel diagnostic évoquez-vous en priorité ?","options":[{"t":"Fissuration d'un anévrisme de l'aorte abdominale","ok":true,"why":"Douleur abdominale ou lombaire chez un porteur d'AAA (masse battante et expansive) : fissuration/rupture, urgence vitale."},{"t":"Colique néphrétique","ok":false,"why":"La masse battante et expansive chez un porteur d'AAA impose d'évoquer d'abord une fissuration."},{"t":"Ischémie mésentérique chronique","ok":false,"why":"Elle donne des douleurs postprandiales, non une douleur lombaire brutale."},{"t":"Lombosciatique commune","ok":false,"why":"Ne rend pas compte de la masse battante ni du contexte."},{"t":"Syndrome de Leriche","ok":false,"why":"Il associe claudication fessière et troubles de l'érection."}],"explanation":"La forme symptomatique d'un AAA est souvent révélée par une fissuration/rupture : douleur abdominale ou lombaire ± choc hémorragique, urgence vitale."},"reveal":"L'hémodynamique reste stable à ce stade, sans signe de choc.","src":"p. 183-185","id":"225-case-51-s01"},{"phase":1,"narrative":"Le patient reste hémodynamiquement stable.","question":{"type":"QRU","stem":"Quel examen réalisez-vous pour confirmer le diagnostic et préparer le traitement ?","options":[{"t":"Scanner abdominopelvien injecté","ok":true,"why":"Il confirme le diagnostic, précise l'anatomie de l'anévrisme et constitue l'examen préthérapeutique de référence."},{"t":"Artériographie aortique","ok":false,"why":"Elle ne visualise que la lumière circulante et sous-estime la taille en cas de thrombus mural."},{"t":"IRM abdominale en 1re intention","ok":false,"why":"L'IRM est une alternative en cas de contre-indication au scanner."},{"t":"Échographie abdominale","ok":false,"why":"Elle sert au dépistage, à la mesure du diamètre et au suivi de l'AAA ; le diagnostic de fissuration et le bilan préthérapeutique reposent sur le scanner injecté."},{"t":"Transfert au bloc sans aucune imagerie","ok":false,"why":"Le diagnostic de fissuration ou de rupture doit être confirmé par le scanner avant le traitement ; même chez le patient en choc, seule une imagerie autre que ce scanner est à proscrire."}],"explanation":"Devant une suspicion de fissuration d'AAA, le scanner abdominopelvien injecté confirme le diagnostic et sert de bilan préthérapeutique de référence ; chez un patient en choc hémorragique, aucune imagerie autre que ce scanner ne doit retarder l'intervention."},"reveal":"Le scanner montre un AAA sous-rénal de 64 mm avec un hématome rétropéritonéal : AAA fissuré.","src":"p. 184-186, 188","id":"225-case-51-s02"},{"phase":2,"narrative":"Son épouse demande si ce risque était prévisible : l'anévrisme mesurait 46 mm il y a 5 ans.","question":{"type":"QRM","stem":"Concernant le risque de rupture d'un AAA, quelles propositions sont exactes ?","options":[{"t":"Il est d'environ 15 %/an au-delà de 60 mm.","ok":true,"why":"Chiffre cité."},{"t":"Il est d'environ 3 %/an entre 50 et 59 mm.","ok":true,"why":"Chiffre cité."},{"t":"Il est d'environ 0,4 %/an en dessous de 40 mm.","ok":true,"why":"Chiffre cité."},{"t":"À diamètre égal, il est plus faible chez la femme.","ok":false,"why":"Il est environ 4 fois plus élevé chez la femme à diamètre égal."},{"t":"Le diamètre est le principal facteur prédictif du risque de rupture.","ok":true,"why":"Le texte le précise."}],"explanation":"Le diamètre est le principal facteur prédictif de rupture ; au-delà de 45 mm, la surveillance échographique est renforcée (tous les 6 mois)."},"reveal":"Vous expliquez qu'à 46 mm une surveillance échographique tous les 6 mois était indiquée.","src":"p. 183-187","id":"225-case-51-s03"},{"phase":3,"narrative":"Le patient est à très haut risque périopératoire ; l'anatomie de l'anévrisme est favorable.","question":{"type":"QRU","stem":"Quelle stratégie thérapeutique privilégiez-vous ?","options":[{"t":"Traitement endovasculaire en urgence","ok":true,"why":"De plus en plus proposé même en contexte de rupture, surtout chez le sujet à très haut risque périopératoire."},{"t":"Surveillance échographique rapprochée","ok":false,"why":"L'anévrisme fissuré est une urgence absolue."},{"t":"Intervention programmée à froid dans 3 mois","ok":false,"why":"Il s'agit d'une urgence absolue."},{"t":"Artériographie avant toute décision","ok":false,"why":"L'artériographie n'est pas utile au diagnostic de l'AAA."},{"t":"Traitement médical seul","ok":false,"why":"L'anévrisme fissuré impose une intervention urgente."}],"explanation":"L'AAA rompu ou fissuré est une urgence absolue ; le traitement endovasculaire est de plus en plus proposé, surtout chez le sujet à très haut risque périopératoire."},"reveal":"Une endoprothèse aortique est posée en urgence par voie fémorale, avec succès.","src":"p. 185-187","id":"225-case-51-s04"},{"phase":4,"narrative":"Les suites sont simples. Vous organisez le suivi.","question":{"type":"QRM","stem":"Concernant le suivi après pose d'une endoprothèse aortique, quelles propositions sont exactes ?","options":[{"t":"Une surveillance par scanner ou échographie est nécessaire au long cours.","ok":true,"why":"Le texte le précise."},{"t":"Les endofuites peuvent faire progresser, voire rompre l'anévrisme.","ok":true,"why":"Le texte le précise."},{"t":"Une antibioprophylaxie est justifiée lors des gestes à risque bactérien.","ok":true,"why":"En raison du risque infectieux de la prothèse vasculaire."},{"t":"Le risque cardiovasculaire persiste malgré le succès du traitement.","ok":true,"why":"Le texte le précise."},{"t":"La surveillance peut être interrompue après 1 an si l'imagerie est normale.","ok":false,"why":"La surveillance après endoprothèse se fait au long cours."}],"explanation":"Après endoprothèse : surveillance scanner/écho au long cours (endofuites), antibioprophylaxie des gestes à risque bactérien, prise en charge du risque cardiovasculaire persistant."},"reveal":"Un suivi au long cours est programmé.","src":"p. 185-187","id":"225-case-51-s05"},{"phase":5,"narrative":"Vous recherchez d'autres localisations anévrismales.","question":{"type":"QROC","question":"Quelles localisations anévrismales associées l'échographie recherche-t-elle chez un porteur d'AAA ?","answer":"Anévrismes poplités et iliaques","accept":["artères poplitées et iliaques","poplités et iliaques"],"keywords":["poplit","iliaq"],"explanation":"L'échographie recherche des localisations anévrismales poplitées et iliaques associées."},"reveal":"L'écho-Doppler découvre un anévrisme poplité droit de 24 mm, perméable, avec un bon lit d'aval.","src":"p. 183-185","id":"225-case-51-s06"},{"phase":5,"narrative":"Vous faites le point sur cet anévrisme poplité.","question":{"type":"QRM","stem":"Concernant l'anévrisme de l'artère poplitée, quelles propositions sont exactes ?","options":[{"t":"Il est associé à un AAA dans environ 30 % des cas.","ok":true,"why":"Chiffre cité, d'où la recherche systématique d'un AAA."},{"t":"Il est bilatéral dans près de la moitié des cas.","ok":true,"why":"L'artère poplitée controlatérale doit donc être explorée."},{"t":"Il peut être découvert par la palpation d'une masse battante au creux poplité.","ok":true,"why":"Le pouls est alors « trop bien perçu » ; l'échodoppler peut aussi le découvrir."},{"t":"Son dépistage repose sur l'artériographie.","ok":false,"why":"Il est découvert par la palpation ou par un échodoppler, notamment en cas d'AAA ou d'anévrisme poplité controlatéral."},{"t":"Il est toujours symptomatique au moment du diagnostic.","ok":false,"why":"Il est souvent découvert à un stade asymptomatique (palpation, échodoppler)."}],"explanation":"L'anévrisme poplité est associé à un AAA dans ≈ 30 % des cas et bilatéral une fois sur deux ; il est découvert par la palpation d'une masse battante, par un échodoppler (dépistage si AAA ou anévrisme poplité controlatéral) ou devant une artériopathie ou une ischémie aiguë."},"reveal":"Le patient est adressé en consultation de chirurgie vasculaire.","src":"p. 186","id":"225-case-51-s07"},{"phase":6,"narrative":"Vous abordez avec le patient la prévention cardiovasculaire.","question":{"type":"QRM","stem":"Quelles propositions sont exactes chez ce porteur d'AAA ?","options":[{"t":"Son risque de décès cardiovasculaire est environ 10 fois supérieur à celui de rupture.","ok":true,"why":"Chiffre cité."},{"t":"Le contrôle des facteurs de risque est indispensable.","ok":true,"why":"Le texte le précise."},{"t":"L'AAA survient sur un terrain athéromateux dans 80 à 90 % des cas.","ok":true,"why":"Chiffre cité."},{"t":"La recherche d'une atteinte coronarienne, carotidienne ou d'une AOMI associée est inutile.","ok":false,"why":"L'AAA est souvent associé à une AOMI, une atteinte coronarienne ou carotidienne."},{"t":"Le tabagisme actif accélère la croissance anévrismale.","ok":true,"why":"Progression environ 3 fois plus rapide."}],"explanation":"Le porteur d'AAA, athéromateux dans 80–90 % des cas, a un risque de décès CV 10 fois supérieur à celui de rupture : contrôle des facteurs de risque indispensable."},"reveal":"Un sevrage tabagique est engagé.","src":"p. 183-187","id":"225-case-51-s08"},{"phase":6,"narrative":"Son frère, 60 ans, fumeur, demande s'il doit être dépisté.","question":{"type":"QRU","stem":"Quelle attitude proposez-vous ?","options":[{"t":"Une échographie abdominale de dépistage dès maintenant","ok":true,"why":"Le dépistage est recommandé chez l'homme > 65 ans, ou plus jeune en présence de facteurs de risque (tabac, athérome, antécédents familiaux)."},{"t":"Aucun dépistage avant 65 ans, quel que soit le contexte","ok":false,"why":"Le dépistage peut être plus précoce en présence de facteurs de risque."},{"t":"Un scanner injecté de dépistage","ok":false,"why":"Le dépistage repose sur l'échographie abdominale."},{"t":"Une artériographie aortique","ok":false,"why":"L'artériographie n'est pas utile."},{"t":"Un dépistage uniquement en cas de symptômes","ok":false,"why":"L'AAA est le plus souvent asymptomatique, d'où l'intérêt d'un dépistage."}],"explanation":"Dépistage échographique de l'AAA chez l'homme > 65 ans, ou plus jeune en présence de facteurs de risque (tabac, athérome, antécédents familiaux)."},"reveal":"Une échographie abdominale est prescrite à son frère.","src":"p. 183-185","id":"225-case-51-s09"}]}],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":{"id":"225-ff","sections":[{"key":"identite","title":"Carte d'identité flash","src":"p. 167-168, 174, 181, 183, 187","fields":[{"label":"Définition / seuil chiffré","value":"**AOMI** : atteinte athéromateuse entre aorte terminale et artères digitales ; IPS < 0,90 (sévère < 0,70) · **anévrisme** : dilatation focale > 50 % du diamètre d'amont ; AAA : intervention au-delà de 50-55 mm · ischémie aiguë : interruption brutale du flux"},{"label":"Causes reines (2 fréquentes + la plus grave)","value":"**Athérome** : AOMI (tabac, diabète), AAA (tabac, ATCD familiaux) · ischémie aiguë : thrombose in situ (sujet âgé, AOMI) ou embolie sur artères saines (FA) · la plus grave : rupture d'AAA"}]},{"key":"pattern","title":"Le pattern de reconnaissance","src":"p. 167-170, 181, 184","fields":[{"label":"Terrain classique","value":"**AOMI** : homme (pic 60-75 ans ; femme 70-80), 3e localisation de l'athérosclérose · **AAA** : homme > 65 ans, tabac, ATCD familiaux · ischémie aiguë : thrombose = sujet âgé artériopathe ; embolie = sujet plus jeune, artères saines"},{"label":"Triptyque sémiologique","value":"**AOMI** : claudication (crampe du mollet, cède < 5 min ; sévère < 100 m) → douleur de repos → ulcère/gangrène · **ischémie aiguë** : douleur brutale + membre froid livide + pouls abolis · AAA : masse battante expansive para-ombilicale"},{"label":"Mot-clé / signe discriminant","value":"Claudication fessière + troubles de l'érection : syndrome de **Leriche** (aorto-iliaque) · douleur postprandiale + amaigrissement : angor digestif · douleur abdominale intense pauvre en signes + FA : ischémie mésentérique aiguë"}]},{"key":"gravite","title":"Le tri vital & la gravité","src":"p. 168-169, 177-179, 184","fields":[{"label":"Alerte rouge immédiate","value":"**Ischémie aiguë** (nerfs atteints dès 2 h, muscles dès 6-8 h, nécrose cutanée vers 24 h) · **AAA** douloureux ou rompu (douleur abdominale/lombaire ± choc) · ischémie mésentérique aiguë : urgence vitale · ischémie critique : cheville < 50, orteil < 30 mmHg"},{"label":"Score pronostique officiel","value":"**Rutherford** ischémie aiguë : I viable, IIa menaçante, IIb immédiatement menaçante, III irréversible · Leriche-Fontaine (AOMI) : I asymptomatique, II claudication, III douleur de repos, IV ulcération/gangrène · critique : mortalité à 5 ans ≈ 70 %"}]},{"key":"paraclinique","title":"Le paraclinique de certitude","src":"p. 166-167, 170-173, 179-180, 184-185","fields":[{"label":"1re intention en urgence (timing)","value":"**Ischémie aiguë** : diagnostic clinique, aucun examen ne doit retarder l'intervention (écho-doppler seulement si grade I sans déficit neurologique) ; artériographie au bloc ; ECG + coagulation · AAA rompu : scanner ; mésentérique aiguë : angioscanner"},{"label":"Examen qui affirme le diagnostic","value":"**AOMI** : IPS (< 0,90) puis écho-doppler artériel · **AAA** : échographie (dépistage, diamètre, suivi) ; scanner injecté = bilan préthérapeutique · mésentérique chronique : écho-doppler, angioscanner ou angio-IRM"},{"label":"Piège paraclinique à éviter","value":"IPS > 1,40 = **médiacalcose** (diabétique, dialysé) → pression d'orteil · angioscanner/angio-IRM/artériographie seulement si revascularisation · artériographie inutile pour mesurer un AAA"}]},{"key":"orientation","title":"L'aiguillage clinique","src":"p. 179-180, 184-187","fields":[{"label":"Ambulatoire","value":null},{"label":"Hospitalisation conventionnelle","value":null},{"label":"USIC / soins intensifs / réanimation","value":"**Ischémie aiguë** : alerter l'équipe chirurgicale au plus tôt (bloc, revascularisation ; amputation si dépassée) · **AAA** douloureux ou rompu : centre spécialisé de chirurgie vasculaire en urgence · mésentérique aiguë : urgence chirurgicale"}]},{"key":"traitement","title":"Le pack thérapeutique de 1re intention","src":"p. 175-176, 182-183, 185-186","fields":[{"label":"Geste salvateur / conditionnement","value":"**Ischémie aiguë** : héparine non fractionnée dès le diagnostic (bolus 5 000 UI puis 500 UI/kg/j, TCA 2-3) + antalgiques palier 3 ; embolectomie de Fogarty si embolie ; aponévrotomie si revascularisation tardive ; amputation si dépassée"},{"label":"Molécule(s) reine(s) (DCI, voie, dose si cotée)","value":"**AOMI** : antiplaquettaire (aspirine ou clopidogrel) si symptomatique · statine systématique (LDL-C < 0,55 g/L) · IEC/ARA2"},{"label":"Mesure non pharmacologique / étiologique","value":"Arrêt du **tabac**, HbA1c < 7 %, marche 30-45 min ≥ 3×/sem (supervisée) · revascularisation (angioplastie ± stent, pontage) si ischémie permanente ou claudication < 100 m invalidante · **AAA** > 50-55 mm : chirurgie ou endoprothèse"}]},{"key":"securite","title":"Les fautes graves & la sécurité","src":"p. 173, 175, 178-179, 182-183, 186","fields":[{"label":"Contre-indications absolues","value":"Angio-IRM : **gadolinium** contre-indiqué si clairance < 30 mL/min/1,73 m² · angioscanner : vérifier allergies et fonction rénale · bêtabloquant : prudence en ischémie critique non revascularisable"},{"label":"Surveillance non négociable","value":"Après reperfusion : **syndrome de revascularisation** (hyperkaliémie, acidose, myoglobinurie → IRA) : diurèse, ionogramme, urée, créatinine, CPK ; syndrome des loges · AAA traité : écho-doppler/scanner au long cours (endofuites, faux anévrismes)"}]}],"src":"p. 166-187"},"pareto":{"id":"225-pareto","points":[{"id":"225-par-01","rank":"A","cat":"définition","text":"AOMI = atteinte athéromateuse entre l'**aorte terminale et les artères digitales** ; 3e localisation de l'athérosclérose ; FDR principaux : **tabac** + **diabète**","src":"p. 167-168"},{"id":"225-par-02","rank":"A","cat":"examen","text":"IPS (PAS cheville / PAS bras) : **< 0,90** = AOMI, **< 0,70** = sévère ; **> 1,40** = médiacalcose (diabète, dialyse) → pression d'orteil","src":"p. 170-171"},{"id":"225-par-03","rank":"A","cat":"clinique","text":"Claudication = crampe du mollet à la marche, cède en **< 5 min**, sévère si **< 100 m** ; fessière + troubles de l'érection = syndrome de **Leriche** (aorto-iliaque)","src":"p. 168-169"},{"id":"225-par-04","rank":"A","cat":"gravité","text":"Ischémie critique = douleurs de décubitus > 15 j (jambe pendante) ± ulcère/gangrène ; cheville **< 50 mmHg** ou hallux **< 30 mmHg** ; mortalité à 5 ans **≈ 70 %**","src":"p. 169, 171, 178"},{"id":"225-par-05","rank":"A","cat":"examen","text":"1re imagerie = **écho-doppler artériel** ; angioscanner / angio-IRM / artériographie **seulement si revascularisation** ; gadolinium CI si clairance **< 30 mL/min**","src":"p. 172-173"},{"id":"225-par-06","rank":"A","cat":"traitement","text":"AOMI : **arrêt du tabac**, **antiplaquettaire** (aspirine ou clopidogrel) si symptomatique, **statine** (LDL < 0,55 g/L), contrôle diabète/PA (IEC), marche supervisée 3×/sem","src":"p. 175"},{"id":"225-par-07","rank":"A","cat":"traitement","text":"**Revascularisation** (angioplastie ± stent, pontage) si **ischémie permanente** ou claudication sévère invalidante après réadaptation ; **amputation** en dernier recours","src":"p. 176-177"},{"id":"225-par-08","rank":"A","cat":"gravité","text":"Ischémie aiguë = urgence : douleur brutale, membre **froid et livide**, pouls abolis, déficit sensitivomoteur ; **aucun examen ne doit retarder** l'intervention","src":"p. 178-180"},{"id":"225-par-09","rank":"A","cat":"étiologie","text":"Ischémie aiguë : **thrombose in situ** (sujet âgé artériopathe) ou **embolie** sur artères saines (FA, valvulopathie, IDM) → auscultation, **ECG**, palpation abdominale","src":"p. 181-182"},{"id":"225-par-10","rank":"A","cat":"traitement","text":"Ischémie aiguë : **héparine non fractionnée** dès le diagnostic (bolus 5 000 UI, TCA 2-3) + antalgiques niveau 3 ; **embolectomie de Fogarty** si embolie ; amputation si dépassée","src":"p. 182-183"},{"id":"225-par-11","rank":"A","cat":"gravité","text":"Reperfusion : **syndrome de revascularisation** (hyperkaliémie, acidose, myoglobinurie → IRA) et **syndrome des loges** (aponévrotomie) → surveiller diurèse, ionogramme, CPK","src":"p. 178, 183"},{"id":"225-par-12","rank":"A","cat":"définition","text":"AAA = dilatation > **50 %** du diamètre d'amont, sous-rénale ; cause = **athérome** (80-90 %) ; FDR : âge, tabac, ATCD familiaux ; dépistage échographique **homme > 65 ans**","src":"p. 183-184"},{"id":"225-par-13","rank":"A","cat":"chiffre","text":"AAA : rupture selon le diamètre (< 40 mm : 0,4 %/an ; 50-59 : 3 % ; > 60 : **15 %**) ; intervention « à froid » si **> 50-55 mm** ; écho tous les **6 mois** si > 45 mm","src":"p. 184-186"},{"id":"225-par-14","rank":"A","cat":"gravité","text":"**AAA douloureux ou rompu** = urgence absolue : douleur abdominale/lombaire ± choc → centre de chirurgie vasculaire ; seul le **scanner** précède l'intervention ; endoprothèse possible","src":"p. 184-186"},{"id":"225-par-15","rank":"A","cat":"clinique","text":"Ischémie mésentérique : chronique = **angor digestif** (douleur postprandiale, amaigrissement) ; aiguë = douleur + peu de signes + vomissements/diarrhée + FA → **angioscanner**, urgence chirurgicale","src":"p. 166-167"}]},"extra":{"semio":[{"title":"Claudication intermittente et formes atypiques","rank":"A","src":"p. 168-169","content":"L'AOMI reste longtemps **asymptomatique** (circulation collatérale), puis se manifeste à l'effort (**ischémie d'effort**), enfin au repos (**ischémie permanente**).\n\n**Claudication intermittente typique** : **crampe du mollet** à la marche, **cédant en moins de 5 min** à l'arrêt ; **sévère** si distance de marche **< 100 m**.\n\n**Formes atypiques** fréquentes :\n- variabilité de la distance ;\n- localisation **fessière/cuisse** (atteinte **aorto-iliaque**) ;\n- paresthésies, ralentissement du pas.\n\n**Syndrome de Leriche** : atteinte aorto-iliaque + **claudication fessière** + **troubles de l'érection** (et fatigabilité à la marche).\n\n> Une atteinte sévère peut rester **masquée** : collatéralité, comorbidités limitant la marche, **neuropathie**.\n\nL'interrogatoire recherche systématiquement les autres atteintes athéromateuses (**angor, AVC**)."},{"title":"Ischémie permanente (stades III-IV)","rank":"A","src":"p. 169","content":"- **Douleurs de décubitus**, soulagées en **position déclive**.\n- **Ischémie critique** : douleurs durant **plus de 15 jours**, avec **pression de cheville < 50 mmHg** ou **pression d'hallux < 30 mmHg**.\n- **Troubles trophiques** :\n  - peau fine ;\n  - **ulcères aux zones d'appui** ;\n  - **gangrène des orteils**, plus fréquente chez le **diabétique**."},{"title":"Examen physique vasculaire des membres inférieurs","rank":"A","src":"p. 170","content":"Toujours **bilatéral et comparatif** :\n- **Inspection** : couleur, troubles trophiques.\n- **Palpation** : froideur ; pouls **fémoral, poplité, tibial postérieur, pédieux** (le pédieux est **absent congénitalement chez 5 %** des sujets) ; **temps de recoloration cutanée** normalement **< 3 s**.\n- **Auscultation** des trajets vasculaires (souffles).\n- **Palpation abdominale et poplitée** à la recherche d'un **anévrisme**."},{"title":"Ischémie aiguë de membre : tableau clinique","rank":"A","src":"p. 178-179","content":"**Interruption brutale** du flux artériel d'un membre : urgence menaçant le **membre** et le **pronostic vital**.\n\n- **Douleur brutale, intense**, à type de **broiement**, avec **impotence fonctionnelle**.\n- Membre **froid, livide**, **douloureux à la palpation musculaire**.\n- **Pouls abolis** en aval.\n- **Troubles neurologiques** : anesthésie, paralysie, notamment du **nerf fibulaire commun**.\n\n> Occlusion de la **bifurcation aortique** → ischémie **bilatérale** sévère pouvant aller jusqu'au **collapsus**."},{"title":"Ischémie aiguë : thrombose in situ vs embolie","rank":"B","src":"p. 181","content":"| | **Thrombose in situ** | **Embolie sur artère saine** |\n|---|---|---|\n| Terrain | **sujet âgé**, FDR CV, souvent **AOMI préexistante** (à rechercher sur l'autre membre) | **sujet plus jeune**, sans ATCD vasculaire (cardiopathie possible) |\n| Douleur | intensité **moyenne**, installation progressive ou rapide | **brutale, aiguë, sévère**, parfois précédée de **palpitations** |\n| Collatéralité | préalable, développée | **absente** |\n\nLes deux tableaux ne sont pas toujours totalement distincts."},{"title":"Anévrisme de l'aorte abdominale : présentations cliniques","rank":"A","src":"p. 184-185","content":"#### Forme asymptomatique (la plus fréquente)\nDécouverte fortuite : **masse battante et expansive para-ombilicale** (± souffle) à la palpation, ou à l'imagerie.\n\n#### Formes symptomatiques\n- **Fissuration/rupture** : **douleur abdominale ou lombaire** ± **choc hémorragique** ; urgence vitale ; rupture intrapéritonéale souvent **cataclysmique**.\n- **Fistule** : **aorto-cave** → insuffisance cardiaque à **débit élevé** ; **aorto-digestive** → hémorragie digestive.\n- **Embolie** à partir d'une thrombose intra-anévrismale.\n- **Compression** des organes de voisinage.\n- **Syndrome inflammatoire** : fièvre, AEG, élévation VS/CRP."},{"title":"Anévrisme de l'artère poplitée","rank":"A","src":"p. 186","content":"- Associé à un **AAA** dans **≈ 30 %** des cas ; **bilatéral** dans près de **la moitié** des cas.\n- Découverte : **masse battante poplitée**, écho-Doppler systématique (dépistage si AAA ou AP controlatéral connu) ou complication."},{"title":"Ischémies mésentériques chronique et aiguë","rank":"A","src":"p. 166-167","content":"#### Ischémie mésentérique chronique\nSténose du **tronc cœliaque** et/ou des **artères mésentériques**, souvent asymptomatique. Si symptomatique : **angor digestif** :\n- **douleurs abdominales postprandiales** ;\n- **restriction alimentaire** → **amaigrissement**, **dénutrition** ;\n- **souffle abdominal** possible.\n\n#### Ischémie mésentérique aiguë\nOcclusion brutale d'une artère digestive (thrombose in situ ou embolie) ; urgence vitale **rare** grâce aux collatérales. **Triade évocatrice** :\n1. **douleur abdominale aiguë pauvre en signes physiques** ;\n2. **vidange digestive accélérée** (vomissements/diarrhée) ;\n3. **arguments emboligènes** (fibrillation atriale)."},{"title":"Athérome aortique","rank":"A","src":"p. 166","content":"- Plaques pouvant toucher **tous les segments** de l'aorte dès un âge jeune, avec prédilection pour la **bifurcation aortique** et l'**origine des branches** (coronaires, digestives, rénales).\n- **Tabagisme** = facteur le plus associé.\n- Le plus souvent **asymptomatique**, de découverte fortuite à l'imagerie.\n- Complications : **embolies** (cerveau, membres, viscères).\n- Marque un **sur-risque cardiovasculaire global**."}],"criteres":[{"title":"Définition et classifications de l'AOMI","rank":"A","src":"p. 167-168","content":"**AOMI** : toute atteinte **athéromateuse significative** des artères entre l'**aorte terminale** et les **artères digitales**.\n\n| Leriche-Fontaine | Symptômes | Rutherford (grade/catégorie) | Symptômes |\n|---|---|---|---|\n| I | Asymptomatique | 0/0 | Asymptomatique |\n| II | Claudication intermittente | I/1-3 | Claudication légère à sévère |\n| III | Douleur ischémique de repos | II/4 | Douleur ischémique de repos |\n| IV | Ulcération ou gangrène | III/5-6 | Perte de substance faible à majeure |\n\nLa classification de **Rutherford**, plus détaillée, tend à remplacer celle de Leriche-Fontaine."},{"title":"Index de pression systolique (IPS) et pression d'orteil","rank":"A","src":"p. 170-171","content":"**IPS** = pression systolique de **cheville** / pression systolique **brachiale**, au doppler de poche ; examen de **1re intention** devant une suspicion d'AOMI.\n\n| IPS | Interprétation |\n|---|---|\n| **1,00–1,40** | normal |\n| **< 0,90** (au moins une cheville) | **AOMI** |\n| **< 0,70** | **AOMI sévère** |\n| **> 1,40** | **médiacalcose** → index de pression d'orteil |\n\n- **Index de pression d'orteil** pathologique si **< 0,70** ; **pression d'orteil < 30 mmHg** = ischémie critique.\n- Un IPS abaissé est aussi un **marqueur de risque CV** global."},{"title":"Ischémie critique, test de marche et TcPO2","rank":"A","src":"p. 169-172","content":"**Ischémie critique** : pression de cheville **< 50 mmHg** ou d'hallux/orteil **< 30 mmHg**.\n\n**Test de marche** sur tapis (protocole de **Strandness** : **3,2 km/h**, pente **10 %**) si symptômes avec **IPS de repos normal** ; évocateur d'AOMI si baisse de pression de cheville **> 30 mmHg** ou de l'IPS **> 20 %** après effort. Le **test de marche de 6 min** évalue le handicap fonctionnel global (non spécifique).\n\n**TcPO2** (après hyperémie), utile en ischémie critique :\n\n| TcPO2 (dos du pied) | Interprétation |\n|---|---|\n| > 50 mmHg | normale |\n| > 35 mmHg | bonne compensation |\n| 10–35 mmHg | hypoxie continue |\n| < 10 mmHg | hypoxie critique |"},{"title":"Imagerie de l'AOMI","rank":"A","src":"p. 172-173","content":"- **Échodoppler artériel** : examen de **1re intention** (non invasif, **localise et quantifie** les sténoses).\n- **Angioscanner** et **angio-IRM** (sensibilité/spécificité **≈ 95 %** vs artériographie) : **uniquement en vue d'une revascularisation**.\n  - angio-IRM : gadolinium **contre-indiqué si clairance < 30 mL/min/1,73 m²** ; ne visualise **pas les calcifications** (utiles au chirurgien).\n- **Artériographie** : réservée aux **procédures de revascularisation**, notamment réseau jambier et pédieux."},{"title":"Diagnostics différentiels et étiologiques de l'AOMI","rank":"B","src":"p. 174","content":"#### Différentiels\n- **Douleurs à la marche** : neurologiques (**canal lombaire étroit**, sciatalgie, atteinte médullaire), rhumatologiques (tendinite, arthrose), veineuses (claudication post-thrombotique), piège ou kyste poplité, endofibrose iliaque, syndrome des loges, malformations vasculaires, douleurs musculaires sous **statines**.\n- **Douleurs de décubitus** : neuropathie sensorielle, syndromes douloureux régionaux complexes, compression radiculaire.\n- **Ulcères** : veineux, microcirculatoire, neuropathique, traumatique.\n\n#### Étiologiques\n- **Athérome** : **> 95 %** des artériopathies oblitérantes des MI.\n- Non athéromateuses (rares) : **inflammatoires** (Buerger, Takayasu, Horton, collagénoses), dysplasie fibromusculaire, coarctation, postradiques, post-traumatiques, toxiques (**ergot de seigle**), gelures, compressions extrinsèques, atteintes de l'artère poplitée (piège poplité, kyste sous-adventiciel)."},{"title":"Classification de Rutherford de l'ischémie aiguë (ESC 2024)","rank":"A","src":"p. 179-180","content":"| Grade | Catégorie | Déficit sensitif | Déficit moteur | Pronostic |\n|---|---|---|---|---|\n| I | Viable | Absent | Absent | Pas de menace immédiate |\n| IIa | Discrètement menaçante | Absent ou limité aux orteils | Absent | Récupérable si prise en charge |\n| IIb | Immédiatement menaçante | Présent au-delà des orteils | Modéré | Récupération possible si urgence immédiate |\n| III | Irréversible | Anesthésie importante | Important, paralysie | Perte tissulaire et séquelles inévitables |\n\n**Diagnostic avant tout clinique** : aucune exploration ne doit retarder l'intervention, surtout si **déficit neurologique** (grade II). Échodoppler possible sans perte de temps si grade I sans atteinte neurologique. **Artériographie** le plus souvent **au bloc** pour guider le geste."},{"title":"Bilan étiologique de l'ischémie aiguë","rank":"A","src":"p. 181-182","content":"**Systématique** :\n- auscultation cardiaque, **ECG** ;\n- **palpation abdominale** (anévrisme) ;\n- **bilan de coagulation**.\n\n**Après revascularisation** :\n- **bilan cardiaque** : Holter, ETT ± ETO/IRM ;\n- **bilan artériel** : échodoppler, angioscanner ou artériographie.\n\n**Causes emboliques** [B] : cardiaques (**fibrillation atriale** = principale cause, FOP/anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome, anévrisme/dyskinésie du VG) ou aortiques (athérome, anévrisme, aortite, tumeur).\n\n**Causes de thrombose in situ** [B] : AOMI, artériopathies non athéromateuses, anévrisme poplité thrombosé, déshydratation/hémoconcentration du sujet âgé, kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies, iatrogènes (cathétérisme, TIH, ergotisme)."},{"title":"Anévrisme : définition, étiologies et diagnostic de l'AAA","rank":"A","src":"p. 183-185","content":"**Anévrisme** : dilatation **localisée et durable** d'une artère, diamètre dépassant de **plus de 50 %** celui du segment sus-jacent, avec **perte du parallélisme** des bords. Sièges (hors cerveau) : **aorte** (surtout **sous-rénale**), **artères poplitées**, **iliaques**.\n\n**Étiologies** [B] : **athérome** dans **80–90 %** ; formes familiales (Marfan, Ehlers-Danlos, Loeys-Dietz) ; aortites (Takayasu, Horton) ; rarement infectieuses (syphilis).\n\n**Dépistage échographique** : homme **> 65 ans**, ou plus jeune si FDR (tabac, athérome, ATCD familiaux).\n\n| Examen | Rôle |\n|---|---|\n| **Échographie abdominale** | dépistage, diamètre maximal, suivi ; recherche localisations poplitées/iliaques |\n| **Scanner abdominopelvien injecté** | **référence préthérapeutique** (diamètre, anatomie) |\n| IRM | alternative si contre-indication au scanner |\n| Artériographie | **pas utile** (lumière circulante seule, sous-estime la taille si thrombus mural) |"},{"title":"Ischémie mésentérique : diagnostic paraclinique","rank":"A","src":"p. 166-167, 187","content":"| | Chronique | Aiguë |\n|---|---|---|\n| Imagerie | **écho-Doppler digestif**, **angioscanner** ou **angio-IRM** ; artériographie seulement pour un geste endovasculaire | **angioscanner** (confirme le diagnostic) |\n| Traitement | **revascularisation** (de préférence endovasculaire) | **résection** des segments infarcis + **revascularisation** (endovasculaire ou chirurgicale) |"}],"chiffres":[{"theme":"Épidémiologie","label":"Rang de l'AOMI parmi les localisations de l'athérosclérose","value":"3e (après cœur et cerveau)","rank":"A","src":"p. 167"},{"theme":"Épidémiologie","label":"Pic d'âge de l'AOMI symptomatique chez l'homme","value":"60–75 ans","rank":"A","src":"p. 167"},{"theme":"Épidémiologie","label":"Pic d'âge de l'AOMI symptomatique chez la femme","value":"70–80 ans","rank":"A","src":"p. 167"},{"theme":"Épidémiologie","label":"Prévalence de l'AOMI clinique après 60 ans","value":"1–5 %","rank":"A","src":"p. 168"},{"theme":"Épidémiologie","label":"Prévalence de l'AOMI (clinique + infraclinique) après 60 ans","value":"10–15 %","rank":"A","src":"p. 168"},{"theme":"Épidémiologie","label":"Formes infracliniques pour un cas clinique d'AOMI","value":"2 à 4","rank":"A","src":"p. 168"},{"theme":"Épidémiologie","label":"Part d'origine athéromateuse des artériopathies oblitérantes des MI","value":"> 95 %","rank":"B","src":"p. 174"},{"theme":"Diagnostic","label":"Délai de disparition de la douleur de claudication à l'arrêt","value":"< 5 min","rank":"A","src":"p. 168"},{"theme":"Seuils et définitions","label":"Distance de marche définissant une claudication sévère","value":"< 100 m","rank":"A","src":"p. 169"},{"theme":"Seuils et définitions","label":"Durée des douleurs de décubitus en ischémie critique","value":"> 15 jours","rank":"A","src":"p. 169"},{"theme":"Seuils et définitions","label":"Pression de cheville définissant l'ischémie critique","value":"< 50 mmHg","rank":"A","src":"p. 169"},{"theme":"Seuils et définitions","label":"Pression d'hallux/d'orteil définissant l'ischémie critique","value":"< 30 mmHg","rank":"A","src":"p. 169, 171"},{"theme":"Épidémiologie","label":"Absence congénitale du pouls pédieux","value":"5 % des sujets","rank":"A","src":"p. 170"},{"theme":"Examens","label":"Temps de recoloration cutanée normal","value":"< 3 s","rank":"A","src":"p. 170"},{"theme":"Seuils et définitions","label":"IPS normal","value":"1,00 à 1,40","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"IPS diagnostique d'AOMI (au moins une cheville)","value":"< 0,90","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"IPS définissant une AOMI sévère","value":"< 0,70","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"IPS évoquant une médiacalcose","value":"> 1,40","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"Index de pression d'orteil pathologique","value":"< 0,70","rank":"A","src":"p. 171"},{"theme":"Examens","label":"Test de marche de Strandness : vitesse et pente","value":"3,2 km/h ; pente 10 %","rank":"A","src":"p. 171"},{"theme":"Diagnostic","label":"Baisse de pression de cheville après marche évocatrice d'AOMI","value":"> 30 mmHg","rank":"A","src":"p. 171"},{"theme":"Diagnostic","label":"Baisse de l'IPS après marche évocatrice d'AOMI","value":"> 20 %","rank":"A","src":"p. 171"},{"theme":"Examens","label":"Durée du test de marche évaluant le handicap fonctionnel global","value":"6 min","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"TcPO2 normale au dos du pied","value":"> 50 mmHg","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"TcPO2 de bonne compensation","value":"> 35 mmHg","rank":"A","src":"p. 171-172"},{"theme":"Seuils et définitions","label":"TcPO2 d'hypoxie continue","value":"10–35 mmHg","rank":"A","src":"p. 171-172"},{"theme":"Seuils et définitions","label":"TcPO2 d'hypoxie critique","value":"< 10 mmHg","rank":"A","src":"p. 172"},{"theme":"Examens","label":"Sensibilité/spécificité angioscanner et angio-IRM (vs artériographie)","value":"≈ 95 %","rank":"A","src":"p. 173"},{"theme":"Examens","label":"Clairance contre-indiquant le gadolinium (angio-IRM)","value":"< 30 mL/min/1,73 m²","rank":"A","src":"p. 172-173"},{"theme":"Traitement","label":"Cible d'HbA1c chez l'AOMI","value":"< 7 %","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible tensionnelle chez l'AOMI","value":"PAS 120–129 ; PAD 70–79 mmHg","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible de PA mentionnée avec l'IEC chez l'AOMI","value":"< 140/90 mmHg","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible de LDL-cholestérol chez l'AOMI","value":"< 0,55 g/L (< 1,4 mmol/L)","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Réduction minimale du LDL-c sous statine","value":"≥ 50 %","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible d'IMC chez l'AOMI","value":"20–25 kg/m²","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Réentraînement à la marche (traitement général)","value":"3 fois/semaine pendant 12 semaines","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Marche régulière (traitement local)","value":"30–45 min, ≥ 3 fois/semaine","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Périmètre de marche pour discuter une revascularisation (claudication)","value":"< 100 m","rank":"A","src":"p. 176"},{"theme":"Traitement","label":"Durée de la bithérapie antiplaquettaire après angioplastie","value":"1 à 6 mois","rank":"A","src":"p. 176"},{"theme":"Pronostic","label":"Réduction de l'espérance de vie du claudicant","value":"≈ 10 ans","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Complications CV à 5 ans chez le claudicant","value":"20 %","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Décès à 5 ans chez le claudicant","value":"20 % (pour moitié CV)","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Aggravation locale à 5 ans chez le claudicant","value":"25 % (dont 1/5 d'amputation majeure)","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Risque d'amputation à 5 ans chez le claudicant","value":"≈ 5 %","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Mortalité à 5 ans en ischémie critique","value":"≈ 70 %","rank":"A","src":"p. 178"},{"theme":"Pronostic","label":"Ischémie aiguë : délai de souffrance des cellules nerveuses","value":"dès 2 h","rank":"A","src":"p. 178"},{"theme":"Pronostic","label":"Ischémie aiguë : délai de souffrance musculaire (rhabdomyolyse)","value":"dès 6–8 h","rank":"A","src":"p. 178"},{"theme":"Pronostic","label":"Ischémie aiguë : apparition de la nécrose cutanée","value":"vers la 24e heure","rank":"A","src":"p. 178"},{"theme":"Seuils et définitions","label":"Nombre de grades de Rutherford (ischémie aiguë)","value":"4 : I, IIa, IIb, III","rank":"A","src":"p. 179"},{"theme":"Doses","label":"Bolus d'héparine non fractionnée en ischémie aiguë","value":"5000 UI","rank":"A","src":"p. 182"},{"theme":"Doses","label":"Perfusion continue d'HNF en ischémie aiguë","value":"500 UI/kg/j","rank":"A","src":"p. 182"},{"theme":"Surveillance","label":"Cible de TCA sous HNF en ischémie aiguë","value":"entre 2 et 3","rank":"A","src":"p. 182"},{"theme":"Traitement","label":"Palier d'antalgiques souvent nécessaire en ischémie aiguë","value":"palier 3","rank":"A","src":"p. 182"},{"theme":"Seuils et définitions","label":"Dilatation définissant un anévrisme","value":"augmentation de diamètre > 50 % par rapport au segment sus-jacent","rank":"A","src":"p. 183"},{"theme":"Épidémiologie","label":"Prévalence de l'AAA chez l'homme > 65 ans","value":"2–5 %","rank":"A","src":"p. 183"},{"theme":"Épidémiologie","label":"Prévalence de l'AAA entre 75 et 84 ans","value":"5 % (homme) ; 3 % (femme)","rank":"A","src":"p. 183-184"},{"theme":"Pronostic","label":"Risque annuel de rupture d'AAA < 40 mm","value":"≈ 0,4 %/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque annuel de rupture d'AAA de 50–59 mm","value":"3 %/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque annuel de rupture d'AAA > 60 mm","value":"15 %/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque de rupture chez la femme à diamètre égal","value":"≈ 4 fois plus élevé","rank":"A","src":"p. 184"},{"theme":"Épidémiologie","label":"Décès par rupture d'AAA en Europe","value":"≈ 12 000/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque de décès CV du porteur d'AAA vs risque de rupture","value":"10 fois supérieur","rank":"A","src":"p. 184"},{"theme":"Épidémiologie","label":"Part des AAA sur terrain athéromateux","value":"80–90 %","rank":"B","src":"p. 184"},{"theme":"Diagnostic","label":"Âge du dépistage échographique de l'AAA chez l'homme","value":"> 65 ans (plus jeune si FDR)","rank":"A","src":"p. 184-185"},{"theme":"Pronostic","label":"Croissance moyenne d'un AAA","value":"2–4 mm/an","rank":"B","src":"p. 185-186"},{"theme":"Pronostic","label":"Accélération de la progression de l'AAA par tabagisme actif","value":"≈ 3 fois plus rapide","rank":"B","src":"p. 185-186"},{"theme":"Surveillance","label":"Diamètre d'AAA imposant une surveillance échographique renforcée","value":"> 45 mm","rank":"B","src":"p. 185-186"},{"theme":"Surveillance","label":"Rythme de surveillance renforcée de l'AAA","value":"tous les 6 mois","rank":"B","src":"p. 185-186"},{"theme":"Traitement","label":"Seuil de diamètre pour une intervention « à froid » sur AAA","value":"50–55 mm","rank":"B","src":"p. 185-186"},{"theme":"Épidémiologie","label":"Association anévrisme poplité – AAA","value":"≈ 30 %","rank":"A","src":"p. 185-187"},{"theme":"Épidémiologie","label":"Bilatéralité de l'anévrisme poplité","value":"près de la moitié des cas","rank":"A","src":"p. 185-187"}],"physio":[{"theme":"Mécanismes","title":"AOMI : de l'ischémie d'effort à l'ischémie permanente","rank":"A","src":"p. 167-170","content":"1. Lésions **athéromateuses** comparables aux autres territoires (tabac et diabète = principaux FDR ; diabète → formes plus **distales** et graves).\n2. Développement d'une **circulation collatérale** → longue phase **asymptomatique**.\n3. À l'effort, apport insuffisant → **ischémie d'effort** : **claudication intermittente**.\n4. Stade avancé : apport insuffisant même au repos → **ischémie permanente** : douleurs de **décubitus** (soulagées en position **déclive**), puis **troubles trophiques**.\n\nLa collatéralité, une comorbidité limitant la marche ou une **neuropathie** peuvent masquer une atteinte sévère."},{"theme":"Mécanismes","title":"Ischémie aiguë : déterminants de gravité et chronologie","rank":"A","src":"p. 178","content":"**Gravité** selon : **PA systémique**, abondance de la **collatéralité**, qualité du **lit d'aval**.\n\n**Chronologie des lésions** :\n1. **Nerfs** : souffrance **dès 2 h** (→ troubles sensitivomoteurs).\n2. **Muscles** : souffrance **dès 6–8 h** (**rhabdomyolyse**).\n3. **Peau** : **nécrose** vers la **24e heure**.\n\nThrombose in situ : douleur moins intense grâce à la collatéralité préalable ; embolie sur artère saine : douleur brutale et sévère (pas de collatérales)."},{"theme":"Conséquences","title":"Syndrome des loges et syndrome de revascularisation","rank":"A","src":"p. 178, 182-183","content":"#### Syndrome des loges\n**Œdème musculaire** dans des **loges aponévrotiques inextensibles** → compression → **syndrome des loges**, traité par **aponévrotomie de décharge** (systématique si revascularisation tardive, loge antéro-externe de jambe en général).\n\n#### Syndrome de revascularisation\nÀ la reperfusion, **relargage d'acides et de radicaux libres** :\n- **hyperkaliémie**, **acidose métabolique** ;\n- hyperuricémie, **myoglobinémie/myoglobinurie** ;\n- hypocalcémie, hyperphosphorémie ;\n- voire **CIVD** ;\n- **IRA** (nécrose tubulaire).\n\n**Prise en charge** : sonde urinaire (diurèse), ionogramme, urée, créatininémie, **CPK** ; **bicarbonates IV** ; hyperkaliémie → **polystyrène sulfonate de sodium**, voire **dialyse** ; lavage de membre au sérum physiologique."},{"theme":"Mécanismes","title":"Formation de l'anévrisme","rank":"A","src":"p. 183","content":"- La **média** perd sa **résistance à la distension** :\n  - **destruction des fibres élastiques** ;\n  - **fragmentation du collagène** ;\n  - sous l'effet d'enzymes comme les **métalloprotéases**.\n- Résultat : dilatation **localisée et durable** (diamètre dépassant de > 50 % celui du segment sus-jacent) avec **perte du parallélisme** des bords."},{"theme":"Histoire naturelle","title":"Histoire naturelle de l'AAA","rank":"B","src":"p. 184-186","content":"- Le **diamètre** est le **principal facteur prédictif** du risque de rupture.\n- Croissance moyenne **2–4 mm/an**, variable ; plus rapide chez l'**homme fumeur** avec un anévrisme déjà volumineux (tabagisme actif : **≈ 3 fois** plus rapide).\n- Risque annuel de rupture : **≈ 0,4 %** (< 40 mm), **3 %** (50–59 mm), **15 %** (> 60 mm) ; **≈ 4 fois** plus élevé chez la **femme** à diamètre égal.\n- Le porteur d'AAA a un risque de **décès CV** (coronaire, AVC) **10 fois** supérieur à celui de rupture → contrôle des FDR indispensable.\n- Thrombose intra-anévrismale → **embolies** ; après endoprothèse, les **endofuites** peuvent faire **progresser voire rompre** l'anévrisme."},{"theme":"Mécanismes","title":"Athérome rénal et digestif","rank":"A","src":"p. 166-167","content":"- **Artères rénales** : athérome → **HTA rénovasculaire** par **activation du SRAA**.\n- **Artères digestives** : sténose chronique → apport insuffisant lors de la digestion → **angor digestif** postprandial → restriction alimentaire, amaigrissement.\n- Occlusion brutale (thrombose ou embolie) → **ischémie mésentérique aiguë**, **rare** grâce aux **collatérales** ; évolution vers la **nécrose**."}],"parcours":[{"title":"AOMI : de la claudication à la revascularisation","rank":"A","patient":"M. L., 66 ans, fumeur, diabétique de type 2, consulte pour une crampe du mollet gauche apparaissant après environ 150 m de marche et cédant en 2 minutes à l'arrêt. Il est traité pour une HTA et n'a jamais eu d'exploration vasculaire.","steps":[{"phase":"Interrogatoire","title":"Caractériser la douleur de marche","question":"Le patient décrit une douleur du mollet à la marche. Que recherches-tu à l'interrogatoire ?","answer":"**Claudication intermittente** typique : **crampe du mollet à la marche**, cédant en **moins de 5 minutes** à l'arrêt ; **sévère** si distance de marche **< 100 m**.\n\n**Formes atypiques fréquentes** : variabilité, localisation **fessière/cuisse** (atteinte aorto-iliaque), paresthésies, ralentissement du pas.\n\n**Syndrome de Leriche** : atteinte **aorto-iliaque** + **claudication fessière** + **troubles de l'érection**.\n\n**Ischémie permanente** (stades III-IV) : **douleurs de décubitus soulagées en position déclive** ; troubles trophiques (peau fine, ulcères aux zones d'appui, gangrène des orteils).\n\n**Terrain** : **tabagisme** et **diabète** (2 principaux FDR), hypercholestérolémie, HTA.\n\n**Autres localisations athéromateuses** à rechercher **systématiquement** : angor, AVC.","cas":[{"si":"Si claudication fessière avec troubles de l'érection","alors":"**Syndrome de Leriche** (atteinte aorto-iliaque)."},{"si":"Si comorbidités limitant la marche ou neuropathie","alors":"Une atteinte sévère peut rester **masquée** (collatéralité, absence de marche, neuropathie)."},{"si":"Si douleurs abdominales postprandiales avec restriction alimentaire et amaigrissement","alors":"Évoquer un **angor digestif** (ischémie mésentérique chronique) : écho-Doppler digestif, angioscanner ou angio-IRM ; revascularisation (de préférence endovasculaire)."}],"pieges":["Éliminer une AOMI devant une claudication atypique (fessière, variable, paresthésies).","Conclure à l'absence d'AOMI sévère chez un patient qui ne marche pas ou neuropathe."],"src":"p. 166, 168-170"},{"phase":"Diagnostic positif","title":"Définir et classer l'AOMI","question":"Comment définis-tu l'AOMI et comment classes-tu sa sévérité clinique ?","answer":"**AOMI** = atteinte **athéromateuse significative** des artères entre l'**aorte terminale** et les **artères digitales** ; **3e localisation** de l'athérosclérose (après cœur et cerveau). Prévalence clinique **1–5 %** après 60 ans, **10–15 %** en incluant les formes infracliniques (2 à 4 infracliniques pour 1 clinique → **dépistage ciblé**).\n\n| Leriche-Fontaine | Symptômes | Rutherford (grade/catégorie) | Symptômes |\n|---|---|---|---|\n| I | Asymptomatique | 0/0 | Asymptomatique |\n| II | Claudication intermittente | I/1-3 | Claudication légère à sévère |\n| III | Douleur ischémique de repos | II/4 | Douleur ischémique de repos |\n| IV | Ulcération ou gangrène | III/5-6 | Perte de substance faible à majeure |\n\n**Ischémie d'effort** (stade II) puis **ischémie permanente** (stades III-IV).\n\n**Ischémie critique** : douleurs de décubitus **> 15 jours** avec **pression de cheville < 50 mmHg** ou **d'hallux < 30 mmHg**.","cas":[{"si":"Si patient diabétique","alors":"Formes **plus distales et plus graves** ; gangrène des orteils plus fréquente."}],"pieges":["Confondre les stades de Leriche-Fontaine et les catégories de Rutherford."],"src":"p. 167-170"},{"phase":"Examen clinique","title":"Examen vasculaire","question":"Comment conduis-tu l'examen physique ?","answer":"Examen **toujours bilatéral et comparatif** :\n\n- **inspection** : couleur, troubles trophiques ;\n- **palpation** : froideur ; pouls **fémoral, poplité, tibial postérieur, pédieux** ; **temps de recoloration cutanée** (normal **< 3 s**) ;\n- **auscultation** des trajets vasculaires (souffles) ;\n- **palpation abdominale et poplitée** à la recherche d'un **anévrisme**.","cas":[{"si":"Si pouls pédieux absent isolément","alors":"Il peut être **congénitalement absent chez 5 %** des sujets."}],"pieges":["Conclure à une AOMI sur la seule absence du pouls pédieux.","Oublier la palpation abdominale et poplitée (anévrisme associé)."],"src":"p. 170"},{"phase":"Examens complémentaires","title":"Index de pression systolique et tests fonctionnels","question":"Quel examen fais-tu en 1re intention pour confirmer l'AOMI et comment l'interprètes-tu ?","answer":"**IPS** = pression systolique de **cheville** / pression systolique **brachiale**, au **doppler de poche** — **examen de 1re intention**.\n\n| IPS | Interprétation |\n|---|---|\n| 1,00–1,40 | normal |\n| **< 0,90** (au moins une cheville) | **AOMI** |\n| **< 0,70** | **AOMI sévère** |\n| **> 1,40** | **médiacalcose** → index de pression d'orteil (pathologique si **< 0,70** ; pression d'orteil **< 30 mmHg** = ischémie critique) |\n\nL'IPS abaissé est aussi un **marqueur de risque CV global**.\n\n**Test de marche** (tapis roulant, **Strandness** : **3,2 km/h, pente 10 %**) si symptômes avec IPS de repos normal : baisse de pression de cheville **> 30 mmHg** ou de l'IPS **> 20 %** après effort = évocatrice d'AOMI. Le **test de marche de 6 minutes** évalue le handicap fonctionnel global (non spécifique).\n\n**TcPO2** (utile en ischémie critique) : normale **> 50 mmHg** au dos du pied ; > 35 = bonne compensation ; 10–35 = hypoxie continue ; **< 10 = hypoxie critique**.","cas":[{"si":"Si IPS > 1,40","alors":"**Médiacalcose** : utiliser l'**index de pression d'orteil**."},{"si":"Si symptômes typiques mais IPS de repos normal","alors":"**Test de marche** sur tapis roulant."}],"pieges":["Rassurer sur un IPS élevé > 1,40 : il traduit des artères incompressibles, pas l'absence d'AOMI.","Écarter une AOMI sur un IPS de repos normal chez un symptomatique sans test de marche."],"src":"p. 171-172"},{"phase":"Examens complémentaires","title":"Imagerie artérielle","question":"Quelle imagerie demandes-tu, et quand ?","answer":"- **Échodoppler artériel** : examen d'imagerie de **1re intention** (non invasif, **localise et quantifie** les sténoses).\n- **Angioscanner** et **angio-IRM** (sensibilité/spécificité **≈ 95 %** vs artériographie) : **uniquement en vue d'une revascularisation**.\n  - angio-IRM : gadolinium **contre-indiqué si clairance < 30 mL/min/1,73 m²** ; ne visualise pas les **calcifications**, utiles au chirurgien.\n- **Artériographie** : réservée aux **procédures de revascularisation**, notamment pour le réseau jambier et pédieux.","cas":[{"si":"Si insuffisance rénale sévère (clairance < 30 mL/min/1,73 m²)","alors":"**Pas de gadolinium** (angio-IRM)."},{"si":"Si projet de revascularisation","alors":"Angioscanner ou angio-IRM ; artériographie lors du geste."}],"pieges":["Demander un angioscanner en 1re intention chez un claudicant sans projet de revascularisation.","Demander une artériographie diagnostique."],"src":"p. 172-173"},{"phase":"Diagnostic différentiel","title":"Diagnostics différentiels [B]","question":"Quels diagnostics différentiels évoques-tu selon le tableau ?","answer":"| Tableau | Diagnostics différentiels |\n|---|---|\n| **Douleurs à la marche** | neurologique (**canal lombaire étroit**, sciatalgie, atteinte médullaire), rhumatologique (tendinite, arthrose), veineuse (claudication post-thrombotique), piège ou kyste poplité, endofibrose iliaque, syndrome des loges, malformations vasculaires, **douleurs musculaires sous statines** |\n| **Douleurs de décubitus** | neuropathie sensorielle, syndromes douloureux régionaux complexes, compression radiculaire |\n| **Ulcères** | veineux, microcirculatoire, neuropathique, traumatique |","cas":[],"pieges":["Oublier les myalgies sous statines chez un patient déjà traité."],"src":"p. 174"},{"phase":"Diagnostic étiologique","title":"Cause de l'artériopathie [B]","question":"L'AOMI est-elle forcément athéromateuse ? Quand évoques-tu une autre cause ?","answer":"- Origine **athéromateuse** : **> 95 %** des artériopathies oblitérantes des membres inférieurs.\n- Artériopathies **non athéromateuses** (rares) : **inflammatoires** (Buerger, Takayasu, Horton, collagénoses), **dysplasie fibromusculaire**, **coarctation de l'aorte**, atteintes **postradiques**, **post-traumatiques**, **toxiques** (dérivés de l'ergot de seigle), **gelures**, **compressions extrinsèques**, atteintes spécifiques de l'artère poplitée (**piège poplité**, **kyste sous-adventiciel**).","cas":[{"si":"Si sujet jeune sans facteur de risque cardiovasculaire","alors":"Évoquer une **artériopathie non athéromateuse** (inflammatoire, piège poplité, kyste adventiciel, dysplasie…)."}],"pieges":[],"src":"p. 174"},{"phase":"Évaluation du risque / pronostic","title":"Pronostic de l'AOMI","question":"Quel est le pronostic de ce patient claudicant ?","answer":"Pronostic **grave**, comparable à certains cancers en ischémie permanente.\n\n**Chez le claudicant** :\n\n- espérance de vie réduite d'**environ 10 ans** ;\n- à 5 ans : **20 %** de complications CV, **20 %** de décès (pour moitié CV), **25 %** d'aggravation locale (dont 1/5 d'amputation majeure), **≈ 5 %** de risque d'amputation.\n\n**En ischémie critique** : mortalité à 5 ans **≈ 70 %**.\n\nUn **IPS abaissé** est un marqueur de **risque CV global** : l'AOMI impose de rechercher les autres localisations athéromateuses (angor, AVC).","cas":[],"pieges":["Réduire l'AOMI à un problème de membre : le pronostic est d'abord cardiovasculaire."],"src":"p. 171, 177-178"},{"phase":"Traitement spécifique","title":"Traitement à visée générale","question":"Quel traitement de fond prescris-tu, avec quelles cibles ?","answer":"**Contrôle des facteurs de risque (tous les stades)** :\n\n| Cible | Objectif |\n|---|---|\n| Tabac | **arrêt** |\n| Diabète | **HbA1c < 7 %** |\n| PA | **PAS 120–129**, **PAD 70–79 mmHg** |\n| LDL-C | **< 0,55 g/L (< 1,4 mmol/L)** avec réduction **≥ 50 %** sous **statine** systématique |\n| Poids | IMC **20–25 kg/m²** |\n| Mode de vie | régime méditerranéen ; réentraînement **3 fois/semaine pendant 12 semaines** |\n\n**Antithrombotiques** :\n\n- **antiplaquettaire** (**aspirine ou clopidogrel**) chez **tout AOMI symptomatique** ; discuté si asymptomatique isolée ;\n\n**Autres** :\n\n- **IEC** : utile sur le plan pronostique (cible PA < 140/90 mmHg) ;\n- **bêtabloquants** possibles si indication formelle (cardiopathie ischémique, insuffisance cardiaque), **prudence en ischémie critique non revascularisable**.","cas":[{"si":"Si AOMI asymptomatique isolée","alors":"Antiplaquettaire **discuté** (non systématique)."},{"si":"Si ischémie critique non revascularisable","alors":"**Prudence** avec les bêtabloquants."}],"pieges":["Contre-indiquer les bêtabloquants chez tout artériopathe : ils restent possibles si indication formelle."],"src":"p. 175"},{"phase":"Traitement spécifique","title":"Traitement à visée locale","question":"Quel traitement proposes-tu pour améliorer la marche ?","answer":"- **Arrêt du tabac** et **marche régulière** : **30–45 min, ≥ 3 fois/semaine**, idéalement en **réadaptation supervisée** + **éducation thérapeutique**.\n- **Traitements vasoactifs** (ex. pentoxifylline) : bénéfice **modeste** sur le périmètre de marche, **sans effet pronostique**.\n- **Prostaglandines** : possibles en **ischémie critique non revascularisable**.","cas":[],"pieges":["Compter sur un vasoactif pour améliorer le pronostic : il n'a aucun effet pronostique."],"src":"p. 175-176"},{"phase":"Traitement spécifique","title":"Revascularisation","question":"Quand et comment revascularises-tu ?","answer":"**Indications** :\n\n- **systématiquement proposée** en cas d'**ischémie permanente** ;\n- **discutée** en cas de **claudication sévère invalidante** (périmètre **< 100 m**), notamment **après échec du traitement médical** bien conduit.\n\n**Techniques** :\n\n| Lésion | Technique |\n|---|---|\n| Courte / proximale | **angioplastie endovasculaire** (± stent) + **bithérapie antiplaquettaire 1–6 mois** |\n| Étendue | **chirurgie** : pontage veineux ou prothétique, endartériectomie |\n\nTechniques **hybrides** possibles. **Surveillance clinique et écho-Doppler systématique** après le geste.\n\n**Soins de plaies** multidisciplinaires ; **amputation** en **dernier recours** (zone saine et bien oxygénée, guidée par la **TcPO2**).","cas":[{"si":"Si ischémie permanente (stade III-IV)","alors":"**Revascularisation systématiquement proposée**."},{"si":"Si claudication non invalidante","alors":"Traitement médical et réadaptation d'abord ; revascularisation discutée seulement si claudication sévère invalidante."}],"pieges":["Revasculariser d'emblée une claudication non invalidante.","Choisir le niveau d'amputation sans évaluation de l'oxygénation (TcPO2)."],"src":"p. 176"},{"phase":"Complications","title":"Complications évolutives","question":"Quelles complications peuvent survenir au cours de l'évolution ?","answer":"- **Aggravation locale** : passage à l'**ischémie permanente** (douleurs de décubitus, troubles trophiques, gangrène) ; amputation.\n- **Ischémie aiguë** de membre par **thrombose in situ** sur AOMI préexistante (cf. parcours ischémie aiguë).\n- **Complications cardiovasculaires** : 20 % à 5 ans chez le claudicant (coronaires, AVC).\n- **Embolies** à partir de plaques d'**athérome aortique** (cerveau, membres, viscères).","cas":[{"si":"Si aggravation brutale avec membre froid, douloureux, pouls abolis","alors":"**Ischémie aiguë** → urgence vasculaire, héparine et avis chirurgical."},{"si":"Si douleur abdominale aiguë pauvre en signes physiques","alors":"Évoquer une **ischémie mésentérique aiguë** (angioscanner)."}],"pieges":[],"src":"p. 166, 177, 181"},{"phase":"Suivi","title":"Éducation et suivi","question":"Quels messages délivres-tu et comment organises-tu le suivi ?","answer":"- **Éducation thérapeutique** : arrêt du tabac, marche régulière (30–45 min, ≥ 3 fois/semaine), idéalement en réadaptation supervisée.\n- Contrôle des cibles : HbA1c, PA, LDL-C.\n- Après revascularisation : **surveillance clinique et écho-Doppler systématique**.\n- Rechercher les autres localisations athéromateuses (angor, AVC).","cas":[],"pieges":[],"src":"p. 170, 175-176"}]},{"title":"Ischémie aiguë de membre inférieur","rank":"A","patient":"M. R., 74 ans, en fibrillation atriale non anticoagulée, est adressé par le SAMU pour une douleur brutale et intense du membre inférieur droit apparue il y a 3 heures. Le pied est froid et pâle, et il ne peut plus le mobiliser normalement.","steps":[{"phase":"Accueil & gravité","title":"Reconnaître l'urgence","question":"Quelle est ta première impression et pourquoi l'horloge compte-t-elle ?","answer":"**Ischémie aiguë de membre** = **interruption brutale du flux artériel** d'un membre : **urgence vasculaire** menaçant le **membre** et le **pronostic vital**.\n\n**Chronologie** :\n\n- cellules **nerveuses** : souffrent **dès 2 h** ;\n- cellules **musculaires** : **dès 6–8 h** (rhabdomyolyse) ;\n- **nécrose cutanée** : vers la **24e heure**.\n\n**Gravité** dépendant de : PA systémique, abondance de la **collatéralité**, qualité du **lit d'aval**.","cas":[{"si":"Si occlusion de la bifurcation aortique","alors":"Ischémie **bilatérale sévère**, pouvant aller jusqu'au **collapsus**."}],"pieges":["Temporiser devant une ischémie aiguë : chaque heure compte."],"src":"p. 178"},{"phase":"Examen clinique","title":"Diagnostic clinique","question":"Quels signes cliniques recherches-tu ?","answer":"- **Douleur brutale intense** à type de **broiement** avec **impotence fonctionnelle** ;\n- membre **froid**, **livide**, **douloureux à la palpation musculaire** ;\n- **pouls abolis en aval** ;\n- **troubles neurologiques** : **anesthésie**, **paralysie**, notamment du **nerf fibulaire commun**.\n\nExamen **bilatéral** : rechercher une AOMI sur l'autre membre (orientation vers une thrombose in situ).","cas":[],"pieges":["Négliger l'examen neurologique du membre : c'est lui qui détermine le degré d'urgence."],"src":"p. 179-181"},{"phase":"Évaluation du risque / pronostic","title":"Classer la sévérité (Rutherford)","question":"Comment classes-tu la sévérité de cette ischémie ?","answer":"**Classification de Rutherford** (ESC 2024) :\n\n| Grade | Catégorie | Déficit sensitif | Déficit moteur | Pronostic |\n|---|---|---|---|---|\n| I | Viable | Absent | Absent | Pas de menace immédiate |\n| IIa | Discrètement menaçante | Absent ou limité aux orteils | Absent | Récupérable si prise en charge |\n| IIb | Immédiatement menaçante | Au-delà des orteils | Modéré | Récupération possible si urgence immédiate |\n| III | Irréversible | Anesthésie importante | Important, paralysie | Perte tissulaire et séquelles inévitables |","cas":[{"si":"Si grade IIb","alors":"**Urgence immédiate** : aucun examen ne doit retarder la revascularisation."},{"si":"Si grade III (ischémie dépassée)","alors":"**Amputation d'emblée**."}],"pieges":["Retarder la revascularisation d'un grade II pour réaliser une imagerie."],"src":"p. 179-180, 182"},{"phase":"Examens complémentaires","title":"Place des examens","question":"Quels examens demandes-tu avant l'intervention ?","answer":"Diagnostic **purement clinique** : **aucune exploration ne doit retarder l'intervention**, surtout en cas de **déficit neurologique** (grade II).\n\n- **Échodoppler** : possible **sans perte de temps** si le tableau le permet (**grade I sans atteinte neurologique**).\n- **Artériographie** : le plus souvent **au bloc** pour guider le geste (localisation, aspect de l'occlusion, qualité du réseau d'aval) et dépister d'autres emboles.\n\n**Bilan étiologique initial systématique** : **auscultation cardiaque**, **ECG**, **palpation abdominale** (anévrisme), **bilan de coagulation**.","cas":[{"si":"Si grade I sans déficit neurologique","alors":"**Échodoppler** réalisable sans retarder la prise en charge."},{"si":"Si déficit neurologique","alors":"**Bloc** sans exploration préalable ; artériographie peropératoire."}],"pieges":["Demander un angioscanner qui retarde le geste chez un patient avec déficit neurologique."],"src":"p. 180-181"},{"phase":"Diagnostic étiologique","title":"Thrombose ou embolie ?","question":"Quels éléments orientent vers une thrombose in situ ou une embolie ?","answer":"| | **Thrombose in situ** | **Embolie sur artère saine** |\n|---|---|---|\n| Terrain | **sujet âgé**, FDR CV, souvent **AOMI préexistante** (à rechercher sur l'autre membre) | **sujet plus jeune**, sans ATCD vasculaire (cardiopathie possible) |\n| Douleur | intensité **moyenne**, installation progressive ou rapide (collatéralité préalable) | **brutale, aiguë, sévère** (absence de collatérales), parfois précédée de **palpitations** |\n| Causes | AOMI, artériopathies non athéromateuses, **anévrisme poplité thrombosé**, déshydratation/hémoconcentration du sujet âgé, kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies, iatrogènes (cathétérisme, **thrombopénie à l'héparine**, ergotisme) | **cardiaques** : **fibrillation atriale**, FOP/anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome, anévrisme/dyskinésie du VG ; **aortiques** : athérome, anévrisme, aortite, tumeur |\n\nLes deux tableaux ne sont **pas toujours totalement distincts**.","cas":[{"si":"Si fibrillation atriale","alors":"Principale cause cardiaque d'**embolie** artérielle des membres."},{"si":"Si anévrisme poplité connu","alors":"Ischémie aiguë par **thrombose** ou **embolie** à partir de l'anévrisme poplité."}],"pieges":["Méconnaître une thrombopénie à l'héparine chez un patient sous héparine qui fait une ischémie aiguë."],"src":"p. 181"},{"phase":"Traitement en urgence","title":"Traitement médical immédiat","question":"Que prescris-tu immédiatement, avant la revascularisation ?","answer":"- **Héparine non fractionnée** dès le diagnostic, **après le prélèvement du bilan de coagulation** :\n  - **bolus 5 000 UI** ;\n  - puis **perfusion continue 500 UI/kg/j** ;\n  - **TCA cible entre 2 et 3**.\n- **Antalgiques de palier 3** (souvent nécessaires).\n- **Oxygénothérapie**.\n- **Correction hémodynamique** (remplissage).\n- **Soins locaux** immédiats : **protection**, position **légèrement déclive** (y compris après revascularisation).","cas":[],"pieges":["Débuter l'héparine avant d'avoir prélevé le bilan de coagulation.","Surélever le membre ischémique : la position doit être légèrement déclive."],"src":"p. 182"},{"phase":"Traitement spécifique","title":"Revascularisation","question":"Quelle technique de revascularisation choisis-tu ?","answer":"Adaptée au **grade de sévérité** et au mécanisme :\n\n- **Embolectomie à la sonde de Fogarty** sous contrôle angiographique : **méthode de référence** pour l'**embolie sur artère saine** (utilisable aussi sur artère athéromateuse).\n- **Thrombolyse in situ / thromboaspiration** : si **lit d'aval de mauvaise qualité** et **ischémie peu sévère** (surveillance spécialisée, contrôles angiographiques répétés).\n- **Angioplastie complémentaire** si sténose résiduelle ; **pontage** (souvent distal) en **dernier recours**.\n- **Aponévrotomie de décompression** (loge antéro-externe de jambe en général) **systématique** en cas de **revascularisation tardive** (prévention du syndrome des loges).\n- **Amputation** : **d'emblée** si ischémie dépassée ; **secondairement** si échec de revascularisation ou désordres métaboliques majeurs.","cas":[{"si":"Si embolie sur artère saine (ex. FA)","alors":"**Embolectomie par sonde de Fogarty**."},{"si":"Si lit d'aval de mauvaise qualité et ischémie peu sévère","alors":"**Thrombolyse in situ / thromboaspiration**."},{"si":"Si revascularisation tardive","alors":"**Aponévrotomie de décompression** systématique."},{"si":"Si ischémie aiguë par embolie à partir d'un AAA","alors":"**Revascularisation du membre en urgence** ; la cure de l'AAA est **secondaire**."}],"pieges":["Proposer une thrombolyse in situ à une ischémie sévère avec déficit neurologique.","Oublier l'aponévrotomie après une revascularisation tardive."],"src":"p. 182-183, 186"},{"phase":"Complications","title":"Syndrome des loges et syndrome de revascularisation","question":"Quelles complications crains-tu autour de la revascularisation ?","answer":"**Syndrome des loges** : l'**œdème musculaire** dans les loges aponévrotiques inextensibles peut aboutir à un syndrome des loges → traitement par **aponévrotomie de décharge** (prévention : aponévrotomie systématique si revascularisation tardive).\n\n**Syndrome de revascularisation** (relargage d'acides et de radicaux libres à la reperfusion) :\n\n- **hyperkaliémie** ;\n- **acidose métabolique** ;\n- hyperuricémie ;\n- **myoglobinémie / myoglobinurie** ;\n- hypocalcémie, hyperphosphorémie ;\n- voire **CIVD** ;\n- **insuffisance rénale aiguë** (nécrose tubulaire).","cas":[{"si":"Si désordres métaboliques majeurs","alors":"Envisager une **amputation secondaire**."}],"pieges":["Oublier que le danger métabolique survient à la reperfusion, après le geste."],"src":"p. 178, 182-183"},{"phase":"Hospitalisation & surveillance","title":"Surveillance et correction métabolique","question":"Comment surveilles-tu le patient après revascularisation ?","answer":"- **Diurèse** (sonde urinaire) ;\n- **ionogramme**, **urée**, **créatininémie**, **CPK** ;\n- correction de l'**acidose** : **bicarbonates IV** ;\n- correction de l'**hyperkaliémie** : **chélateur** type **polystyrène sulfonate de sodium**, voire **dialyse** ;\n- **lavage de membre** au sérum physiologique ;\n- **soins locaux** : protection, position légèrement déclive.","cas":[{"si":"Si hyperkaliémie non contrôlée par le chélateur","alors":"**Dialyse**."}],"pieges":["Ne pas doser les CPK et la kaliémie après une revascularisation."],"src":"p. 182-183"},{"phase":"Diagnostic étiologique","title":"Bilan étiologique après revascularisation","question":"Une fois le membre sauvé, quel bilan étiologique complètes-tu ?","answer":"Après revascularisation :\n\n- **bilan cardiaque** : **Holter**, **ETT ± ETO/IRM** (source embolique) ;\n- **bilan artériel** : **échodoppler**, **angioscanner** ou **artériographie** (AOMI, anévrisme, athérome aortique).\n\nL'artériographie peropératoire aura aussi recherché **d'autres emboles**.","cas":[{"si":"Si douleur abdominale aiguë pauvre en signes physiques, vomissements/diarrhée, chez un patient en FA","alors":"Évoquer une **ischémie mésentérique aiguë** (embolie digestive) : diagnostic confirmé par **angioscanner** ; résection des segments infarcis + revascularisation."}],"pieges":["S'arrêter à la revascularisation sans rechercher la source embolique."],"src":"p. 167, 181, 187"},{"phase":"Sortie & ordonnance","title":"Traitement étiologique au long cours","question":"Quel traitement prescris-tu à la sortie ?","answer":"Traitement **étiologique** :\n\n| Mécanisme | Traitement au long cours |\n|---|---|\n| Embolie sur **fibrillation atriale** | **anticoagulation au long cours** |\n| Origine **thrombotique** (AOMI) | **antiplaquettaire** + **contrôle des facteurs de risque** (statine, arrêt du tabac…) |","cas":[],"pieges":["Oublier le traitement étiologique : anticoagulation au long cours si embolie sur fibrillation atriale."],"src":"p. 183"}]},{"title":"Anévrisme de l'aorte abdominale : de la découverte à la rupture","rank":"A","patient":"M. T., 71 ans, fumeur actif, coronarien, consulte pour un bilan systématique. Il est asymptomatique. La palpation abdominale retrouve une masse para-ombilicale battante et expansive.","steps":[{"phase":"Examen clinique","title":"Découverte d'une masse battante","question":"À la palpation abdominale, tu perçois une masse para-ombilicale battante et expansive. Qu'évoques-tu et comment définis-tu un anévrisme ?","answer":"**Anévrisme** = dilatation **localisée et durable** d'une artère, diamètre **> 50 %** de celui du segment sus-jacent, avec **perte du parallélisme** des bords.\n\n- Localisations (hors cerveau) : **aorte** (surtout **sous-rénale**), **poplitées**, **iliaques**.\n- Mécanisme : destruction des fibres élastiques et fragmentation du collagène de la média (métalloprotéases).\n\n**Forme asymptomatique** (la plus fréquente) : découverte à la **palpation** (masse battante et expansive para-ombilicale, ± souffle) ou à l'imagerie.\n\n**Dépistage échographique** recommandé chez l'**homme > 65 ans**, ou plus jeune si FDR (tabac, athérome, ATCD familiaux).\n\n**Épidémiologie** : 2–5 % des hommes > 65 ans ; entre 75–84 ans, 5 % des hommes et 3 % des femmes.","cas":[],"pieges":["Définir l'anévrisme par un diamètre absolu plutôt que par rapport au segment sus-jacent."],"src":"p. 183-184"},{"phase":"Examens complémentaires","title":"Confirmer et mesurer","question":"Quels examens demandes-tu pour confirmer et caractériser l'anévrisme ?","answer":"| Examen | Rôle |\n|---|---|\n| **Échographie abdominale** | **dépistage**, mesure du **diamètre maximal**, **suivi** ; recherche des localisations **poplitées/iliaques** |\n| **Scanner abdominopelvien injecté** | **examen préthérapeutique de référence** (diamètre, anatomie) |\n| IRM | alternative en cas de **contre-indication au scanner** |\n| Artériographie | **inutile** : ne visualise que la lumière circulante, **sous-estime** la taille en cas de thrombus mural |","cas":[{"si":"Si contre-indication au scanner injecté","alors":"**IRM**."}],"pieges":["Demander une artériographie pour mesurer un AAA."],"src":"p. 184-185"},{"phase":"Diagnostic étiologique","title":"Étiologie et lésions associées [B]","question":"Quelle est la cause la plus probable et quelles autres atteintes recherches-tu ?","answer":"- **Athérome** : **80–90 %** des cas (souvent associé à une **AOMI**, une atteinte **coronarienne** ou **carotidienne**).\n- **Formes familiales**, parfois avec maladie du tissu élastique : **Marfan**, **Ehlers-Danlos**, **Loeys-Dietz**.\n- **Aortites** : Takayasu, Horton.\n- Plus rarement **infectieuses** (syphilis, historiquement).\n\n**Autres localisations anévrismales** à rechercher : **poplitées** et **iliaques** (échographie).","cas":[{"si":"Si anévrisme poplité associé (≈ 30 % des AP ont un AAA)","alors":"Rechercher un anévrisme **controlatéral** (bilatéral dans près de la moitié des cas)."},{"si":"Si histoire familiale d'anévrisme","alors":"Forme **familiale**, parfois avec une **maladie du tissu élastique** identifiée (Marfan, Ehlers-Danlos, Loeys-Dietz)."}],"pieges":[],"src":"p. 184, 187"},{"phase":"Évaluation du risque / pronostic","title":"Risque de rupture et risque cardiovasculaire","question":"L'anévrisme mesure 44 mm. Quel est son risque évolutif ?","answer":"**Le diamètre** est le **principal facteur prédictif** de rupture :\n\n| Diamètre | Risque annuel de rupture |\n|---|---|\n| < 40 mm | ≈ **0,4 %/an** |\n| 50–59 mm | **3 %/an** |\n| > 60 mm | **15 %/an** |\n\n- Risque **≈ 4 fois plus élevé chez la femme** à diamètre égal.\n- **Croissance** moyenne **2–4 mm/an** (variable), plus rapide chez l'**homme fumeur** avec anévrisme déjà volumineux (tabagisme actif : progression **≈ 3 fois plus rapide**).\n- ≈ **12 000 décès** par rupture par an en Europe, mais le porteur d'AAA a un risque de **décès CV** (coronaire, AVC) **10 fois supérieur** à celui de rupture.","cas":[{"si":"Si femme","alors":"Risque de rupture **≈ 4 fois plus élevé** à diamètre égal."},{"si":"Si tabagisme actif","alors":"Croissance **≈ 3 fois plus rapide** : arrêt du tabac impératif."}],"pieges":["Oublier que le porteur d'AAA meurt surtout de causes cardiovasculaires, pas de la rupture."],"src":"p. 184-185"},{"phase":"Traitement spécifique","title":"Surveillance de l'AAA asymptomatique [B]","question":"Comment prends-tu en charge cet AAA asymptomatique de petit diamètre ?","answer":"- **Surveillance échographique répétée**, **renforcée tous les 6 mois** si diamètre **> 45 mm**.\n- **Contrôle des facteurs de risque** indispensable pendant le suivi (arrêt du tabac notamment).\n- Prise en charge du **risque cardiovasculaire global** (le risque de décès CV dépasse largement celui de rupture).","cas":[{"si":"Si diamètre > 45 mm","alors":"Surveillance échographique **tous les 6 mois**."}],"pieges":["Négliger l'arrêt du tabac, qui accélère la croissance de l'anévrisme."],"src":"p. 185"},{"phase":"Traitement spécifique","title":"Intervention « à froid » [B]","question":"L'anévrisme atteint 55 mm. Que proposes-tu ?","answer":"Au-delà d'un seuil de **50–55 mm** : intervention **programmée « à froid »**, précédée d'un **scanner injecté** préthérapeutique.\n\n| Technique | Principes |\n|---|---|\n| **Chirurgie conventionnelle** à ciel ouvert | exclusion de la zone anévrismale, **interposition d'une prothèse** |\n| **Traitement endovasculaire** (endoprothèse par voie fémorale) | moins invasif, préféré chez les sujets à **haut risque chirurgical** si **anatomie favorable** ; **surveillance itérative** (scanner, écho de contraste) à la recherche d'**endofuites** |","cas":[{"si":"Si patient à haut risque chirurgical avec anatomie favorable","alors":"**Endoprothèse** préférée."}],"pieges":["Poser une endoprothèse sans prévoir de surveillance au long cours des endofuites."],"src":"p. 185-186"},{"phase":"Accueil & gravité","title":"Rupture d'AAA","question":"Le patient revient aux urgences pour une douleur lombaire brutale avec une PA à 85/50 mmHg. Que fais-tu ?","answer":"**Fissuration / rupture** : douleur **abdominale ou lombaire** ± **choc hémorragique** → **urgence vitale absolue** ; la rupture intrapéritonéale est souvent **cataclysmique**.\n\n- Chez un patient **en choc** : **le scanner ne doit pas retarder l'intervention**.\n- **Traitement endovasculaire** de plus en plus proposé **même en contexte de rupture**, surtout chez le sujet à **très haut risque périopératoire**.","cas":[{"si":"Si patient en choc hémorragique","alors":"**Bloc sans délai** ; ne pas retarder par le scanner."},{"si":"Si sujet à très haut risque périopératoire","alors":"**Endoprothèse** envisageable même en urgence."}],"pieges":["Retarder l'intervention pour un scanner chez un patient en choc.","Se rassurer sur un diamètre < 50 mm : une rupture reste possible."],"src":"p. 184, 186"},{"phase":"Complications","title":"Autres modes de révélation symptomatiques","question":"En dehors de la rupture, quelles complications peuvent révéler un AAA ?","answer":"- **Fistule aorto-cave** → **insuffisance cardiaque à débit élevé** ;\n- **fistule aorto-digestive** → **hémorragie digestive** ;\n- **embolie** à partir d'une **thrombose intra-anévrismale** (ischémie aiguë de membre) ;\n- **compression** des organes de voisinage ;\n- **syndrome inflammatoire** : fièvre, altération de l'état général, élévation VS/CRP.","cas":[{"si":"Si ischémie aiguë de membre par embolie à partir de l'AAA","alors":"**Revascularisation du membre urgente** ; la cure de l'AAA est **secondaire**."}],"pieges":["Traiter l'AAA avant le membre ischémique en cas d'embolie."],"src":"p. 184, 186"},{"phase":"Suivi","title":"Suivi après traitement","question":"Comment surveilles-tu le patient après la cure de l'anévrisme ?","answer":"- **Risque cardiovasculaire persistant** : contrôle des FDR même après traitement réussi.\n- **Après chirurgie conventionnelle** : surveillance **écho-Doppler** (risque de **faux anévrisme anastomotique** ; thrombose exceptionnelle).\n- **Après endoprothèse** : surveillance **scanner/écho au long cours** à la recherche d'**endofuites** (pouvant faire progresser voire rompre l'anévrisme).\n- **Antibioprophylaxie** lors des gestes à risque bactérien (risque infectieux de la prothèse vasculaire).","cas":[{"si":"Si endoprothèse","alors":"Surveillance **itérative au long cours** (scanner, écho de contraste) des endofuites."}],"pieges":["Arrêter la surveillance après endoprothèse : une endofuite peut entraîner une rupture."],"src":"p. 186-187"},{"phase":"Diagnostic étiologique","title":"Anévrisme de l'artère poplitée","question":"L'échographie retrouve aussi une dilatation poplitée. Quelles sont ses particularités et que recherches-tu ?","answer":"- Fréquemment associé à un **AAA** (**≈ 30 %**), **bilatéral** dans près de **la moitié** des cas.\n- Découverte : **masse battante poplitée** (pouls trop bien perçu), écho-Doppler systématique (**dépistage si AAA ou AP controlatéral** connu), ou tableau d'artériopathie progressive, voire d'ischémie aiguë.","cas":[],"pieges":["Oublier de rechercher un AAA (≈ 30 %) et un anévrisme poplité controlatéral (bilatéral une fois sur deux)."],"src":"p. 186"}]}],"examens":[{"theme":"Explorations fonctionnelles","title":"Index de pression systolique (IPS)","rank":"A","content":"#### Indications\n- **Examen de 1re intention** devant une suspicion d'**AOMI**.\n\n#### Technique\n- Rapport **pression systolique de cheville / pression systolique brachiale**, mesuré au **doppler de poche**.\n\n#### Interprétation\n| IPS | Signification |\n|---|---|\n| **1,00–1,40** | normal |\n| **< 0,90** (au moins une cheville) | **AOMI** |\n| **< 0,70** | **AOMI sévère** |\n| **> 1,40** | **médiacalcose** |\n\n- Un IPS abaissé est aussi un **marqueur de risque cardiovasculaire global**.\n- **Ischémie critique** : pression de **cheville < 50 mmHg** (ou d'hallux < 30 mmHg).\n\n#### Pièges\n- **IPS > 1,40** (médiacalcose) → le remplacer par l'**index de pression d'orteil**.\n- Symptômes avec **IPS de repos normal** → **test de marche**.","src":"p. 169-171"},{"theme":"Explorations fonctionnelles","title":"Index de pression d'orteil / pression d'orteil","rank":"A","content":"#### Indications\n- **Médiacalcose** (IPS > 1,40) : remplace l'IPS.\n\n#### Interprétation\n- **Index de pression d'orteil pathologique si < 0,70**.\n- **Pression d'orteil (hallux) < 30 mmHg** = **ischémie critique**.","src":"p. 169-171"},{"theme":"Explorations fonctionnelles","title":"Test de marche sur tapis roulant (Strandness)","rank":"A","content":"#### Indications\n- **Symptômes** évocateurs avec **IPS de repos normal** : sensibilise le diagnostic d'AOMI.\n\n#### Technique\n- Tapis roulant, **protocole de Strandness** : **3,2 km/h, pente 10 %**.\n\n#### Interprétation (évocateur d'AOMI)\n- Baisse de la **pression de cheville > 30 mmHg** après l'effort.\n- Baisse de l'**IPS > 20 %** après l'effort.","src":"p. 171"},{"theme":"Explorations fonctionnelles","title":"Test de marche de 6 minutes","rank":"A","content":"#### Indications\n- Évaluer le **handicap fonctionnel global**.\n\n#### Limites\n- **Non spécifique**.","src":"p. 171"},{"theme":"Explorations fonctionnelles","title":"Pression transcutanée en oxygène (TcPO2)","rank":"A","content":"#### Indications\n- **Ischémie critique** (mesure après hyperémie).\n- Guide le niveau d'**amputation** (zone saine et bien oxygénée).\n\n#### Interprétation (dos du pied)\n| TcPO2 | Signification |\n|---|---|\n| **> 50 mmHg** | normale |\n| > 35 mmHg | bonne compensation |\n| 10–35 mmHg | hypoxie continue |\n| **< 10 mmHg** | **hypoxie critique** |","src":"p. 171-172, 176"},{"theme":"Imagerie","title":"Échodoppler artériel des membres inférieurs","rank":"A","content":"#### Indications\n- **Examen d'imagerie de 1re intention** de l'AOMI : **non invasif**, **localise et quantifie** les sténoses.\n- **Surveillance systématique après revascularisation** (avec la clinique).\n- **Ischémie aiguë** : réalisable **sans perte de temps** si le tableau le permet (**grade I sans atteinte neurologique**) ; bilan artériel étiologique **après revascularisation**.\n- **Anévrisme poplité** : découverte par écho-Doppler systématique ; **dépistage si AAA ou AP controlatéral** connu.\n- **Après chirurgie conventionnelle d'AAA** : surveillance (faux anévrisme anastomotique, thrombose exceptionnelle).\n\n#### Pièges\n- En ischémie aiguë avec **déficit neurologique** (grade II), **aucune exploration ne doit retarder** l'intervention.","src":"p. 172, 176, 180-182, 186-187"},{"theme":"Imagerie","title":"Angioscanner des membres inférieurs","rank":"A","content":"#### Indications\n- **Uniquement en vue d'une revascularisation** (AOMI).\n- **Ischémie aiguë** : bilan artériel étiologique **après revascularisation** (ou artériographie).\n\n#### Performances\n- Sensibilité/spécificité **≈ 95 %** vs artériographie.","src":"p. 172-173, 181-182"},{"theme":"Imagerie","title":"Angio-IRM / IRM","rank":"A","content":"#### Indications\n- **AOMI** : **uniquement en vue d'une revascularisation**.\n- **Ischémie mésentérique chronique** : diagnostic (avec écho-Doppler digestif, angioscanner).\n- **AAA** : **alternative** en cas de **contre-indication au scanner**.\n- **Ischémie aiguë** : bilan cardiaque après revascularisation (**ETT ± ETO/IRM**).\n\n#### Performances / limites\n- Sensibilité/spécificité **≈ 95 %** vs artériographie.\n- **Ne visualise pas les calcifications** (utiles au chirurgien).\n\n#### Contre-indications\n- **Gadolinium contre-indiqué** si clairance **< 30 mL/min/1,73 m²**.","src":"p. 166, 172-173, 182, 185"},{"theme":"Imagerie","title":"Artériographie","rank":"A","content":"#### Indications\n- **AOMI** : **réservée aux procédures de revascularisation**, notamment pour le **réseau jambier et pédieux**.\n- **Ischémie aiguë** : le plus souvent **au bloc** pour guider le geste (localisation, aspect de l'occlusion, qualité du réseau d'aval) et **dépister d'autres emboles** ; contrôle de l'embolectomie (**sous contrôle angiographique**) ; contrôles répétés en thrombolyse in situ.\n- **Ischémie mésentérique chronique** : réalisée **seulement pour un geste endovasculaire**.\n\n#### Limites\n- **AAA** : **pas utile** — ne visualise que la **lumière circulante** et **sous-estime la taille** en cas de **thrombus mural**.","src":"p. 166, 173, 180-182, 185"},{"theme":"Imagerie","title":"Angioscanner abdominal (artères digestives)","rank":"A","content":"#### Indications\n- **Ischémie mésentérique aiguë** : **examen de référence**.\n- **Ischémie mésentérique chronique** : diagnostic (avec écho-Doppler digestif, angio-IRM).","src":"p. 166"},{"theme":"Imagerie","title":"Écho-Doppler digestif","rank":"A","content":"#### Indications\n- Diagnostic de l'**ischémie mésentérique chronique** (sténose du tronc cœliaque et/ou des artères mésentériques), avec angioscanner ou angio-IRM.","src":"p. 166"},{"theme":"Imagerie","title":"Échographie abdominale (AAA)","rank":"A","content":"#### Indications\n- **Dépistage** : recommandé chez l'**homme > 65 ans**, ou plus jeune si facteurs de risque (tabac, athérome, antécédents familiaux).\n- **Mesure du diamètre maximal** et **suivi** de l'AAA ; recherche des localisations **poplitées/iliaques** associées.\n\n#### Rythme de surveillance [B]\n- Surveillance échographique répétée, **renforcée tous les 6 mois** si diamètre **> 45 mm**.\n- Intervention « à froid » au-delà de **50–55 mm**.\n\n#### Interprétation (risque annuel de rupture)\n| Diamètre | Rupture/an |\n|---|---|\n| < 40 mm | ≈ 0,4 % |\n| 50–59 mm | 3 % |\n| > 60 mm | 15 % |\n\n- Risque **≈ 4 fois plus élevé chez la femme** à diamètre égal.\n- Croissance moyenne **2–4 mm/an** ; environ **3 fois plus rapide** en cas de tabagisme actif.","src":"p. 184-186"},{"theme":"Imagerie","title":"Scanner abdominopelvien injecté (angioscanner aortique)","rank":"A","content":"#### Indications\n- **Examen préthérapeutique de référence** de l'AAA (diamètre, anatomie).\n- **Surveillance après endoprothèse** (scanner, écho de contraste) : recherche d'**endofuites**.\n- AAA **rompu** (urgence absolue) : le scanner confirme le diagnostic mais **ne doit pas retarder l'intervention** chez un patient **en choc**.\n\n#### Contre-indications\n- En cas de contre-indication au scanner → **IRM**.","src":"p. 185-186"},{"theme":"ECG & explorations électriques","title":"ECG et Holter (ischémie aiguë de membre)","rank":"A","content":"#### Indications\n- **ECG** : **bilan étiologique systématique** d'une ischémie aiguë (avec auscultation cardiaque, palpation abdominale, bilan de coagulation).\n- **Holter** : bilan cardiaque **après revascularisation**.\n\n#### Ce qu'on recherche\n- Cause **emboligène** : **fibrillation atriale** (principale cause cardiaque d'embolie artérielle des membres).","src":"p. 181-182"},{"theme":"Imagerie","title":"Échocardiographie (ETT ± ETO) – ischémie aiguë de membre","rank":"A","content":"#### Indications\n- **Bilan cardiaque après revascularisation** d'une ischémie aiguë : **ETT ± ETO/IRM**.\n\n#### Ce qu'on recherche (causes cardiaques d'embolie)\n- Foramen ovale perméable / anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, **myxome de l'atrium**, anévrisme/dyskinésie du VG.","src":"p. 181-182"},{"theme":"Biologie","title":"Bilan de coagulation et TCA sous héparine","rank":"A","content":"#### Indications\n- **Bilan de coagulation** : partie du bilan étiologique systématique de l'ischémie aiguë ; **prélevé avant** l'anticoagulation.\n- **Surveillance** de l'HNF.\n\n#### Protocole\n- **HNF** dès le diagnostic : **bolus 5000 UI** puis **perfusion 500 UI/kg/j**.\n- **TCA cible entre 2 et 3**.","src":"p. 182"},{"theme":"Biologie","title":"Surveillance métabolique (syndrome de revascularisation)","rank":"A","content":"#### Indications\n- Ischémie aiguë, notamment après **reperfusion** : surveillance de la **diurèse** (sonde urinaire), **ionogramme**, **urée**, **créatininémie**, **CPK**.\n\n#### Ce qu'on recherche\n- **Hyperkaliémie**, **acidose métabolique**, hyperuricémie, **myoglobinémie/myoglobinurie**, hypocalcémie, hyperphosphorémie, voire **CIVD**.\n- **Insuffisance rénale aiguë** (nécrose tubulaire) ; **rhabdomyolyse** (cellules musculaires dès 6–8 h).\n\n#### Conséquences\n- Correction de l'acidose (**bicarbonates IV**), de l'hyperkaliémie (chélateur type **polystyrène sulfonate de sodium**, voire **dialyse**), lavage de membre au sérum physiologique.","src":"p. 178, 183"},{"theme":"Biologie","title":"Cibles biologiques de l'AOMI (HbA1c, LDL-C)","rank":"A","content":"#### Cibles\n- **HbA1c < 7 %**.\n- **LDL-cholestérol < 0,55 g/L (< 1,4 mmol/L)** avec réduction **≥ 50 %** sous **statine** systématique.","src":"p. 175"},{"theme":"Biologie","title":"VS / CRP (AAA inflammatoire)","rank":"A","content":"#### Interprétation\n- Un AAA peut se révéler par un **syndrome inflammatoire** : fièvre, altération de l'état général, **élévation de la VS/CRP**.","src":"p. 184"},{"theme":"Gestes & procédures","title":"Angioplastie endovasculaire des membres inférieurs","rank":"A","content":"#### Indications\n- Revascularisation **systématiquement proposée** en **ischémie permanente** ; **discutée** en **claudication sévère invalidante** (périmètre < 100 m), notamment après échec du traitement médical.\n- Lésions **courtes/proximales**.\n- Ischémie aiguë : angioplastie **complémentaire** en cas de **sténose résiduelle**.\n\n#### Modalités\n- **± stent**, **bithérapie antiplaquettaire 1 à 6 mois**.\n- **Surveillance clinique et écho-Doppler systématique** après le geste.","src":"p. 176, 182"},{"theme":"Gestes & procédures","title":"Revascularisation chirurgicale (pontage, endartériectomie)","rank":"A","content":"#### Indications\n- **Lésions étendues** (AOMI) ; techniques **hybrides** possibles.\n- Ischémie aiguë : **pontage** (souvent distal) **en dernier recours**.\n\n#### Modalités\n- **Pontage veineux ou prothétique**, **endartériectomie**.\n- **Surveillance clinique et écho-Doppler systématique** après le geste.","src":"p. 176, 182, 187"},{"theme":"Gestes & procédures","title":"Embolectomie à la sonde de Fogarty","rank":"A","content":"#### Indications\n- **Méthode de référence** de l'ischémie aiguë par **embolie sur artère saine** (utilisable aussi sur artère athéromateuse).\n\n#### Modalités\n- **Sous contrôle angiographique**.","src":"p. 182"},{"theme":"Gestes & procédures","title":"Thrombolyse in situ / thromboaspiration","rank":"A","content":"#### Indications\n- Ischémie aiguë avec **lit d'aval de mauvaise qualité** et ischémie **peu sévère**.\n\n#### Précautions\n- **Surveillance spécialisée**, **contrôles angiographiques répétés**.","src":"p. 182"},{"theme":"Gestes & procédures","title":"Aponévrotomie de décompression","rank":"A","content":"#### Indications\n- **Syndrome des loges** (œdème musculaire dans des loges aponévrotiques inextensibles).\n- **Systématique** en cas de **revascularisation tardive**, pour prévenir le syndrome des loges.\n\n#### Modalités\n- Loge **antéro-externe de jambe** en général.","src":"p. 178, 183"},{"theme":"Gestes & procédures","title":"Amputation","rank":"A","content":"#### Indications\n- **AOMI** : **en dernier recours**.\n- **Ischémie aiguë** : **d'emblée** si ischémie **dépassée** ; **secondairement** si échec de revascularisation / désordres métaboliques majeurs.\n\n#### Modalités\n- En **zone saine et bien oxygénée**, guidée par la **TcPO2**.","src":"p. 176, 179, 183"},{"theme":"Gestes & procédures","title":"Chirurgie conventionnelle de l'AAA","rank":"B","content":"#### Indications\n- AAA asymptomatique au-delà de **50–55 mm** : intervention « à froid ».\n\n#### Modalités\n- À ciel ouvert : **exclusion de la zone anévrismale**, **interposition d'une prothèse**.\n\n#### Complications / suivi\n- Surveillance **écho-Doppler** : **faux anévrisme anastomotique**, thrombose exceptionnelle.\n- Risque **infectieux** de la prothèse → **antibioprophylaxie** lors des gestes à risque bactérien.","src":"p. 185-187"},{"theme":"Gestes & procédures","title":"Endoprothèse aortique (traitement endovasculaire de l'AAA)","rank":"B","content":"#### Indications\n- AAA > **50–55 mm** : **moins invasif**, préféré chez les sujets **à haut risque chirurgical** si l'**anatomie est favorable**.\n- De plus en plus proposé **même en contexte de rupture**, surtout chez le sujet à très haut risque périopératoire.\n\n#### Modalités\n- **Voie fémorale**.\n\n#### Complications / suivi\n- Surveillance **itérative au long cours** (**scanner**, **écho de contraste**) à la recherche d'**endofuites**, pouvant faire progresser voire **rompre** l'anévrisme.\n- Antibioprophylaxie lors des gestes à risque bactérien (prothèse vasculaire).","src":"p. 185-187"},{"theme":"Gestes & procédures","title":"Revascularisation des artères digestives","rank":"A","content":"#### Indications\n- **Ischémie mésentérique chronique** symptomatique : revascularisation **de préférence endovasculaire**.\n- **Ischémie mésentérique aiguë** : **résection** des segments intestinaux infarcis + revascularisation (**endovasculaire ou chirurgicale**).","src":"p. 166-167, 187"}]}});
